window.CHAPTER_DATA["ch42"]={"id": "ch42", "num": 42, "part": "תחומין", "title": "יוצא חוץ לתחום", "paras": [{"s": "h2", "h": "יוצא חוץ לתחום"}, {"s": "h3", "h": "א. שביתת ד' אמות מול תחומין וגדרי אוויר מחיצות"}, {"s": "h7", "h": "הבדל שביתת ד' אמות מתחומין - שביתה במקום מול שביתה למקום ושילובם ביוצא חוץ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1586\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">2\u003c/sup>\u003csup class=\"cb\" data-c=\"1585\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"1585 1586\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">הנה כמו שכתבנו שני דינים אלו שביתה דד\"א ושביתה דתחומין, תרי שביתות הן. דד\"א הוא שביתה במקום, ושביתה דתחומין הוא שביתה למקום. ששביתת ד\"א, היינו, שמקום אדם אינו רק במקום שעומד, אלא בכלל ד\"א שסביבו. אבל שביתה דתחומין אינה שביתה אלא במקום עומדו, אלא שלגבי מה שנחשיב שיצא ממקום זה, כל עוד הוא בתוך התחומין הרי שלא יצא. וע\"כ נמצא שאף במקום שלא נתנו לו חכמים רק ד\"א, יהיה לד\"א אלו שני גדרים, גם שביתה דד\"א, וגם תחומין. וכאילו גזרו שיהיה תחומו קטן, ובד\"א.\u003c/span>"}, {"s": "h7", "h": "אחידות מקום באוויר מחיצות - היות המקום כאחד לתחומין תלוי בשביתה מבעוד יום"}, {"s": "p", "h": "והנה לבאר יותר נקדים מה שמצאנו חילוקי גדרים באחידות מקום, ונמצאם בדין שבת באוויר מחיצות מבעוד יום, והיינו, שאף שיהיה חשוב מקום זה אחד לגבי שאר דברים, ויותר דאף לגבי תחומין יהיה נחשב אחד, למי ששבת שם מבעוד יום. לגבי מי שלא שבת בו מבעוד יום אין נחשב לו המקום אחד, ולא מיבעי דלגבי אלפים לא חשיבא כולה כחד, אלא אפילו לגבי שביתה דד\"א לא חשיבא כחד. והיינו, שהיה לומר דכיון שכל המקום אחד לא יחשב יציאה חוץ לאלפים בו, ליציאה, וכן שהיה לומר דכיון שכל המקום אחד יחשב השובת שם כשובת בכל המקום, ושיהיה לו אלפים חוץ ממנה, ושניהם אינם. וכן במי שהגיע סוף תחומו לאמצע מערה, שלא נחשב מקום לאחד משום תחומין, ואף שמקום המערה אחד הוא, יהיה נחשב יוצא."}, {"s": "h7", "h": "עיר שכולה בתוך תחומו - נחשבת לו כד' אמות אף שלא שבת באוויר מחיצותיה"}, {"s": "p", "h": "אלא שצ\"ב גדר זה שהרי מצאנו שהמודד ובא לעיר שנמצאת כולה בתחומו נחשבת לו כד\"א, ומשמע דאף לגבי תחומין נחשב המקום לאחד, ואף שלא שבת באוויר מחיצותיה. והיינו, שרהיטת הדברים לומר שגדר מה שלא נחשב מקום המוקף מחיצות לחד לגבי תחומין, הוא משום שאין אלפיים מותרים משום שנחשבים מקום אחד כולם, אלא המקום הוא רק במקום השביתה, ואלפיים הוא משום מרחק ממקום זה שנחשב יציאה, וע\"כ לא יועיל מה שסוף תחומו נמצא במקום אחד כאמצע מערה, אחר שכבר התרחק ממקומו. אלא דזה קשה דא\"כ כך היה לדון גם בעיר הנמצאת בתוך תחומו, דאם שיעור אלפיים הוא בגדר מרחק ממקום, מה מועילה לזה העיר שהיא כאחד לעצמה."}, {"s": "h7", "h": "ספק אי איתא לתחומין למעלה מי' - חילוק רשות קרקע גמורה מקרקע כללית"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"660\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">3\u003c/sup>\u003cspan class=\"ca\" data-c=\"660\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והנה נסתפקו בגמ' אי איתא לתחומין למעלה מי', וסייגו דבעמוד שהוא רחב ארבעה לא תיבעי לך דאיתא לתחומין, דהוה כארעא סמיכתא, והיינו, שגדר מה שנסתפקו בלמעלה מי' הוא משום חסרון שיש בזה דלא הוי רשות דקרקע, אבל אין הכוונה דאוויר למטה מי' הוי רשות דקרקע שתחתיה אלא קרקע כל שתהיה, וע\"כ אף שמקום גבוה עשרה ודאי אינו נחשב חלק מהקרקע שלידו, אבל לגבי הגדרת קרקע סתם חשובים שניהם נחשבים קרקע אחת. והיינו, שאף שלגבי שטח שאינו מוקף מחיצות, מקומות שאינם בתוך עשרה טפחים אינם נחשבים מקום אחד, אין זה אלא לגבי הגדרה נוספת שיש בהם, היינו, שבאם נבחנם לומר שהם רשות אחת, הרי הם חלוקים. אבל לגבי גדר קרקע עצמה אין בגובה י\"ט לומר שאין זה קרקע, והא דבדיני רשויות יש בי\"ט הפרדה, הוא משום שדינים אלו נוגעים להגדרת מקומות מופרדים, היינו, ההבדלים שיש בין רשות אחת לשניה, ולשאינה, וזה גדר מפריד, היינו, שהוא מתייחס לחלוקת קרקעות זה מזה, וכיון שהוא תלוי בקרקע הוי עשרה טפחים שיעור נפרדות לגבי קרקע. אבל אם יהיה גדר הדין במה שאינו נוגע למקומות נפרדים, אין שום גריעותא במה שאין המקום אחד. וכן הוא לגבי תחומין שאין גדר אלפיים דתחומין הגדרת מקום לעצמו, היינו, אלפיים אלו, אלא גדרם הוא ביחס למקום אחר, היינו, מקומו של אדם.\u003c/span>"}, {"s": "h7", "h": "חלקי קרקע כאחד במדידת תחום - חילוק בין דיני חלוקת רשויות למדידת מרחק תחומין"}, {"s": "p", "h": "וע\"כ יהיו כל חלקי קרקעות אחד לגבי זה, ויש במדידת מרחק לכלול כל חלקי הקרקעות, ואלף בזה ואלף בזה יהיו אחד לענין מדידת אלפים, וע\"כ כל שיש להחשיבו כקרקע יחשב לענין זה, אבל במקום שאינו רחב ארבעה, ואין הוא מוגדר כקרקע לעצמו, יש לדון אם נחשב כנ\"ל לענין מרחק אלפים, ואם יהיה בתוך עשרה לא מיבעי לן אף שאין הוא קרקע לעצמו, כיון דלית ביה ד\"ט הרי הוא ברשות דקרקע עולם, והיינו, דאף דלגבי רשויות כל שגבוה ג' כבר אינו נחשב חלק מקרקע שלידו, הכא לא הוי חלוקה, וכמשנ\"ת דחלוקה הנ\"ל חשובה רק לגבי הגדרת רשות דקרקע שהוא גדר מפריד, היינו, להחשיב קרקע מסויימת, שאין גדרה רק קרקע, אלא ביחס לרשות אחת, ויש בגובה ג' להפריד. אבל לגבי קרקע כללית, וביחס להגדרה שאינה תלויה בקרקע שנצטרך להגדיר חילוק קרקעות, אין בגובה ג' כדי להפריד, ויחשב כחלק מהקרקע (והוה כמו עמוד תשעה), וכן הוא בתחומין, שאמנם גדר תחומין הוא ביחס להליכה, ובאינו רחב ד' אינו חשוב מקום הילוך, אבל הרי אין אנו צריכים להגדיר מקום הילוך, אלא הילוך שיש בו התרחקות ממקום, אלא דכיון שאף מקומו, היינו, נקודת שביתתו שממנה מודד אלפיים הרי היא בקרקע, יש לדון אם דבר שאינו קרקע ולא רשות קרקע, יש לו יחס מרחק לקרקע הנ\"ל. וכן מי ששבת במקום כזה, אם נחשב שביתה לגבי תחומין שנחשב מרחק אלפיים מנקודה זו."}, {"s": "h7", "h": "גדר מרחק אלפיים אמה בתחומין - שיעור המקום שיש בו התרחקות ולא מרחק מנקודה"}, {"s": "p", "h": "והביאור בזה, כי אין מרחק דאלפים אמה כגדר התרחקות מדבר סתם, היינו, שנחשיב מקום שביתתו כנקודה שאין להתרחק ממנה, שבזה הרי היה לומר שאף התרחקות בגובה הוה התרחקות, ואם יעלה השמימה אלפיים גם הרי התרחק. וזה אינו, שאין מקומו דבר, אלא מקום, ואין מקום אלא בקרקע, וע\"כ לא תהיה התרחקות ממנה בהיעלמות, אלא בהצטבר מקום שיש בו התרחקות. וע\"כ יהיה אלפיים כמות מקום, שהנמצא חוץ לה הרי שנחשב שהתרחק, משום שעתה בכדי לחזור למקומו יש לו להלך את כל המקום הנ\"ל, והוה כמו חציצה בינו לבין מקומו, והיינו, יציאה האמורה בפסוק, היינו, היותו במקום שהגעה ממנו למקומו יש בה גדר נוסף לבד ממרחק הליכה סתם, וזה בהיות המרחק מכיל מקום שיש בו גדר התרחקות סתם, והיינו חוץ האמור בלימוד דאלפיים. וגדר זה הוא כמו שנאמר שמי שנמצא בתוך מקום זה, אין זה נחשב שבטל ממנו שם המקום ההוא, ואף שאין הוא המקום הנ\"ל, אבל עדיין יש לו שייכות עם המקום שנאמר שנחשב חוץ לזה, שסתם מקום שאין לו שייכות למקום זה, אינו נחשב חוץ לזה, ואין לומר במי שנמצא בארץ אחרת שהוא חוץ לאיזה ביתו שבארץ זו, אלא הוא מקום לעצמו שאינו מקום זה, ומקום שיש להחשיבו כחוץ למקום מסויים, הרי זה משום שעדיין יש בו שייכות לאותו מקום. אלא שזה שייך רק במה שיש להחשיבו באותו הגדר כמו המקום המסויים, אבל אין לומר שהעולה מעלה באוויר שיצא מעיר מסויימת, אלא אין הוא כלל בארץ, ואין זה יציאה ממקומו, אלא יציאה ממקום בכלל, וזה מה דבעו בתחומין למעלה מעשרה, היינו, רשות תחתית (וכמו מה שאמרו שלא ירדה שכינה לארץ, והיינו, שאין בשלילה זו להרחיק השכינה ממקום מסויים כמו המשכן, אלא הרחקה מהארץ בכלל שאינה ראויה להשראת שכינה, או שאין ראוי לשכינה לשכון שם). אבל אין זה גדר בהילוך, שהרי אין להגדיר הילוך בקרקע במי שמרחף מעל ג\"ט דקרקע, ואין צריך לי\"ט לבטל שם הילוך הנ\"ל מקרקע שתחתיו, אלא דכמו שאמרנו הרי אין הילוך האמור בקרקע מסויימת, אלא בקרקע כללית כמו ארץ, והיינו, במה שיש להחשיב את התקדמותו ביחס לקרקע."}, {"s": "h7", "h": "כלתה מידתו בעיר מול מערה - חשיבות חיובית של עיר לעומת גדר שלילי במערה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"661\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"661\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ובזה יש לדון אם מי שמתקדם מעל עשרה יש לו משמעות שמתקדם ביחס לקרקע שתחתיו, או כיון דעל על, ובזה יבואר חילוק בין כלתה מידתו בחצי לכלתה באמצע, והיינו, שיש במי שכלתה מידתו בסוף העיר להגדיר את התקדמותו ביחס למרחק ממקומו כאי התקדמות משום גדר אחיד שיש למקום העיר, וזה בחשיבות חיובית שיש לעיר להגדיר שלילת חשיבות לגבי התקדמותו, והיינו, דאף מה שאמרנו שגדר יציאה שיש בהיותו במקום שאין להחשיבו כחוץ דמקומו, הוא בדבר שיש להחשיבו כחוץ, ואין עיר נחשבת חוץ, אבל זה רק בעיר שיש להחשיבה ביחס למקומו, והיינו, שכולה בתוך אלפיים, שאחר שהיא בתוך חוץ למקומו, והרי אין היא נחשבת ממין החוץ, אזי יש להחשיבה כפנים במובנו החיובי. וכיון שכן הרי שגדרה האחיד יחשב ככזה גם לענין חוץ דמקומו, אבל בכלתה מידתו בחצי עיר הרי שאין היא נחשבת לגבי חוץ דיליה וכו'.\u003c/span>"}, {"s": "h7", "h": "גדר ד' אמות שחוץ לאלפיים - תלותן בקביעת האלפיים ובשביתה מבעוד יום באוויר מחיצות"}, {"s": "p", "h": "ומעתה יש לבאר ביתר ביאור גדר דד\"א האמור חוץ לאלפיים, והיינו, שכמו שאמרנו דאלפיים הם מה שנחשבים חוץ דנקודת מקומו, ויש במקום גדר יותר מאלפיים, שאין הן משום חוץ אלא משום מקומו, ואמנם כמו שאמרנו אין גדר דחוץ תלוי בגדר המקום עצמו, היינו, בכלתה מידתו בחצי מערה, שאף שמערה לעצמה נחשבת כמקום אחד, אין זה עניין לגדר מקום חוץ דנקודת מקומו, אבל לגבי מקומו ודאי שמה שנחשב למקום אחד, באם יהיה מקום ההוא מקומו, יהיה גדר זה בכל המקום, והוא כגדר שלילי לגבי חוץ דאלפיים, כי אין להחשיבו כתחילת חוץ. אבל כיון שזה ביחס לאלפיים, ומה שיש להחשיב המקום כולו כנקודת מקומו למדידת אלפיים, הרי שזה תלוי באלפיים, וכיון שאלפיים הנ\"ל כבר נקבעו, לא יועיל מה שעתה הוא באוויר מחיצות אם לא שבת שם, כיון שאין גדר זה אלא ביחס לאלפיים, וכבר נקבעו. אבל אם שבת באוויר מחיצות, הרי שיש להחשיב כל המקום בעל המחיצות כמקום שביתה שלו, היינו, נקודה שממנה יש למדוד אלפיים דחוץ."}, {"s": "h7", "h": "גדר אוויר מחיצות בתחומין - דיני תחומין תלויים במקומו של אדם ולא בקרקע"}, {"s": "p", "h": "ובזה יבואר שם אוויר מחיצות, והיינו, שאין גדר מה שנחשב מקומו בכל המקום המוקף משום גדר הקרקע עצמה, ומה שנקודת שביתתו בקרקע שאין בה חלוקה משום מחיצות המקיפות אותה, שאין שייכות בין דיני תחומין לדיני מקומות המחולקים, שכמו שאמרנו אין דיני תחומין ביחס למקום בכלל אלא ביחס למקומו של אדם מסויים."}, {"s": "h7", "h": "חילוק מלאכת הוצאה מיציאת תחומין - הוצאה תלויה במקום חפץ ותחומין במקום האדם עצמו"}, {"s": "p", "h": "(ויותר מזה שאין גדר יציאה דתחומין משום העברה שיש באדם ממקום למקום, שהרי אין מקום שאין לצאת ממנו אלא במקומו של אדם, ומה שייך לומר שאין לצאת ממקומו, והרי כל מקום שיהיה הוא מקומו, וביתר ביאור החילוק בין הוצאת חפץ דמלאכת הוצאה ליציאת אדם חוץ לתחום, שגדר מקום האמור לגבי הוצאה אין הוא ביחס למקום חפץ אלא ביחס למקום אדם, וע\"כ שייך שיהיה שם העברה ד\"א ברשות הרבים, והוצאה והכנסה, אף שכל מקום שינוח החפץ הרי הוא מקומו, כיון שאין גדר הוצאה במקום חפץ עצמו, אלא ביחס למקום שנחשב לאדם. ובזה יהיה הבדל בין רה\"י לרה\"ר, וד\"א ברה\"ר, אבל ביציאת אדם כזאת לא יהיה איסור, היינו, ביוצא מרה\"י לרה\"ר (ועוד שלא יהיה גדר הוצאה במלבושיו מחמתו וכו'). ואף אי ס\"ל דאין חי נושא את עצמו ואפ' באדם, שיציאת אדם היא חשיבות ברשות ולא חשיבות בו. וע\"כ לא יועיל מה שנחשב המקום לאחד לגבי תחומין שהוא ביציאת אדם, והיינו, שגדר הוצאה הוא ביחס למה שנחשב מקום דבר, חשיבות בדבר, ובשינוי מקום יחשב שינוי חשיבות, אבל בתחומין גדר מקומו הוא במה שיש חשיבות בהישארות במקום אחד (ובאם היה גדר זה גם בהוצאה היה נאסר להוציא אפ' מרה\"י לכרמלית. והבן) לענין שביתה דשבת. וע\"כ לא יהיה חשיבות במה שהמקום אחד לעצמו אלא במה שהוא נחשב אחד לענין מקומו, וזה רק בזמן קניית תחומין, דכיון שיש במקום המוקף גדר ישיבה אחת לענין שאינו נחשב חוץ דהאי ישיבה, והיינו, אוויר מחיצות. שאף אמנם דלגבי רשויות דשבת אין גדר באוויר מחיצות אלא ביחס לשימוש ולא ביחס לקרקע, אבל גדר ישיבה דתחומין הרי הם גדר דשימוש, ולא גדר מקום, והיינו, שמה שנחשב מקומו של אדם הוא לא במה שהוא מונח בקרקע זו, שאין הוא חפץ שיש להחשיב מקומו ביחס לקרקע שמונח עליה, אלא ביחס לשימוש במקום, והיינו, אוויר מחיצות, שיש במחיצות להגדיר שימוש הנעשה באווירן כשימוש אחד, וכיון שישיבה דאדם הוא בגדר שימוש, הרי שיש באיחוד אוויר שימוש שנעשה ע\"י מחיצות להגדיר ישיבה בכל המקום. וזה הגדר רק בישיבה, והיינו, שכיון שגדר ישיבה אין היא שימוש עצמו אלא הכנה לשימוש, והרי שגדר ישיבה הוא ביחס לשימוש קבוע, ומקום שיש להחשיב שימושים שבו לשימוש במקום אחד, גם קביעת מקום שימוש תחשב קביעה בכל המקום. אבל אחר שקנה תחומין כבר נקבעה ישיבתו ותחומיו, ואין מקום אחיד שאינו מקומו, מועיל לעניין תחומין דמקום אחר, שאין מקום דתחומין גדר דשימוש קבוע, שהרי אין זה אלא גבול מקומו, ולא מקומו ממש. אבל במי שהוציאוהו חוץ לתחום, אף אמנם שאין לו לקנות תחום חדש, אבל כיון שיש לו לקנות ארבע אמות דישיבת מקום, הרי זה כאילו יש לו לקבוע מקומו מחדש, והוי כמו מי ששבת מבעוד יום, וכשבת באוויר מחיצות, דכיון שאין להחשיב שימוש דד\"א הללו שנתנו לו כחלק משימוש אחר, הרי שקובעים הם שימוש לעצמם, והיינו קולא שהקלו חכ', ביצא שלא לדעתו שנתנו לו המקום שיצא לשם להחשב כמקום קבוע)."}, {"s": "h3", "h": "ב. מחלוקת התנאים בדין ספינה וסוגיית רגלך"}, {"s": "h7", "h": "מחלוקת התנאים בדין ספינה בשבת - חילוק בין ר\"ג וראב\"ע לר' יהושע ור' עקיבא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"662\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"662\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ולכאורה נראה דבזה נחלקו ר\"ג וראב\"ע עם ר\"י ור\"ע, דסבר ר\"ג שגדר מה שנתנו לו חכ' הוא כמו ישיבה דתחומין בלי התחום, ור\"ע סבר שלא נתנו לו אלא ארבע אמות דשימוש שאינו קבוע, ומה שיש לאדם להגדיר ארבע אמות דידיה בפועל, וכמו גדר דתחתיו. וזהו מה שכתב תוס' במח' רבה ור' זירא בסברת שמואל שהלכה כר\"ג רק בספינה, שאין די בסברת ר\"י ור\"ע, דכיון שס\"ל כר\"ג בספינה הרי שנתנו לו ארבע אמות דישיבת תחום, ולא רק ארבע אמות דתחתיו, א\"כ יקשה מאי שנא דבספינה נתנו לו ובדיר וסהר לא נתנו לו. ואמרו שם בגמ' כמה דעות בסברת ספינה, דרבה סבר שהוי משום דשבת באוויר מחיצות, ור' זירא סבר משום שספינה נוטלתו מתחילת ארבע ומניחתו בסוף ארבע, ורבה סבר שסברת ר' זירא שייך גם לר\"י ור\"ע, ור' זירא לא סבר כן, ור' זירא סבר דלא מהני אוויר מחיצות דספינה, כיוון דלהבריח מים עשויות, ורבה חלק. ושניהם דברו אפילו לדעת שמואל דס\"ל לקמן דלגבי היקף לדירה דבמה שעשויות להבריח מים הוי חסרון, ולכאורה יקשה דהיה לגמ' לתלות דין זה במח' הנ\"ל, וכל זה צריך ביאור.\u003c/span>"}, {"s": "h7", "h": "ביאור לישנא דנוטלתו בספינה - ד' אמות ליוצא חוץ לתחום חלוקות מד' אמות"}, {"s": "p", "h": "והנה בגדר דספינה נוטלתו, כתב ברש\"י שלושה פירושים, ומלישנא דגמרא דמניחתו בסוף ד\"א, היינו, במקום שיהיה אסור לו אם היה הולך, וממה שלא אמרה הגמרא חוץ לד\"א, משמע שהוא גדר במה שכן מותר בתוך ד\"א, והאיסור הוא במה שאין זה בתוך ד\"א, והיינו, שבספינה אין גדר ד\"א שיש לתת לכל מי שיצא חוץ לתחום. והנה דין ד\"א שיש למי שיוצא חוץ לתחום מוסכם לכולי תנאי, ומשמע שאף שאין למי שאינו בתחומו היתר ללכת אלפיים, משום דלא קונה תחום, ואין ללכת שלא בתוך התחום, הליכה בתוך ד\"א לא חשובה הליכה האסורה חוץ לתחום, והנה זה ודאי שמי שנמצא בתחומו אין לו לצאת אפילו משהו מחוץ לתחום, משום שיציאה מתחום אין היא נוגעת למה שיש לאדם ד\"א סביבו, כיון שאין היא נקבעת ביחס למקום הנוכחי, אבל מי שכבר יצא חוץ לתחום, והרי שאין מקומו הנוכחי נמדד ביחס למקום תחומו, ואף אם יתרחק ממקום תחומו יותר ע\"י ד\"א אלו שקיבל שרי, שכבר יצא ואין יציאה אחר יציאה (ויש לדון לר\"א דתוך ב\"א יכנס, אי שרי ליה לבחור בד\"א דאית ליה), ומה שאסור לו לצאת מד\"א אלו הוא משום שנחשב יוצא ממקומו, כמו מי שיוצא מאלפיים דתחומו, אבל אין זה משום תחום שיצא ממנו."}, {"s": "h7", "h": "מדידת תחום וד' אמות בספינה - אלפיים לפי קרקע עולם ומחלוקת בד' אמות בספינה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"663\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">6\u003c/sup>\u003cspan class=\"ca\" data-c=\"663\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">והנה משמע דלכ\"ע מודדים אלפיים דתחום לפי קרקע עולם, ולא לפי קרקע ספינה, ואפילו לר\"ג חשיב שיצא מחוץ לתחום. אלא שיש לדון אי ארבע אמות דאית למי שיצא הוה בקרקע עולם, או בקרקע דספינה, והנה אף ר\"י ור\"ע דהחמירו אמרינן עלייהו דלא יצאו רק מארבע אמות ולא אמרו שלא זזו כלל, והיינו, דאף לר' זירא דס\"ל דחלקו, אי מהני האי דנוטלתו, דלר\"ג מהני שיצא חוץ לארבע, ולר\"י ור\"ע לא מהני, הוא דווקא לגבי הילוך כל הספינה, אבל לגבי ארבע אמות לא חלקו, ואף שנוטלתו חוץ לארבע, ואף אם הולך למערב והיא למזרח, ומשמע דאף לר\"י ור\"ע יש לו ארבע אמות לפי קרקע דספינה, אלא דסבר ר\"ג דכיון שנוטלתו וכו', וממילא אין להגדיר בספינה ארבע אמות דתחום לפי קרקע עולם, והרי שאין בקרקע דספינה גדר קביעות ביחס לתחומין, וכיון שכן גם הילוך בכל חלקיה לא יחשב כיציאה חוץ לתחום. אבל ר\"י ור\"ע סברי דאין ד\"א אמות הללו נמדדים ביחס לתחום, היינו, קרקע עולם, אלא ביחס לאדם, וספינה הוי קרקע דשימושו, ויש לקבוע בה ד\"א. אבל רבה סבר דבספינה המהלכת כ\"ע יודו שמותר, וכדאמרן בדעת ר\"ג. ולא חלקו אלא בעומדת. והנה ממה שאמר הסברא דשבת באוויר מחיצות, והיינו, בתחילת שבת (דאמר רבה מבעוד יום, והרי בזה ספינה הוי יותר מדיר וסהר), משמע שגדר היתר דאית לר\"ג הוא מתחילת שבת, ואף במהלכת בתחילת שבת, דכיון ששבת באוויר מחיצות שם הוי שביתתו, ואף שעמדה באמצע שבת ורק אז יש לו לקנות ד\"א, כשקונה קונה באוויר ששבת בו מבעוד יום. ור\"י ור\"ע מודו דכיון שהיתה מהלכת בתחילת שבת אין לו לקנות שביתה משום דנוטלתו וכו', ואפילו לגבי ספינה ומהלך את כולה, אבל אם עמדה אפילו באמצע שבת, עתה יש להם לקנות ד\"א קבועים בספינה, ואף אחר שתהלך לא יהיה להם אלא האי ד\"א, והיינו, דמה דמהני מה שנוטלתו הוא רק אלא למנוע קביעת שביתה, אבל אחר שנקבע ואפילו באמצע שבת אין בנוטלתו להשפיע על ד\"א אלו. ומשמע דאם לא היה מועיל שבת באוויר מחיצות דתחילת שבת לר\"ג והיה קונה רק באמצע שבת משום שעמדה, גם היה מודה דאין לו אלא ד\"א, ולפי מה שפרש\"י בפירוש אחרון (וכתב דזה עיקר), צ\"ל דלא סבר כן ר' זירא, וגם בזה נחלקו רבה ור' זירא, אי מהני מה שנוטלתו לר\"ג אחר שעמדה וקנה שביתה בלא שבת באוויר מחיצות. וכן משמע דא\"כ הוה ליה להקשות לר' זירא מדיוקא דמתני', דלמה לא חש ר\"ג אולי עמדה באמצע שבת וקנה שביתה שלא ע\"י שביתה באוויר מחיצות (דלר' זירא הוי מחיצה גרועה), ועתה לא מהני מה שנוטלתו, וכמו לר\"י ור\"ע. ואמנם ברש\"י כתב דלהאי לישנא אפילו עמדה, מותר אחר כן בשעת הילוך, ואפילו לר\"י ור\"ע, ולא נחלקו אלא בשעת עמידה, והיינו, דרבה סבר דאף אי עמדה אחר שתלך מותר לכ\"ע, ולא ביאר רש\"י דיוקא דרנב\"י שרצו להחמיר, להאי לישנא, דקשה דאם לא נחלקו אלא על שעת עמידה מה שייך להחמיר, וכי לא היו יודעים אם ספינה מהלכת או עומדת. וצ\"ל ללישנא זו דכיון שגדר ההיתר במהלכת הוא משום שמוציאתו מד\"א קודמות, באמצע פסיעה יתכן שתהלך הספינה ולא במהירות, ויניח רגלו שניה מחוץ לד\"א לפני שיצאה רגלו הראשונה מד\"א, שצריך שהספינה תהלך מרחק ד\"א תוך זמן צעד אחד. וזה שהחמירו על עצמם שאף שעתה היא מהלכת ד\"א כדי פסיעה, אפשר שתאט הליכתה, וזה שכתב רש\"י דלמא עמדה פתאום. אלא שיש להקשות דלפ\"ז היה להם שלא להלך אפילו בתוך ארבע אמות, דכיון שקונים כל פעם ארבע אמות, אם יש לחשוש שלא הולכת הספינה ארבע אמות כדי צעד אחד, הרי שהביאתם לקצה ד\"א שקנו, ובהנחת רגלם יוצאים מזה. וצ\"ל דאף לר\"ע בתוך ד\"א מותר, וזה גדר בקרקע ספינה. וצ\"ב. וע\"ע לקמן. וברש\"ל מחק מילים אלו וכן כל ד\"ה הלכה, ונראה דעתו משום דהא איתא רק לר' זירא דלית ליה שבת באוויר מחיצות, ואנן כרבה דייקינן דבמהלכת לא פליגי, ואפילו ר\"ע, וליכא למימר הלכה כר\"ג. ונראה לתרץ דברים אלו, בהקדם מה דיש להקשות בדרב אחא בריה דרבא ורב אשי במהלך השקו\"ט, דהלא משנה ברורה היא דחלקו בספינה דר\"ג וראב\"ע הלכו, ור\"ע ור\"י לא זזו, ולפי מה שביארנו לעיל צ\"ל דכיון שהעמדנו דאיירי בזמן שיש להסתפק אי איכא לנוטלתו או לא, ובמשנה כתוב שרצו להחמיר, אפשר דאף ר\"ג מודה דבודאי עמדה אסור, אלא דלא רצה להחמיר, ומהיכי תיתי דחלק, וכדרבה, שנאמר הלכה כר\"ג אפילו בעומדת, ומשום הא דרבה. והוכיח לו רב אשי מבריתא דר\"י דאף בעומדת סבר ר\"ג דמותר, דהא פסק ר\"י כר\"ג, ומדוע החמיר על עצמו, ובהכרח דהא דפסק כר\"ג הוא במהלכת, ומה שהחמיר הוא בעומדת, ומשום דהוה כדיר וסהר דפסק כר\"ע. ואחר העיון נראה דאפשר זה אף ללישנא קמא, וצ\"ל דמה שאמרו דהלכה כר\"ג, היינו, ולא מטעמיה, דהוא התיר אפילו בעומדת, ואפילו בלא שבת מבעוד יום, וכמו בדיר וסהר, אלא ממה שאמר רב הלכה כר\"ג בספינה ולא אמר רק הלכה כר\"ג, משמע דרב ס\"ל שיש גריעותא בספינה מדיר וסהר, ועכ\"פ הלכה כר\"ג דמהלך את כולה ומטעם אחר. וכן משמע מהא דשמואל פסק כן רק בספינה ולא בדיר וסהר. וטעם שביקשה הגמ' הוא טעמא דרב ושמואל ולא דר\"ג. ור' זירא סבר דהאי מעליותא הוא מטעם דנוטלתו, ורבה סבר וכו'. אלא שהיה קשה דא\"כ אין זה משום דהלכה כר\"ג, שיש לומר דבזה אף ר\"ע יודה, ויש להעמיד את המשנה בלא שבת ובעומדת, וכמו בדיר וסהר. ונאמר דהא דכתבה המשנה המעשה בספינה הוא משום מחלוקתם בדיר וסהר, ולא דין נוסף. והוכיח רב אשי מברייתא שיש בספינה מחלוקת נוספת, והיינו, דסבר ר\"ג דאף לר\"ע בדיר וסהר יש להתיר בספינה, משום שאין לחשוש שעמדה או שעומדת, ופסק ר\"י כוותיה, ומוכח מזה דלא ס\"ל לר\"י ור\"ע להא דר' זירא ודרבה, ומשום הכי תלו רב ושמואל הלכה דספינה בר\"ג, ומה שאמרנו דאיכא גריעותא בספינה לרב, היינו, לגבי מה שאין לומר בה דכולה כד\"א בשבת באמצע שבת, וכדיר וסהר. ויש לומר בזה שני סברות, או משום דמחיצות ספינה להבריח מים עשויות, או משום דלא קביעא, וזה מה דלא אמרו ר' זירא ורבה כאידך, דסבר ר' זירא דגריעותא דספינה משום דלא קביעא, וע\"כ אין לומר דכולה כד\"א בשבת באמצע שבת אלא משום שנוטלתו, אבל לא יועיל לזה מה דשבת מבעוד יום, משום דמחיצות וכו', ורבה סבר דגריעותיה משום דמחיצות וכו' אבל בשבת מבעוד יום ליכא להאי גריעותא, אבל מה דלא קביעא אין זה חסרון. וביאורו ללישנא קמא דאיירי לפני שקנו שביתה, היינו, דאמר ליה רבה לר' זירא דבמהלכת אפילו ר\"ע מודה, ובהכרח שאין חסרון בדלא קביעא, דכ\"ש שהיה לו לאסור ללכת חוץ לד\"א משום מחיצות גרועות. ור' זירא אמר דאמנם היה לשביתה מבעוד יום להועיל אפילו בלא קביעא, אבל רק במחיצות שיש בהם להגדיר מקום דספינה, ולא במחיצות העשויות להבריח מים, דהוו מחיצות לבר. וללישנא בתרא דאיירי אפילו קנו שביתה א\"ל רבה לר' זירא וכו', ובביאור מה שחוסר קביעות הוי גריעותא, נראה כך, שהרי גדר תחום אינו תלוי בקרקע מסויימת, וא\"כ אין גדר מה שהתיר ר\"ג בדיר וסהר, משום שיש לו להלך בכל המקום דהוא אחד, והיינו, שיש לומר שסיבת מה שאין איסור בהילוך בד\"א דאית ליה יהיה שייך בכל המקום, וזה אינו. שאין לתלות גדר איסור הילוך במקום, וכמו בחצי מערה. ובהכרח שגדרו משום דד\"א דאית ליה חשיבי בכל המקום, ולומר דיחשב המקום כולו כד\"א, לא מסתברא דהאי ד\"א משום הילוך הוא, ולא הוי קביעא לגבי המקום, אלא היינו טעמא, דכיון דהאי ד\"א חשיבא כדבר לא קבוע ביחס למקום, יש לומר שלא קביעא ד\"א כלל, והיינו, שיש לבאר אמאי לא יהיה גדר ד\"א אלו כד\"א דהוצאה, דאית להעביר פחות פחות, וביאורו הוא, שגדר נקודת מקומו היא ישיבה וביחס להילוך הוי דבר קבוע, וע\"כ יהיה לה חשיבות להגדיר הילוך, וכמו שנאמר במי שיושב ויש מי שהולך לידו שאין גדר היושב שהוא יושב ליד המהלך, אלא המהלך הוא שהולך ליד היושב. וע\"כ במקום שיש לו גדר מקום קבוע אין להגדיר הילוך, אלא ביחס למקום ולא ביחס לישיבה, שהיא לא קבועה ביחס אליו. וכמו שנאמר בשלושה שאחד יושב בארץ ואחד יושב בעגלה ואחד מהלך שיש ליחס המהלך ליושב בארץ, ולא ליושב בעגלה, ואף שאם לא היו רק שניהם, ודאי היה מתייחס ליושב בעגלה, וא\"כ כשמהלך בה הוי כאילו קונה בכל צעד מקום ישיבה חדש, ובחצי מערה אין מועיל מקום המערה דהילוך האסור הוא, משום שביתה שקנה מבעוד יום, וביחס לאותה השבת הוי כביתו, וזה חשיבות באדם עצמו, ויש בזה להגדיר הילוך. אבל בספינה אף שיש לה מקום קבוע בקרקע שלה אין בזה חשיבות ביחס להילוך, דהוא בקרקע עולם והרי היא מהלכת כמוהו, וע\"כ יהיה גדר ההילוך לפי ד\"א דאית ליה. אבל בנוטלתו לל\"ק ליתא למקום ישיבה כלל, ולל\"ב אין זה הילוך שלו אלא דספינה (ומעתה יש לבאר גם לישנא דכתב רש\"י בשם רבו שהספינה הולכת למערב והוא הולך למזרח, והיינו, דאין הכוונה דאיירי בזה האופן, וכמו שהקשה רש\"י שפיר. אלא כוונתו שאין להגדיר הילוך ברחבי ספינה הנעה כהילוך ביחס לקרקע עולם, שהרי יתכן שילך ממקום למקום בספינה, וישאר עדיין במקומו דקרקע עולם, וע\"כ אין להחשיב הילוך דספינה כהילוך ביחס לקרקע עולם).\u003c/span>"}, {"s": "h7", "h": "מחיצה להבריח מים בספינה - שייכת לשביתה באוויר מחיצות ולא להילוך רגיל בשבת"}, {"s": "p", "h": "והנה מה שאמרנו בגריעותא דמחיצה העשויה וכו', היינו, כמו שיתבאר לקמן דמה שיש להגדיר הילוך ביחס למקום המוקף, ולא ביחס לנקודת ישיבתו, הוא משום קביעות שיש למקום המוקף ביחס למקום ישיבתו, והיינו, שבאותם ד\"א אמות דהן מקום ישיבה יש חשיבות עדיפה, דהוו מקום המוקף, וע\"כ יהיה עמידה דהילוך ביחס למקום המוקף, היינו, כל המקום, כישיבה חדשה. אבל אם אין כל המקום חשוב למקום אחד, הרי שכל חלק וחלק חשוב כמוקף לעצמו. ועדיין יהיה חשיבות במקום ישיבה, וגם הילוך ביחס למקום המוקף יהיה ביחס לד\"א אלו, והיינו, ספינה שאין מחיצותיה חשובים לאחד המקום, אבל בשבת באוויר מחיצות מבעוד יום אין גדר הילוך שלו ביחס לכל המקום, משום אחידות קרקע המקום המוקף, אלא משום קביעות שיש לאדם עצמו במקום, והוי כמו עומד בקצה התחום, שאין הילוכו ביחס לד\"א, אלא ביחס מקום ששבת שם. ולקמן יבואר למה אין חסרון דמחיצות עשויות להבריח מים ביחס לשביתה זו."}, {"s": "h7", "h": "מדידת הילוך ביציאת אלפיים אמה - האיסור תלוי בביטול שביתה הנמדד לפי קרקע עולם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"664\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"664\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואחר כל זה יתבאר ביתר למה אין הילוך דיציאת אלפיים נמדד אלא ביחס לקרקע עולם (דאף למ\"ד יש תחומין אין איסור לעלות למעלה), והיינו, דכיון שאיסור יציאה חוץ לתחום משום ביטול שביתה הוא, הרי שגדר מקומו הוא במה שיש באי יציאה ממנו שביתה דאדם (ואין זה ככל המלאכות שהם משום עבודה, ואי השביתה היא במלאכה שנעשתה, אלא גדר זה הוא כמו שביתת כלים דב\"ש, והיינו, שהאדם עצמו נחשב שבות ולא רק שובת (ומה דהתם בעינן דלעביד הכלי מעשה משום דהוה מבעוד יום)), וע\"כ לא יהיה חשיבות דמקום ויציאה ממקום אלא במה שנחשב המקום כמקומו עצמו, ומי שיצא מתחומו הרי שאין הוא במקומו. וע\"כ יהיה גדר מדידת דבר זה ביחס למקום קיום דאדם עצמו ולא תשמישו, וע\"כ לא יהיה חשיבות מקומות חלוקים ביחס למדידת אלפים, שאין חילוקי מקומות אלא ביחס לשימוש ולא ביחס לאדם. וזה הגדר אינו תלוי באי אית לתחומין למעלה מעשרה או לא, ולא נחלקו אלא בגדר מה נחשב יציאה שלא נאמר אל יהי שלא במקומו, אלא שלא יצא, ואף שהוא גופו הדבר השבות כמלאכה, אין האיסור אלא בדעתו ובמעשהו. ונסתפקו אי למעלה מעשרה חשיב הילוך.\u003c/span>"}, {"s": "h7", "h": "הדעה דרגל אחת הוי כיציאה - חילוק מהוצאה שחציו כאן וחציו כאן אינו הוצאה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"665\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">8\u003c/sup>\u003cspan class=\"ca\" data-c=\"665\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וע\"פ זה יבואר מה דאיכא למ\"ד דאפילו לא יצא אלא ברגל אחת כבר נחשב שהוא חוץ לתחום, אף דלגבי הוצאה חציו כאן וחציו כאן לא חשוב הוצאה, וכ\"ש ברוב. והוא משום שאין גדר ביציאה דתחום שיוצא ממקום למקום כבהוצאה, אלא מה שאינו במקומו, וא\"כ אין שני המקומות בגדר אחד שיהיה להכריע מקומו אם הוא כאן או כאן, וללכת אחר רובו ואיגודו וכו'. ואף מאן דסבר למקום שרובו נזקר אין זה גדר במקום, אלא בו, וגדר נזקר, היינו, שאם תעמידהו ביושר רגלים וזקירת גוף, יש לו להזדקר לפי רובו.\u003c/span>"}, {"s": "h7", "h": "סוגיית ר' חנינא בתשיב רגלך - פילוגא מברייתא דאמרינן כאחרים דאזלינן בתר רובא"}, {"s": "p", "h": "והנה עפ\"ז יש לבאר סוגיא דהתם דיליף ר' חנינא מאם תשיב משבת רגלך, שמשמע שזהו גדר באיסור יציאה, והקשו מבריתא, ואמרו דהא כאחרים דלמקום שרובו הוא נזקר. ויש לשמוע מזה שהוא גדר במקומו, היינו, היכן נחשב שהוא נמצא. ואמנם יש לבאר למה יהיה תלוי זה בזה, והיינו, שהיה לומר דלגבי איסור עובר אפילו ברגלו אחת, ולגבי מקומו לא חשיב שיצא, ויכנס. ומשמע שאין איסור דהילוך אלא במה שהוא נחשב חוץ לתחום."}, {"s": "h7", "h": "מהלך הגמ' בין ר' חנינא לברייתא - חילוק אי הפסוק מגדיר מעשה איסור או מקומו"}, {"s": "p", "h": "וביאור מהלך הגמ' כך, דר' חנינא אמר שע\"י יציאת רגלו אחת כבר חשיב שעבר אאיסור תחומין, היינו, ביטול שביתה האמור בתשיב משבת, וממילא לא יכנס, ולא הוי גדר במקומו, אלא משום שביתה דאית ביה, והקשו מברייתא לומר שלא חשיב דעבר, ותרצו דהאי ברייתא כאחרים, והיינו, דס\"ל לברייתא שאין גדר מקומו תלוי ביציאה, אלא יציאה תלויה במקומו, ורגלו האמורה בפסוק, הוא באופן שאין להגדירה לפי מקום האדם, ומשום מקום שרובו נמצא בו לשם הוא נזקר, והיינו, דעיקר קושיא דגמ' היתה בביאור הפסוק, שר' חנינא סבר שהוא גדר במעשה יציאה, ורגל אחת אמר הכתוב, ובברייתא משמע  שהוא גדר באדם, ורגלו, היינו, גופו, לענין מה שמתרחק. ובאיכא דאמרי דיליף ר' חנינא רגליך, דמשמע דסבר שאין איסור יציאה אלא ע\"י סיום הליכתו והקשו מברייתא ותרצו דאה\"נ דלא סבר ר' חנינא שהוא גדר ביציאה, ואה\"נ אפילו ברגלו אחת הוה יציאה, וכדכתיב בקרא, אלא דמשום דסבר כאחרים הרי אפילו רגלו הנ\"ל לא חשיבא שיצאה, ולא איירי קרי דהפסוק בגדר האיסור, אלא בצורת המעשה שיש לעבור עליו."}, {"s": "h7", "h": "דקדוק קרא דרגלך ורגליך בקרי - חילוק בין מעשה ההילוך למצב עמידת גופו בתחום"}, {"s": "p", "h": "וביאור הפסוק כך דרגלך בלשון יחיד מתייחס למעשה דהילוך, ותשיב שלא תעשה המעשה, משבת מחמת שיש באי הילוך קיום שביתה דמעשה הילוך, ובקרי, היינו, רגליך בלשון רבים הוא בעמידה, היינו, מה שהילוך עביד ביחס לעמידת אדם. ותשיב, היינו, שלא יהיה המקרה הוא העמידה, משבת, מחמת שיש בעמידה בתוך התחום קיום מצב שביתה דגופו. ואי סבירא לן כאחרים שיש גדר במקום גופו ביחס לתחום, וממילא יהיה גדר בהילוך ביחס לזה, אז יש לפרש דרגליך, היינו, במצב ששתיהם בחוץ, ורגלך הוא מעשה האיסור דרגל שניה. ואי לא ס\"ל כאחרים ואין גדר במקום גופו כנ\"ל, ויהיה מעשה האיסור מגדיר המקום ולא בהיפך, אז רגלך יהיה גם מצב המציאות, היינו, רגל אחת חוץ לתחום, ורגליך, היינו, גדר גופו כולו אחר שיצא, ואף רגלו שתוך התחום בטלה משביתה, שהרי לא חשיבא לענין יכנס."}, {"s": "h3", "h": "ג. שיטת ר\"א בד' אמות באמצען ויוצא ברשות"}, {"s": "h7", "h": "גדר ההיתר ברבנן ובר\"א - הבלעת תחומין לרבנן מול קניית תחום חדש לר\"א"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"666\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"666\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכל זה רק לרבנן וביחס להשפעת מקום גופו על מעשה הילוך וההיפך, אבל לר\"א גדר ההיתר הוא משום מקום גופא, והיינו, דמה שחילקנו בין מקום גופו דעמידה לבין מעשה דהילוך, הוא גדר רק לגבי הילוך ועמידה כתוצאת הילוך, אבל ר\"א סבר שאמנם לגבי מעשה יש לומר כדלעיל, אבל אין כניסה תלויה במעשה האסור, ומשום הבלעת תחומין, והיינו, דלרבנן כיון שנחשב שגופו עומד במקום שאסור לו להיות כבר בטל תחום דידיה, אבל ר\"א סבר דלא בטל תחום דידיה אלא במה דאית ליה תחום אחר, ואין זה משום קנס, אלא כיון שאין יכול יותר להגיע למקום ששבת אין לו תחום דהאי מקום, וממילא הוו ד\"א שלו תחום חדש (והיינו, שהיה אולי לומר שאף ר\"א סבר שבעומדו חוץ לתחום כבר בטל תחומו, ומשום דעבד מעשה יציאה, וכרבנן, אלא דסבר דעמידת רגלים הוה בכל ארבע אמות שסביבו, והוי כנמצא מיעוטו בתחום, ובזה לא חשיב שיצא. וזה מה דאמרה הגמ' מאי לאו ר\"א לטעמיה, ולא הכריחה, והיינו, כדלעיל, שהיה לומר שאין זה משום מקום, ומה שיש לאדם ד\"א כמקומו, אלא זה משום דחשיב גופו בכל ד\"א. וזה אמרה הגמ' והסכימו בה כ\"ע דזה משום מקום, וכמו במי שישן), אבל אם אפשר לו להגיע לתחומו, אין לתחומו ליבטל.\u003c/span>"}, {"s": "h7", "h": "גדר ד' אמות באמצען לר\"א - ביאור הדין בעקר תרתי וקם אתלתא בפסיעותיו"}, {"s": "p", "h": "והנה ביאור גדר ד\"א אלו צ\"ב, דהא אמרו דהוא מטעמא דאית לר\"א במי שאין לו לקנות אלפיים דעכ\"פ קנה ד\"א, ודסבר ר\"א דהוא באמצען, היינו, שאין הוא יכול לבחור איזה ד\"א שירצה כר\"י, אלא הרי הוא באמצען. ומשמע שכוונתו כאילו לוקחין טבלה (מרובעת או עגולה), ומניחים נקודת אמציעתה במקום נקודת אמצע גופו, ולפ\"ז הרי שגופו תופס חלק מארבע אמות אלו, והנה בגמ' אמרו דלא אסר ר\"א אלא בעקר תרתי, וקם אתלתא, וביאר רש\"י שכל עוד נמצא בתוך שתים משהו מותר להיכנס, ואם כאמור זה קשה, שהרי מה דאמר ר\"א והוא באמצען היינו דשתיים דצד זה מתחיל מאמצע גופו, וחצי גופו הוי משתיים דצד שני. אלא שהיה לומר דלגבי מקום עמידת גופו אף ר\"א סבר דיש לו לברור, אבל זה לא מסתבר דהא יש לומר בשתי דרכים, או שיש לו לברור ד\"א איפה שירצה, אבל בעינן שיהיה נקודת אמצעיתן תחתיו, ושיש לו לברור נקודה אחת מתחתיו שתהיה אמציעתו, ושם יהיה אמצע ד\"א, ולא נראה דלא מצאנו רמז לגדר זה, וגם לשון המשנה שהוא באמצען, ור\"י אמר לאיזה שירצה משמע שאין זה ברירה דידיה, וכמו באלפים לריב\"נ."}, {"s": "h7", "h": "חילוק בגדר הברירה בתחומין - קניית שביתה זקוקה לברירה וד' אמות דחזרה אינן צריכות"}, {"s": "p", "h": "וע\"כ נראה יותר לחלק בהא דאמר ר\"א שאינו יכול לברור כר\"י, דאמנם לגבי קנית שביתה שיהיה מקומו, הרי שאין לו יכולת לברור, משום דיש בזמן דקודם הברירה חסרון ביחס להיות לו מקום קבוע, אבל בנידון דידן הרי אינו רוצה לקנות שם שביתה, אלא לחזור לתחומו, וע\"כ באי קביעת האי ד\"א חסרון. אבל גם זה צ\"ב דאם יש לו לברור למה אין זה רק ביחס לשתי אמות, ומדוע לא יברור כל ד\"א, וכר\"י בישן."}, {"s": "h7", "h": "ברירה בד' אמות או בגופו - דיוק מלשון המשנה לאיזה רוח שירצה לברור לו"}, {"s": "p", "h": "ונראה לחלק לפמש\"כ לעיל, ושיש לחקור אם גדר הברירה הוא בד\"א או בגופו, והיינו, אף לר\"י דסבר שיש לו לברור כל ד\"א, יש לחקור במה ברירתו, אם היא באיזה ד\"א רוצה, או בעצמו, שבורר באיזה חלק דד\"א הוא נמצא, בצפונה או בדרומה וכו'. ובלשון המשנה דלאיזה רוח שירצה, משמע שאין זה ברירה בעצמו. וכן משמע ברש\"י דכתב יטול ד\"א, היינו, שבורר הד\"א. ונראה דזה בדווקא, דאם היה גדר הברירה בגופו, לא היה לומר ברירה כלל, והיינו, שסיבת מה שסבר ר\"י דיש לו לברור הוא משום שעדיין אין זה קבוע, והיינו, שלא קנה שביתה במקום מסויים, ואמנם מקום שכיבתו קבע, היינו, גופו עצמו, אבל אין בזה לקבוע מקום. וע\"כ יש לו לקבוע באיזה רוח שירצה, ובחלק זה אף ר\"א מודה דכיון שהיה ישן אין לו לקבוע מקום, אלא שנחלקו דר\"י סבר שגדר מקום שהוא קובע הוא משום תחומין, ומקום הילוך, וע\"כ אפשר שיהיו כל הד\"א לפניו. ור\"א סבר דקביעות דאית ליה הוא משום שימוש במקום, וע\"כ גדר הקביעה במה שיש לו להשתמש ביותר, וזה ע\"י שהוא באמצען. וביאורו כי גדר ד\"א אלו הוא שיעור מקומות שימוש רבים."}, {"s": "h7", "h": "מקום גופו הישן אינו בשימושו - חילוק בין מקום מקומו העצמי למקום שימושו לר\"א"}, {"s": "p", "h": "ואם כנים הדברים מעתה יש לנו לומר דאף לגבי ישן סבר ר\"א שאין הוא חלק ממקום הד\"א, והיינו, דמקום שנמצא בו הוא גדר מקומו, וד\"א הם בגדר מקום לשימושו, ואין מקום הנחת גופו חשיב מקום שימושו, אלא מקומו הוא. וכן משמע ברש\"י אדין דהיו שנים שעומדים בריחוק ו' אמות, דאיירי באופן דמיבלע ב' אמות של זה בחבירו. ומשמע דזה לכ\"ע, וא\"כ גם הכא ב' אמות, היינו, חוץ לו. אלא שזה ניחא לר\"י אבל לת\"ק, היינו, ר\"מ, יקשה מהו שאמר שמונה על שמונה, דאי איירי דיש לו ד\"א לכל רוח מלבד עמידת רגליו, אין זה שמונה על שמונה, ור\"א דאמר דהוא באמצען ניחא, דהוא איירי אדברי ת\"ק דאמר דאין לו אלא ד\"א, ואמר ר\"א דהוה חציו לכאן וחציו לכאן. וכן ר\"י דאיירי על ד\"א כטבלה, והיינו, דלפני שבירר יש לו לקנות בשמונה על שמונה חוץ מעמידת רגליו. אלא לר\"מ אי איירי חוץ מעמידת רגליו אין זה ראוי לקרותו שמונה על שמונה, ומשמע דבאמת אין זה חוץ לעמידת רגליו אלא הרי הוא עומד בתוכם."}, {"s": "h7", "h": "תמיהת הגמ' היינו תנא קמא - ת\"ק כולל עמידת רגליו בשמונה ור\"א חילק מחדש"}, {"s": "p", "h": "ובזה יבואר מה הקשתה הגמ' דהיינו ת\"ק, דכיון דלא סבר ת\"ק כר\"א, הרי שאין כוונתו באמצען, ואי כוונתו לרוח אחת הרי זה כר\"י, ואי כוונתו לכל רוח ואין צריך לברר, מאי מודה ר\"י, הלא לא אתי אלא בשביל זה. וזה מתרצת הגמרא דת\"ק סבר שמונה על שמונה כולל עמידת רגליו, היינו, ד\"א לכל צד וקצוותיהם באמציעתו. ועל אמר ר\"א דאין זה תלוי באמצעיתו, אלא הוא באמצען, והיינו, דזה חוץ מעמידת רגליו, ואמר ר\"י דאמנם הוא חוץ מעמידת רגליו, אבל הרי זה כת\"ק דהוא לכל רוח שירצה, ודקתני מודה ר\"י, הוא לכ\"ע, דכיון דסבר ר\"י דהוא חוץ מעמידת רגליו ולכל רוח שירצה, היה לומר דכיון שיכול לחזור למקום עמידת רגליו הראשון הרי יש לו לקנות ד\"א אחרים, שהוא בקצות כולם וכאילו לא יצא, אבל מודה ר\"י דאחר שבירר אינו יכול לחזור בו, ואף שאפשר לו לחזור למקום שאין בשהיה בו בירור."}, {"s": "h7", "h": "מחלוקת עגולות ומרובעות לר\"י - חילוק בין מרחק מנקודה לטבלה המתחלת מרגליו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"667\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"667\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וביתר ביאור דברי ר\"י, שהנה מצאנו שיש מח' אי אלפים דאית למי ששבת בדרך עגולות הן או מרובעות, ותראה כי שני אפשרויות אלו הרי הן בשני גדרים. דאי נימא שהן מעמידת רגליו ולחוץ, מה שייך שיהיו עגולות כיון שאין האדם עגול, ואין זה כמו אלפים דעיר אי לא מרבעינן לה הרי שיש למדוד כל צד בנפרד, ואין זה עגול. ובעגולה אה\"נ, דהא אמר עגולות. ובהכרח שגדר אלפיים הנ\"ל הן מנקודת אמציעתו, וכן למ\"ד מרובעות הן, שאין פירושו מעמידת רגליו דאין זה כטבלה, אלא כארבע טבלאות דיושר, וארבע דזויות, וא\"כ יקשה בשלמא לר\"מ דהוה מנקודת אמצעיתו, היינו, כטבלה, אלא לר\"י דהוה מעמידת רגליו, היינו, שיש לו לקנות במרחק ארבע אמות דארבע צדדיו, אין זה לכל רוח שירצה דאין יכול לקנות ברוח זווית כברוח יושר, ואי הוה לכל צדדיו אין שייך שיהיה זה חוץ לעמידת רגליו, ובעי למדוד מאמצעיתו.\u003c/span>"}, {"s": "h7", "h": "חילוק בין קודם לברירה לאחריה - קודם בירור מרחק מנקודה ולאחריו טבלה קבועה"}, {"s": "p", "h": "אלא היינו טעמא דבאמת קודם שבירר הוי מנקודת אמציעתו, ובעיגול, ומשום מרחק, וע\"כ הוי לכל רוח. אבל אחר שבירר, הרי אין זה בגדר מרחק מנקודה, אלא כטבלה המתחלת מעמידת רגליו, וע\"כ אין יכול לחזור בו. ובזה יבואר גדר חזרה המוזכר פה, שהיה לשאול לא יברור ולא יחזור, אלא היינו טעמא דאמנם במרחק דנקודה שייך שיהיה בלי בירור ובלא חזרה, אבל לקנות ד\"א הרי נשכר לזוויות, וד\"א אחרים הוי תרתי דסתרי, אלא שתאמר שיחזור בו כיון שבירר אינו יכול לחזור, וכדלעיל."}, {"s": "h7", "h": "מחלוקת רבנן ור\"א ביוצא ברשות - חילוק אי ד' אמות מתחומו או תחום חדש"}, {"s": "p", "h": "וזה ביאור מה שחלקו רבנן ור\"א ביצא לדבר הרשות, והיינו, דסברי רבנן שמה שיש ליוצא חוץ לתחום ארבע אמות, אין זה משום שיש לתת לו תחום חדש, אלא משום דהיוצא הריהו כמי שנמצא בסוף התחום, שאין לילך אפילו אמה, ומה שאנו אומרים שיש לו ארבע אמות, הרי זה משום מקום דקני, ומשום שאין להחשיב תזוזה בו להילוך, וא\"כ ממ\"נ אי קני האי ארבע הרי הפסיד את תחומו, ואי לא קני הרי שאין לו לזוז כמלא נימא. אבל ר\"א סבר דהילוך ארבע אמות הנ\"ל אינו צריך לקניה, דס\"ל שהילוך בפחות מד\"א אינו נחשב הילוך, וכיון שכן היה לו ללכת, אלא דביציאתו הרי יש לו לקנות ד\"א כמו שיש לו ד\"א בתחום עצמו לענין טלטול ועוד, וכיון שקנה הרי זה מקומו, ואין לו עוד מקום דתחום, אלא דכמו דהאי ארבע דאית בתוך התחום לא מפקי ממקום תחום, דחשיבא מקום תחומו יותר, כך לגבי יוצא לתחום שאין להחשיב ארבע אמות הללו לגבי מקומו, אלא דזה יש לומר שזה רק כאופן לד\"א אלו שייכות עם מקום התחום, והיינו, בהבלעתם, אבל אי לאו אין להם להתבטל מחמת זה."}, {"s": "h7", "h": "ביאור נוסף בשיטת ר\"א - תוך שתיים מקומו על גבול תחומו ואינו מפסיד"}, {"s": "p", "h": "כל היה נראה לומר בתחילה, אבל יש לנו לבאר בדרך אחרת, והיינו, שאין די במה שמקצת ד\"א דשימוש נמצאים בתוך תחום מקומו, ואה\"נ כיון שיצא כמעט הוה ליה לקנות מקום, אלא היינו טעמא דר\"א דס\"ל שבהיותו תוך שתים יש לומר שמקומו על גבול תחומו ובטיל לגבי מקומו דתחום, וע\"כ כל עוד נמצא בשתים אלו יש עדיין לומר שאין לו לקנות שהרי הוא בתוכם, אבל כיוצא משתים וקונה בשלש הפסיד התחום."}, {"s": "h7", "h": "תרי לישני בברייתא אליבא דר\"א - לישנא דמשנה בתחום ולישנא דברייתא בד' אמות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"668\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"668\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ונראה דזה ביאור שני הלישנות דברייתא, היינו, שבמשנה דשתיים יכנס שלוש לא יכנס אירי ביחס לתחומו, וכאילו קנה על גבול התחום. ולישנא דברייתא דאחת יכנס שתיים לא, היינו, שתיים דד\"א, שאין בקנייתם להפסיד תחומו. ובאמת דעת ר\"א כלישנא דברייתא, דאף דחשיב שיצא חוץ לתחום ויש לו מקום, כיון דמובלע יש לו ליכנס, אלא דבמשנה דאיירי ארבנן דסברי דבקניית מקום יש לו להפסיד תחומו, אמר ר\"א דע\"כ נימא דקנה בגבול התחום שאין לו להפסיד מקומו, ועמידת רגליו היא משום הא, ולא משום מקום דחוץ לתחום. ופליגי רבנן דעכ\"פ כיון דיצא חוץ לתחום אין לו מקום תחומו, וכדלעיל, דאם תשיב משבת רגלך. אבל לדבר מצוה שלא עבד איסור אה\"נ.\u003c/span>"}, {"s": "h3", "h": "ד. הבלעת תחומין לדבר מצוה במחלוקת רבה ורחב\"א"}, {"s": "h7", "h": "דעת רבנן ביוצא לדבר מצוה - אי תלוי בשלא קנה מקום או בקנה ומובלע"}, {"s": "p", "h": "אלא שיש לנו לדון לדעת רבנן אם זה דווקא כשלא קנה מקום, והיינו, משום שד\"א שלו בגבול התחום, או אפילו אי נימא דקנה, כיון דמיבלע מקומו. והיינו דלא חשיב מיבלע אלא בדבר מצווה שאין בד\"א אלו להפסיד לו תחומו. וחילוק הצדדים הוא דלצד הראשון אף לרבנן הוי דווקא בב' אמות, וכר\"א, אבל לצד שני הוי אפילו בארבע אמות, אי ס\"ל שאינו באמצען."}, {"s": "h7", "h": "מחלוקת רבה ורב שימי בהבלעה - תרי צדדי בדעת רבנן ביוצא לדבר מצוה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"669\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"669\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ונראה דבזה חלקו רבה ורב שימי בר חייא, דלרבה אין הבלעת תחומין אפילו לדבר מצוה, דכיון שיש לו מקום חדש הרי הפסיד תחום מקומו. ורב שימי בר חייא סבר כצד השני. ובזה יבואר דעת רבה דאמר אביי משמיה דלדבר מצווה אפילו רבנן מודו, דאביי סבר כמו שאמרנו בצד השני, וא\"כ הרי זה משום הבלעת תחומין. אבל רבה דאמר הכי לא התכוון אלא כמו הצד הראשון.\u003c/span>"}, {"s": "p", "h": "וזה ביאור מה שאמר רבה שנתחדש דלא אמרינן כיון דעקר עקר, ויקשה מנלן למימר הכי, אחר דאיירי שהוא בתחומו המותר לו. ולמשנ\"ת הרי זה תלוי בדברי רבה עצמם, היינו, דהא סבר רבה דכיון שקנה לו מקום אחר ממקומו לא מהני מה דהוא משום דבר מצווה, והרי הקנו חכ' מקום ליוצא לדבר מצוה, א\"כ הרי יש לו בזה להפסיד מקומו. וזה חידשו דלא הקנו לו חכ' זה אלא כשיוצא."}, {"s": "h7", "h": "חקירה בגדר תחומין באלפיים אמה - אי לאלפיים גדר מקום או מרחק משביתתו בלבד"}, {"s": "p", "h": "ונראה ביאור מחלוקתם בדעת רבנן כך, שהיה לחקור אי איכא גדר מקומו לאלפים דאית ליה, או שאין מקומו רק במקום שביתתו, ואלפים אלו אין הם אלא מרחק ממקום זה. ובזה יש לתלות מדוע לא קונה מי שנמצא בתוך תחומו מקום שביתתו, ויהיה לו עוד אלפים, וכמו לגבי הוצאה דפחות פחות מד\"א. דאי נימא דיש לאלפיים גדר מקום, אינו קונה משום שכבר קנוי לו. ואי נימא שהם משום מרחק, נצטרך לומר שבתוך אלפים נחשב שהוא עדיין במקום שביתתו."}, {"s": "h7", "h": "הבלעת תחומין ברבה ורחב\"א - תלות הדין במעמד אלפיים אמה כגדר מקום לעצמו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"670\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"670\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ובזה יש לתלות פלוגתא דרבה ורחב\"א דרבה סבר שאין זה רק מרחק, ואין זה מקומו, וממילא אין מובלע כלום. ורחב\"א סבר שנחשב למקומו, וא\"כ הרי דאיכא להבלעת תחומין. וזה שאלו ממערה דכיון שמתרחק אלפים אמה יאסר, ולא יועיל מה שזה קרוב לפתח שני שלא יצא משם, ואין למדוד מרחק ממקום שאינו. ותירץ דהתם שבת באוויר מחיצות, והיינו, דבזה מודה רבה דחשיבי כל אלפים כמקומו, והיינו, שתרתי אית ביה, גם שבשניהם שבת, ודלא כבמשנה. וגם דשביתה שלו היתה באוויר מחיצות, וכיון דחשיבי כולה כד\"א, ואין זה נחשב מקום, הרי שהיה לתת לו עוד ארבע אמות חוץ לזה, והיינו, אלפים הוי כארבע אמות.\u003c/span>"}, {"s": "h3", "h": "ה. גדרי יוצא בשוגג ושלא לדעת ודין אלפיים פסיעות"}, {"s": "h7", "h": "שיטת רש\"י ביוצא בשוגג ורשות - ג' תנאים מזיד, לדעת, ושלא לדבר מצוה"}, {"s": "p", "h": "והנה להוסיף בזה גדר יש לנו לבאר שיטת רש\"י שכתב במשנה דיצא חוץ לתחום לא יכנס, הוא במזיד, ולדעת, ושלא לדבר מצוה. והיינו, דכוונתו דמה דחלקו רבנן אר\"א במי שנמצא בתוך ב' לא יכנס הוא דווקא בכגון דא, וביאור שלושה תנאים אלו הוא דהנה בגמ' אמרו דהיפך דהוציאוהו נכרים הוא לדעת, וברש\"י כתב דהוציאוהו נכרים הוי אונס, וכן משמע דרוח רעה מעבירתו על דעתו, ולא אמרו יצא לרצון, שהוא היפך דאונס בכל מקום, והיינו, שאין לדעת גדר במעשה שלו, אלא במציאות האסורה. וכמו שאמרו דאין אונס לערווה משום שאין קישוי אלא לדעת, והיינו, שגדר איסור ערווה הוא לא בביאה שהיא המעשה, אלא במציאות השכיבה והנאה דאית ליה מחמתה, ולגבי מציאות קיימת אין שייך אונס ורצון, אלא דעת וחסרונה. וכן הוא בענייננו שאין גדר איסור יציאה אלא במה שהוא נמצא חוץ למקומו, היינו, גופו, וכדאמרן שזה חפצא דאיסור, וכדכתיב אל יצא חוץ למקומו, ולא אמר אל ילך כמו שאמר שבו (דמילת שבו יש בו משמעות יותר מסתם הימצאות במקום, ושלא אמר השארו או הימצאו איש תחתיו, שאז היה לומר שגדר המצוה היא הימצאות במקום, וישיבה היא מעשה דהימצאות במקום), שאין גדר איסור יציאה במעשה דהילוך, אלא בעשיית מצב דחוץ לתחום."}, {"s": "h7", "h": "העדר לימוד ביציאת חפצים בתחומין - איסור תחומין באדם עשיית עצמו למצב אסור בחוץ"}, {"s": "p", "h": "וכן נראה ממה שלא מצאנו לימוד לגבי יציאת חפצים, והיינו, שאין גדר אדם היוצא משום מעשה דהילוך, אלא משום מציאות מצב גופו שהוא בחוץ. אלא דכיון שאין לאדם גדר מקיים המציאות, היינו, בשעה שהוא חוץ לתחום שאין זה בידו, על כן יהיה גדר איסור יציאה שלו במה שהוא מביא עצמו למציאות זו (אבל בערווה הרי יש לו חלק בקיום המציאות עצמה דאין קישוי וכו', וע\"כ לא יועיל מה שההבאה היתה ע\"י אחרים, וכן הוא באישה), והיינו דדעת דהיתה לו לפני המעשה להימצאות חוץ לתחום ע\"י המעשה, חשיבא כאילו הוא המקיים את מציאות זו."}, {"s": "h7", "h": "ב' אופני חסרון דעת בתחומין - הליכה מחמת אונס נפשות מול דחיפה ע\"י אחרים"}, {"s": "p", "h": "וחסרון גדר זה שייך בשני אופנים, או שהוליכוהו באונס, היינו, שהלך הוא מחמת אונס נפשות, או שלקחוהו או דחפוהו ובזה אף באופן שרצונו בכך. דבמקרה הראשון אין הבדל בין מי יצא בעצמו למי שאנסוהו, אלא במה שאין זה לרצונו. ובמקרה השני אף שהיה רצונו לכך הרי לא הוציא עצמו, וזה כמו שאמרנו לעיל שגדר מה שנחשב מצב מציאותו חוץ לתחום מדעתו הוא במה שעשה מעשה ברצון לקיום התוצאה. ובשני מקרים אלו אין זה נחשב דעתו."}, {"s": "h7", "h": "הוציאוהו נכרים או רוח רעה - התאמת ב' המקרים לשני אופני חסרון דעת"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"671\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"671\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וזה ביאור מה שכתבה המשנה הוציאוהו נכרים או רוח רעה, דהוציאוהו נכרים, היינו, שלקחוהו או דחפוהו, וזה כמו המקרה השני. אבל רוח רעה הרי הוא עשה המעשה, רק שנחשב המעשה באונס (וכן נראה שלא כתבה המשנה עובדי כוכבים אלא נכרים, ושנכרים סתם לא איירי שרוצים שיעשה איסור, אלא עושים זאת מדעתם ולצרכיהם, אבל עובדי כוכבים איירי שרוצים להעבירו על דעתו ודתו, וזה משום אונס, וכמו רוח רעה, ולא יתחדש בזה דבר יותר מיוצא מחמת רוח רעה, וכן נראה דלגבי ביאת יבמה נקטו לישנא דעובדי כוכבים שהרי אין להם בזה הנאה מלבד להעביר על דעת.\u003c/span>"}, {"s": "h7", "h": "סוגיית עובדי כוכבים ברוח רעה - חילוק מנכרים דמתני' שאינם מתכוונים להעביר על הדת"}, {"s": "p", "h": "וזה ביאור מה שאמרו ג' דברים וכו' עובדי כוכבים וכו' ואין זה נכרים דמשנה שאין שייך בהם על דעת קונו, והיינו, רוח רעה, שאין רוח רעה שנשטתה אלא שנטרפה דעתו, היינו, שלא היה בכוח דעתו לעמוד ברוח זו, וזה דווקא ברוח רעה, היינו, שכשעומד בדעתו אין הוא מרוצה ברוח זו. אבל אם נטרפה דעתו מרוח טובה מרוב כל או שכרות וכו', אין זה חשוב אונס, וכן י\"ל בדקדוקי עשירות שהרי רוצה בכך. וע\"כ שאלו למאי נפק\"מ, והיינו, דכיון שאין זה מרצונו בודאי לא יביא עצמו לכך, ומה יש לו לעשות, וזה אמרו שיתפלל על זה שלא יבוא, ואחר שבא שילך)."}, {"s": "h7", "h": "אומר לנכרים לדחפו מול שוגג - אומר לנכרים לדעתו ושוגג בהילוך מהלך את כולה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"672\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">15\u003c/sup>\u003cspan class=\"ca\" data-c=\"672\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אבל במי שאמר לנכרים שידחפוהו אף שלא עשה המעשה בעצמו נחשב לדעתו, שהרי עושים זה לדעתו, וכן נראה, שהרי זהו כמקרה דספינה שאמרו ופוסק עליו לשבות ואינו שובת, ולא נתקן בפסיקה זו אלא מה שאין הנכרי עושה זה לדעת הישראל, ואף שעושה זה לצורך ישראל, ודי בזה לדין תחומין, וכמו דאמר רש\"י במזיד ולדעת, והיינו, דאף במזיד אי הוה שלא לדעת אין זה נחשב מעשה שלו. וכן משמע דבשוגג אף אי הוה לדעת לא נאסר אי חזר, וכמו בנחמיה בריה דרב חנילאי, שהרי אין להחשיב מה שיצא כלא לדעת, וכרוח רעה, שעסק בשמעתתא מדעתו (ונאמר בה באהבתה תשגה תמיד, ואמרו בירו' ברכות פ\"ה ה\"א דריש לקיש היה יוצא חוץ לתחום מחמת עסקו, וכמדומה דכן אמרו בר' עקיבא), וידוע שיש בזה לגרום, אבל כיון שהיה שוגג על המעשה מהלך את כולה, ובחזרתו כאילו לא יצא.\u003c/span>"}, {"s": "h7", "h": "שגגת התחום מול שגגת האיסור - שגגת תחומין באיסור עשיית מצב דחוץ לתחום"}, {"s": "p", "h": "ושוגג האמור לא נתבאר אם הוא לגבי ידיעת התחום, או זכירת שבת ואיסור תחומין, ולגבי הא דנבד\"ח הוא לכאורה אף לגבי ידיעת התחום (וכמו לגבי סדינו מוטל, ובזה הוי מתעסק לדעת אביי (אם פטור דאביי משום חטאת ולא משום מלאכת מחשבת, או אם גם תחומין חשיבי מלאכה), ולרבא הוי שוגג, ואיך שיהיה חשיב שוגג לענין זה), אלא שנראה שאין זה אלא משום שגגה דאיסור דאית ביה, היינו, שלא ידע שעושה בדבר אסור, שלא ידע שהילוך שלו הוא לחוץ התחום, וזה לכאורה אפילו במי שידע לתחום לענין ערי הלווים, או לרוצח בשגגה, ורק לא ידע לאיסור תחומין. וביאור זה כי גדר האיסור שיש ביציאה חוץ לתחום הוא באי שביתה."}, {"s": "h7", "h": "הולך אלפיים פסיעות כשאינו יודע - דין שמואל משום שוגג ולא משום ודאות מקומו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"673\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">16\u003c/sup>\u003cspan class=\"ca\" data-c=\"673\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכן משמע דהא אמרו במי שהיה הולך ולא היה יודע תחום שבת שמהלך אלפים פסיעות בינוניות, והרי דאיירי ביודע מקום שביתתו, ויודע האיסור, ומשמע דלולי שגילו לנו שיעור זה היה לאסור אפילו בספק, ואף שגם בשיעור זה לא יצא מכלל ספק, שאיכא למיחש דפסיעותיו יותר מאמה, אבל כיון דרובא דעלמא הוו בכך אין לו לחשוש, והוא משום דדי בזה להיחשב שוגג ולא מזיד, ואם היה גדר השוגג במציאות התחום לא היה להועיל לו רוב דעלמא.\u003c/span>"}, {"s": "h7", "h": "ספק בהגיע לקצה אלפיים פסיעות - חזרה תלויה בהילוך דתחום ולא במציאות בלבד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"674\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">17\u003c/sup>\u003cspan class=\"ca\" data-c=\"674\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אלא שעדין יש לבאר שאחר שהגיע לקצה אלפים פסיעות ויש לו להסתפק אם הוא בתחומו או לאו, דעתה כבר לא יועיל רובא דעלמא, ואין לו לחזור, ומשמע שגם גדר חזרה הוא משום הילוך דתחום. ובאמת שכך מבואר מדברי שמואל הנ\"ל דאמר וזו היא תחום שבת. וכן יש להוכיח ממה שהסתפקה הגמ' בתחומין למעלה מעשרה, וכתב רש\"י דלא חשיב הילוך, ותתמה מה יועיל דלא חשיב הילוך, הא כיון שעתה הוא חוץ לתחום אין לו לחזור, ומשמע שאין גדר חוץ לתחום אלא במה שהוא הולך חוץ לתחום, היינו, יוצא, וזה היפך ממה שכתבנו בגדר שלא לדעת לעיל.\u003c/span>"}, {"s": "h7", "h": "סוגיית הירושלמי בהילוך חוץ לתחום - חילוק מאיסורי הנאה שהאיסור במעשה עצמו ובגופו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"675\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"675\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אמנם שניהם אמת שכמו שכתבנו שאיסור יציאה חוץ לתחום הוא מעשה שלו בעצמו, שמעשה האיסור הוא בהליכתו, וחפצא דאיסורא הוא הוא עצמו, ותראה דזה בהיפך מחלבים ועריות, והיינו, שבהם האיסור הוא בתוצאה, והמעשה הוא בגדר התקרבות לתוצאה. אבל בתחומין האיסור הוא במה שאינו שובת, וזה נעשה ע\"י תוצאת היות לתחום, וכלשון הכתוב אל יצא איש ממקומו, והיינו, שאמר לכולם אל יצא, היינו, שלא תעשו מעשה יציאה, ומעשה זה הוא באיש, ויציאה היא ממקום אותו איש, וזה כמו שביעה דאכילה ביום הכיפורים, וע\"כ יהיה לאדם גדר גם במעשה וגם בתוצאה.\u003c/span>"}, {"s": "h7", "h": "יציאה וחזרה שלא לדעת בתחומין - תלות באיסור הגעת האדם למקום חוץ לתחום"}, {"s": "p", "h": "והנה יש לנו לבאר גדר יציאה וחזרה האמורה דבעינן שיהיו שניהם שלא לדעת בכדי שיחשב שלא יצא, והנה בפשטות אין איסור בחזרה לתחום אי לאו שיוצא מד\"א שלו, והפשטות לכאורה אין שייכות בין ד\"א אלו לתחומו, ולמה שיהיה זה תלוי בחזרה לדעת, ומשמע שהוא בגדר אחד, והיינו, שמניעת הילוך כולה בחוץ לתחום הוא משום שהגיע באיסור יצאת תחום אלפים, ומניעת כאילו לא יצא הוא משום שהגיע באיסור יציאת ד\"א. אלא דלפ\"ז היה להתיר יצא לדעת והחזירוהו נכרים, וזה אמר שמואל דאין לו אלא ד\"א, והיינו דביציאתו לדעת כבר הפסיד תחומו אף שלא נעשה איסור בתחומו, כי אין זה גדר כמו במניעת הילוך כולה, היינו, מה שהגיע למקום באיסור, שהפסד התחום הוא גדר באדם עצמו, היינו, שכיון שיצא באיסור דמקום אין לו מקומו, שאחר שעשה איסור בגופו נאסר לו להשתמש במקום גופו, וזה דעת ר\"ג. אבל ר\"ע ור\"י סברי דאין לו כלל מקום גופו, כיון דלא שבת בה מבעוד יום."}, {"s": "h3", "h": "ו. ד' אמות בדיר וסהר ובספינה ובירור סוגיית הירושלמי"}, {"s": "h7", "h": "דעת ר\"ע ור\"י בד' אמות - שלילת דין תחומין כשלא שבת באוויר מחיצות מבעו\"י"}, {"s": "p", "h": "והיינו, דד\"א שבאם הוו במקום המוקף מחיצות הוו בכל המקום, לית להו לר\"ע ור\"י ביוצא חוץ לתחום, אלא רק בשביתה דמבעוד יום, דסברי ר\"ע ור\"י שאין גדר ד\"א אלו חלק מדין תחום כלל, ומה שיש למי ששבת ד\"א מלבד אלפים, היינו, שאין למדוד אלפים במקום זה, משום שאין חשוב הילוך בו כהילוך דהתרחקות, שאין מתרחק במה שהולך שם ממקומו."}, {"s": "h7", "h": "מהלך את כולה לר\"ג ברש\"י - קולא שהקלו חכמים במי שאין לו אלא ד'"}, {"s": "p", "h": "והנה ברש\"י כתב דמה שסבר ר\"ג דיוצא חוץ לתחום שלא מדעת ונתנוהו בדיר וסהר מהלך את כולה, הוא קולא שהקילו במי שאין לו אלא ד\"א שיחשב האי ד\"א בכל המקום. והנה יש לבאר למה הוצרך לזה, היינו, לומר שהוא קולא, שהרי כתבו בגמ' דסברת ר\"ע ור\"י אפשר שהוא משום דלא שבת באוויר מחיצות מבעוד יום, וכמו שאמרנו שאין דין שנחשב כל המקום כד\"א אלא בשביתה דמבעוד יום, וא\"כ ר\"ג דחלק סבר דלא בעינן שביתה מבעוד יום, ומה דמהלך את כולה הוא בדין דחשיב ליה כולה כד\"א, ולא בעי לשבת מבעוד יום, ולא קולא הוא, וצ\"ב."}, {"s": "h7", "h": "דין שמואל לטלטל ע\"י זריקה - ספק אי מדובר בכליו או בחפצים של אחרים"}, {"s": "p", "h": "והנה האי דהתיר ר\"נ בשם שמואל לטלטל בכולה ע\"י זריקה, לא נתבאר אי הוה בכלים דידיה, היינו, שקנו שביתתו ואין להוציאם מאלפים דידיה, או בחפצים שאינם שלו. וברש\"י משמע דאיירי בחפציו, וכן משמע בפירושו במשנה לקמן (מה:). וא\"כ איכא למשמע מיניה דאף לגבי דיני תחומין חשיב כולה כד\"א, וזה קשה מדין דחצי מערה דמשמע שאין דיני תחומין תלויים ברשויות. ואמנם היה לחלק דבמקום דאין כל האלפים בתוך המחיצות אין לרשות אחת להתיר הילוך, אבל במקום שכל אלפים בתוכו יש להתיר. אבל חילוק זה אינו ברור דכיון שאלפים אינם תלויים ברשות, ואף בתוך רשות אחת שייך למדוד אלפים, א\"כ אף שכולם בתוכו אין לרשות להשפיע, ומאי שנא הילוך דגופו מחפציו."}, {"s": "h7", "h": "גזירת רב הונא טלטול אטו הילוך - אמאי הותר טלטול ונאסר הילוך בחצי מערה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"676\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">19\u003c/sup>\u003cspan class=\"ca\" data-c=\"676\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וברש\"י שם כתב יותר מזה דאף טילטול דבתוך ד\"א דחפץ אסור מחוץ לד\"א דידיה לתוכו דהוי כרשות היחיד, ואף דהוי בתוך ד\"א דתחום דחפץ, דד\"א דשביתה הוי כרשות היחיד, ואעפ\"כ התיר להוציא חפץ דידיה מאלפים בתוך רשות אחת. והנה לולי דמשמע דאיירי בחפציו, היינו אומרים שמה שאמרו גזירה דטילטול אטו הילוך, היינו, טילטול דעלמא אטו הילוך דתחומין, אבל ממה שהתיר ר\"ה במשיכה (להאי גירסא), וכתב רש\"י דלא הוי חפציו עד שיכניס, ואין לגזור הילוך דידיה משום חפציו דלאו דידיה, משמע דגזר הגזירה הוא משום טילטול דתחומין. והיינו, דלגבי חפציו מדינא היה להתיר טילטולם אף מחוץ לאלפים, דכולה כארבע אמות, אלא דגזרו משום הילוך. וממה שדימה רש\"י דין זה לחצי מערה משמע דאף שיש לאסור הילוך דחוץ לאלפים, יש להתיר טילטול דחוץ לאלפים. וזה קשה דאם סברת מה שאין מותר הילוך הוא משום מרחק, שאין ברשות להגדירו, א\"כ גם לגבי חפצים וטילטולם היה לומר כן.\u003c/span>"}, {"s": "h7", "h": "שביתה באוויר מחיצות לגבי טלטול - איחוד המקום כמקום עמידה ולא לגבי הילוך"}, {"s": "p", "h": "ולבאר כל זה צ\"ל כמו שאמרנו בדעת ר\"ע ור\"י, שגדר מה שאין נחשב ד\"א דשביתה מבעוד יום חלק מאלפים, הוא משום שאין להחשיב הילוך במקומו כהילוך דהתרחקות, וזה גדר שלילי, והיינו, שאין אנו אומרים שהיה להתחיל את מדידת אלפים ממקום עמידתו רק שבתוך ד\"א דשביתה חשיב כאי מרחק, אלא היינו טעמא דאינו חשיב מהילוך דאלפים, משום דהוה כל ד\"א כמקום עמידתו, וכאילו לא זז. וזה יהיה ביאור במה שהותר לטלטל ע\"י זריקה, היינו, שאמנם לגבי הילוך אין במחיצות שלא שבת בהם להגדיר כל המקום כמקום עמידתו, אבל לגבי טלטול חפצים יהיה כן."}, {"s": "h7", "h": "חילוק מקום עמידה מהילוך בתחומין - גזירת רב הונא בטלטול חפציו משום הילוך דגופו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"677\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">20\u003c/sup>\u003cspan class=\"ca\" data-c=\"677\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וביאור זה משום שגדר מקום עמידתו הוא ביחס להילוך, ואין במקום מוקף להגדיר הילוך, וכמו בחצי מערה, אבל לגבי הינוח חפצים במקום המוקף לדירה, אין נחשב טילטול כלל, וחשיב בתוך ד\"א, ואפילו חוץ לאלפים אין נחשב, כיון דהוי בתוך ד\"א דמקום שביתה, והיינו גזירה דר\"ה, דכיון שלא חשיב האי מקום כולו כד\"א לגבי הילוך, אי נתיר שיחשב כד\"א לגבי טילטול דחפציו, וביחס לדיני תחומין היינו דהוי כרגלי הבעלים, יבואו להתיר אף הילוך. שיאמרו אם נחשב כל המקום כד\"א, גם לגבי הילוך יחשב כד\"א (ובזה יש אפילו להתיר יותר, שיבוא למדוד אלפים מחוץ למקום, היינו, דיהלך את כולה וימדוד לה אלפים מחוץ לה).\u003c/span>"}, {"s": "h7", "h": "תליית דין שמואל בר\"ג ור\"ע - דחיית התלייה משום דדילמא ר\"ע גזר בבקעה"}, {"s": "p", "h": "וזה רצו לתלות במח' ר\"ג ור\"ע, והיינו, שיש לומר דכולי עלמא ס\"ל דד\"א דאית ליה חוץ לתחום, חשיבי בכל המקום, אלא שר\"ע גזר משום בקעה, ור\"ג סבר שאין לגזור. וזה דחו דאפשר דר\"ע סבר דאין ד\"א אמות אלו שנתנו לו חשיבי בכל המקום, משום שלא שבת באוויר מחיצות, וכן שמה דלא גזר ר\"ג הוא דווקא בשתי מקומות, היינו, דיר ובקעה, אבל בהא יגזור. ובתוס' הקשו איך רצו להעמיד דברי שמואל לדעת ר\"ג כיון שלא פסק כוותיה בדיר וסהר, ולרש\"י נראה דביאורו הכין, דהרי אף ר\"ג מודה דמודד אין לו אלא חצי מערה, ואעפ\"כ התיר שמואל לטלטל, והיינו, שד\"א דטילטול חפצים אין שייך בו סברא דמרחק ברשות אחת, והרי זה כמו למ\"ד אין תחומין למעלה מי', והרי זה כד\"א דנותנים לו אף לר\"ע, וא\"כ אין תלוי במח' כלל."}, {"s": "h7", "h": "ספק איסור ר\"ע בדיר וסהר - אי איסורו משום גזירת בקעה או חסרון שביתה"}, {"s": "p", "h": "אלא שהיה להסתפק בדעת ר\"ע אם הוא משום גזירה, משום דלא שבת, אבל לגבי טילטול דחפצים אף לר\"ע כולו כד\"א, ואף אם נאסור ביוצא חוץ לתחום ונתנוהו בדיר וסהר ואין אלא ד\"א ויהיה אסור להוציא חפצים, הרי זה משום דהוי כרשות היחיד, וכמו דכתב רש\"י במשנה, אבל הכא דאית ליה אלפים ליתא, וכרש\"י התם, שאין אלפים כרשות היחיד, ובהכרח דד\"א דשביתה דאית ליה לגבי הילוך אין בהם לאסור טלטול חפצים, שהרי בתוך אלפים מותר אף שהוא מחוץ לד\"א, ואף לר\"ע מותר מתוך ד\"א דשביתה לחוץ להם בתוך ד\"א דחפץ, ואין בד\"א דשביתה לאסור, ואף מה דאסר ר\"ה לא אסר אלא משום שאלפים נפרצו לחוץ להם, וד\"א דאמר היינו, ד\"א דחפץ, וזה ביאור הגזירה דר\"ה, היינו, דכיון שאין ד\"א של הילוך חשיבי בכל המקום, אי נתיר לו טילטול יהיה לו לחשוב שאף ד\"א דהילוך הוי בכל המקום, ושאין חשוב הילוך דמקום המוקף כהילוך. וזה מה שדמו למח' ר\"ע ור\"ג, שהיה לומר דכולי עלמא סברי דבנתנוהו בדיר וסהר יש לו להלך בכל המקום, מטעם שאין חשוב הילוך יציאה מתחום, והיינו, דכיון שהמקום כולו מוקף אין להגדיר ד\"א נפרדים, שנאמר שהילוך חוץ להם הוי יציאה מהם, והיינו, שאחר שמהלך מקומו החדש הוי ד\"א דידיה, וממילא לא שייך לאסור הילוך, דאין זה יציאה ממקומו. אלא דר\"ע גזר שאם נתיר לו הילוך משום כן, יש לו לומר אף בבקעה כן, ור\"ג לא גזר, ואף דשמואל ס\"ל בדיר וסהר כר\"ע, אין זה אלא רק לגבי הילוך, שגדרו בבקעה הוא קביעות מקום, אבל לגבי הינוח חפץ אף ר\"ע יודה בבקעה שמותר, שאין זה נחשב יציאה לגבי חפץ (ומה שנאסר במשנה הרי זה משום דד\"א חשיבי רשות היחיד, וזה לא שייך במי שיש לו אלפים), אלא שיש לומר דכמו שגזר ר\"ע הילוך דדיר וסהר משום הילוך דבקעה יש לו לגזור טלטול משום הילוך, ור\"ג לא גזר, וסבר שמואל כר\"ג, ומה שלא התיר בדיר וסהר כר\"ג משום דחשיב ליה הילוך."}, {"s": "h7", "h": "ספק הירושלמי בד' אמות דיוצא - פשיטות ר' זירא דלית ליה ד\"א מב' מקומות"}, {"s": "p", "h": "ולביאור דבר זה יש להביא מה שנסתפקו בירו' אי ארבע אמות שאמרו למי שהוציאוהו חוץ לתחום הוא משום תחום אי לאו, ואמרו שיהיה תלוי בזה אי יש לו ארבע אמות משני מקומות, ופשט ר' זירא דהם משום תחום מהא דהיו שנים לא יוציא מתוך שלו, ושם לקמיה אחר שהביא מח' חברייא (ובתלמוד דידן הוא משמיה דרבה) ור' זירא בסיבת היתר ספינה יותר על דיר וסהר, אי משום מחיצות, אי משום שנוטלתו וכו', ואחר כן אמר ר' זירא ששמיענן מיניה דאין ארבע אמות משום תחום, והוא סתירה."}, {"s": "h7", "h": "ביאור דברי ר' זירא בסוגיא - בדיר וסהר מודי דאית ליה משתי מקומות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"678\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">21\u003c/sup>\u003cspan class=\"ca\" data-c=\"678\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ולפי מה שביארנו יש לחלק, דהא דר' זירא שאינם משום תחום אמרה אדיר וסהר, היינו, מה דסברי ר\"י ור\"ע דאין לו אלא ד\"א, ומה שאמר ששהן משום תחום אמר בבקעה, והיינו, שאף שיש לומר דד\"א בבקעה הרי הם משום תחום, בדיר וסהר אין הוא משום תחום, ואף דודאי משום תחום יש כל דיר וסהר, ומה שאין לו אלא ד\"א הרי זה משום שלא נתנו לו אלא ד\"א דידיה, היינו, שסביבותיו, ובאמת בדיר וסהר יודו ר\"ע ור\"י דיש לו משתי מקומות, והיינו, דמה שנסתפקו בתחילה אי הוה משום תחום או לא, הוא שהיה לומר שאמנם אין לו להלך חוץ לתחום כיון שאין זה מקומו והוי כיוצא חוץ לתחום עוד ועוד, אבל זה שייך רק במי שיש להחשיבו כמהלך, אבל בתוך ד\"א אין חשיבא הילוך, וזה ביאור שאינו משום תחום.\u003c/span>"}, {"s": "h7", "h": "ד' אמות דיוצא משום תחום - מקומו הנוכחי נקבע לתחומו ושתי אמות לכל רוח"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"679\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">22\u003c/sup>\u003cspan class=\"ca\" data-c=\"679\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אבל אי נימא דהוה משום תחום, היינו, שאמרו שמעתה יהיה מקומו הנוכחי כתחומו, וא\"כ ד\"א אלו חשובים כאלפים, ויש לו גבול, וע\"כ יהיה קבועים ב' מכאן וב' מכאן, ואין מועיל מה שתוך ד\"א לא חשיב הילוך, וכמו בחצי מערה. אבל בדיר וסהר אי נימא דיש לו תחום הרי תחומו בכל הדיר וסהר, ומה שאמרו ר\"ע ור\"י שאין לו אלא ד\"א אינו משום תחום, אלא משום הילוך שאסרו להלך חוץ לתחום דמעיקרא. והיינו, שיש לנו לאסור במי שיצא חוץ לתחום מתרי טעמי, האחד, משום מקומו, היינו, אם יצא חוץ למקומו העכשווי. והשני, משום הילוך דחוץ לתחום דמעיקרא, ואמנם אין בדיר וסהר משום חוץ למקומו עתה, שהרי כל המקום הוי כד\"א, אבל יש בזה משום הילוך דחוץ לתחום דמעיקרא, וזה הרי אינו תלוי במקומו העכשווי אלא בשם הילוך, אבל זה אינו אלא בהילוך דד\"א, ואפילו משתי מקומות, ואף בזה נחלק ר\"ע. והיינו דסבר ר\"ע שאין הילוך דחוץ לתחום תלוי במקומו העכשווי, אלא הוא הילוך סתם, והיינו, דאף בנוטלתו לא יועיל ללכת ארבע אמות, דכיון שהוא הולך ארבע אמות הוי הילוך אסור, ואף שלגבי מקומו אין זה הילוך, שהרי הוא תמיד בתוך מקום שלו, אבל דין הילוך דחוץ לתחום אינו תלוי בזה, והיינו דאף שמודה ר\"ע שמותר להלך בתוך ד\"א, אין זה אלא משום שיש בד\"א להגדיר הילוך בו כלא הילוך, אבל ר' יהושע דחלק בספינה סבר דאין הילוך נחשב הילוך אלא ביחס למקומו העכשווי, והיינו, ד\"א שיש לו עתה, ואי לא חשיב יציאה מד\"א אלה גם לגבי תחומו דמעיקרא, לא חשיב הילוך.\u003c/span>"}, {"s": "h7", "h": "דברי ר' זירא בדיר וסהר - אינו משום תחום אלא שהילוך בד' אמות לא חשיב"}, {"s": "p", "h": "והיינו דאמר ר' זירא דד\"א שאמרו אינו משום תחום, היינו, ד\"א דיוצא חוץ לאלפים, שהילוך בהאי ד\"א לא חשיבי הילוך, אינם משום תחום, אלא תחומו במקום עמידת רגליו, ומה שהותר בד\"א הוא משום דלא חשיבא הילוך. וזה כמו שאמרנו בדעת ר\"י דאית ליה לברור, והיינו, דאף ר\"י סבר דד\"א הוא משום תחום, ואין לו ד\"א משתי מקומות, אלא דסבר דכיון שאין להחשיב הילוך בתוך ד\"א דמקום עמידת רגליו, אין בעמידתו להגדיר ד\"א דתחום, אבל אחר שבירר הוו האי ד\"א תחום, ואינו יכול לחזור בו לקבוע תחום ככל שובת."}, {"s": "h7", "h": "שביתה במקום היקף מחיצות מבעו\"י - מהלך את כולה וחוצה לה אלפיים כד' אמות"}, {"s": "p", "h": "וא\"כ מה שמצאנו שמי ששבת במקום היקף מהלך את כולו וחוצה לו אלפים, טעמו משום שנחשב מקום עמידתו בכל המקום (וחלקו חכ' ור\"ע בנותן), וכמו ד\"א שנותנים למי ששבת חוץ ממדידת אלפיים, כי נחשב שעומד בכל ד\"א, ומי שיצא חוץ לתחום שיש לו ד\"א, היינו, שנחשב עמידת רגליו בכל ד\"א שסביבו, וכתחום, כי ד\"א אלו מוגדרים בקרקע שנחשבת כמקומו. ובנתנוהו בדיר וסהר סבר ר\"ג דחשיב עמידת רגליו בכל המקום, ומהלך את כולה, ור\"ע ור\"י חלקו."}, {"s": "h7", "h": "ב' טעמים באיסור ר\"ע בדיר - שלילת אחידות המקום כולו או גזירה משום בקעה"}, {"s": "p", "h": "ואית לן למימר בה שתי סיבות, או משום דסברי שאין נחשב עמידת רגליו בכל המקום, דזה דלא אמרינן זה אלא במי ששבת באוויר מחיצות מבעוד יום, או דאכן מודו שחשוב עמידת רגליו בכל המקום, רק שגזרו הילוך דדיר וסהר, היינו, חוץ לארבע אמות משני מקומות, משום הילוך דבקעה, דחששו שיאמר ההולך בבקעה שמה שהעומד בדיר וסהר מהלך, הוא משום שנחשב הילוך בכל המקום כהילוך בתוך ד\"א, ואין הילוך פחות מד\"א נחשב הילוך, ואף שיוצא מד\"א דמקומו, ויעשה כן אף בבקעה ללכת פחות פחות מד\"א, ובשבת בבקעה והקיפוה נכרים אין נחשב עמידת רגליו בכל המקום, משום שכשקנה שביתה מבעוד יום לא קנה אלא בד\"א, אבל לגבי חפציו חשוב כל המקום כד\"א, והיינו, דטילטול בתוכו חשיב כטילטול בתוך ד\"א. ור\"ה סבר שיש לגזור שאם נתיר לו לטלטל חוץ לד\"א, ומשום שאינו נחשב לשינוי מקום, יאמר שאף אינו נחשב להילוך, ויש לנו לגזור טלטול משום הילוך. ור\"נ סבר שאין לגזור טילטול משום הילוך, משום דמה דחשיב כד\"א לגבי טלטול הוא משום שהמקום כולו אחד, ואין לזה שייכות להילוך שהוא משום מקומו, ולא מקום סתם, ומה שאסרו ר\"ע ור\"י הוא משום דסברי שאין נחשב עמידת רגליו בכל המקום, משום שלא שבת בה מבעוד יום, אבל לגבי טלטול ליכא למ\"ד דבעינן לשבת מבעוד יום, שאין טילטול אלא בקרקע, והרי היא אחת. ואכן סבר שמואל כר\"ע וכר\"י דלגבי הילוך דתחומין נתנוהו בדיר וסהר לא חשיב עמידת רגליו בכל המקום, ואין לו אלא ד\"א, ואף שכל המקום נחשב למקום אחד אין זה מועיל גבי הילוך חוץ לתחום, וד\"א אלו הוו כתחום. אבל בספינה מודה משום דליתא לד\"א דתחום, או משום שאין לקנות ד\"א בספינה, או משום ששבת באוויר מחיצות."}, {"s": "h7", "h": "סברת ר\"ע לאסור בספינה בנוטלתו - הילוך חוץ לד' אמותיו חשוב הילוך בלא תחום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"680\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">23\u003c/sup>\u003cspan class=\"ca\" data-c=\"680\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואי נימא שהוא משום שאין לקנות ד\"א בספינה משום דנוטלתו, סברת ר\"ע לאסור בזה הוא משום שאין לילך שלא בתחומו, והילוך חוץ לד\"א שלו חשיב הילוך, ואפילו שאינו יוצא ממקום שביתתו. ואי נימא שהוא משום שבת באוויר מחיצות, סברת ר\"ע לאיסור הוא משום שאין למי שיצא ממקום שביתתו להלך, והילוך אף במקום אחד חשוב הילוך, ומה שמותר בתוך ד\"א הוא משום שאינו נחשב הילוך, ואפ' בשתי מקומות. ומכל זה יבואר שאיסור תחומין מורכב משלושה חלקים, הדבר, מקום הדבר, והמעשה בדבר ובמקומו. והאיסור הוא להוציא דבר ממקומו.\u003c/span>"}, {"s": "h3", "h": "ז. היתר הוצרך לנקביו ושבת באוויר מחיצות מבעוד יום"}, {"s": "h7", "h": "פשיטת רבא בהוצרך לנקביו לצאת - כבוד הבריות שאינו נחשב הילוך לדעתו כלל"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"681\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">24\u003c/sup>\u003cspan class=\"ca\" data-c=\"681\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ולפמשנ\"ת יש לבאר מה שהביאה הגמ' בעי דהוצרך לנקביו, ומה שפשט רבא. והיינו, שהרי מי שהוציאוהו חוץ לתחום ואין לו אלא ד\"א, נמנעים ממנו צרכים רבים כאכילה ושתיה, והוא כיושב בבית הסוהר, ולא הותר לצאת מחמת כן חוץ לד\"א, והיה לומר דאף זה יש לו לסבול. וזה אמר רבא שאינו נחשב כצרכיו, אלא זהו מכבוד הבריות, היינו, מה שיש לאדם לכבד גופו כאילו היה של אחר, ואין זה נחשב כעשיית רצונו אלא כדבר מצוה, וע\"כ תחשב יציאתו כאילו הוציאוהו נכרים, היינו, שאין הילוך שלו, אלא כאילו אחר מוליכו, וע\"כ אמרו נהרדעי דאי פיקח הוא עייל לתחומא, היינו, דכיון שאין זה נחשב כהילוך, הרי שאין זה כיוצא, ואי עייל לתחומא לא נחשב כחזר לדעת, ואפילו לרבנן דאמרי אפילו אמה אחת לא יכנס, כאן יש לו להיכנס.\u003c/span>"}, {"s": "h7", "h": "דעת רש\"י ברבה דעל על - נכנס לתחום שביתתו אינו קונה במקום עמידתו"}, {"s": "p", "h": "ובזה יבואר דעת רש\"י שכתב דרבה גופיה לא ס\"ל להא דעל על, והוא שכמו שאמרנו גדר האי דעל הוא משום שע\"י הילוך, כבר אין להחשיבו כעומד לענין קניית ד\"א, ואין קונה עד שיעמוד, וכמו שבהיותו בתוך התחום אין קונה ד\"א דתחום במקום שעומד אלא במקום ששבת, כך לגבי האי, שכיון שנכנס למקום שהוא תחום מקומו, אין אנו אומרים שיהיו ד\"א שלו במקומו הנוכחי, אלא במקום ששבת. וכן הוא בעניינו, שהרי סבר רש\"י דמה שהותר לו הוא שיצא מד\"א ויעשה צרכיו ויחזור, ולא יחשב שיצא, וזה ממש כמו תחום דרשות, היינו, שיש ליוצא ברשות מקום שביתה שלו ואלפים הוי תחומו, ושאין לו לקנות שביתה בכל מקום שעומד, ונחשב שמקומו היכן שנודע לו (אבל לדעת ר\"ח שמה שאמרו נהרדעי היינו שיעשה צרכיו במקומו ואחר כן הרי יהיה חייב לצאת כבר יכנס לתחומו, שפיר, שהרי יש לו לקנות מקום חדש. אבל רש\"י סבר דזה לא הותר לו, והיינו, דמה שהתיר רבא הוא לא קנית שביתה חדשה, אלא יציאה מד\"א וחזרה אליה, וזה ממש כמו היוצא ברשות, וזה מה שהביאה הגמ' דעת רב פפא בפירות שיצאו חוץ לתחום)."}, {"s": "h7", "h": "מחלוקת ר\"ע ור\"ג לדעת רבה - חילוק שביתה בתחום מיציאה חוץ לתחומו המקורי"}, {"s": "p", "h": "ונשוב לענייננו והנה עכ\"פ לדעת רבה נחלקו אי מהני שבת באוויר מחיצות, והיינו, דר\"ע סבר שאף ששבת באוויר מחיצות, והרי מהני זה למדוד לו אלפיים חוצה להם, זה אינו אלא כשהוא בתוך התחום, אבל אחר שיצא מן התחום בטלה שביתה, והוי ליה שביתה חדשה, ולא מהני מחיצות, כמו מה דלא מהני בדיר וסהר."}, {"s": "h7", "h": "דעת ר\"ג בלא שבת באוויר - אמאי פסק שמואל כמותו בספינה ולא בדיר וסהר"}, {"s": "p", "h": "אבל הנה יש לדון בדעת ר\"ג דכיון דאית ליה דאף בדיר וסהר מהלך את כולה, הרי דלא בעי לשבת באוויר מחיצות, ולפ\"ז הלכה דאמרו דלא מטעמיה כלל, וצ\"ב, דמאן יימר לן דאיכא למאן דאמר כהאי (והרי לא אמר שמואל הלכה כר\"י וכדתניא לקמן), ומשמע דסבר רבה דאף ר\"ג מודי דבזה לא יועיל אלא משום דשבת באוויר מחיצות, וגרעה ספינה מדיר וסהר, דאם לא קנה שביתה אלא באמצע שבת לא יועיל מה דכולה כד\"א משום מחיצותיה, והיינו, דמה שמועיל בדיר וסהר הוא משום ד\"א דקרקע עולם, דכיון שד\"א הנתונים לו נמצאים במקום שנחשב כולו אחד, הוי שביתתו בכולו, וזהו תחומו, אבל בספינה כיון שנעה, אין לד\"א דקרקע עולם שייכות עם קרקע ספינה, אבל בשבת באוויר מחיצות כיון שיש לו לקנות ד\"א חוץ מתחומו, הרי דהאי ד\"א אינם משום תחום, אלא משום מקום שלו, וזה תלוי בו ולא בתחומו, ואף אחר שיצא חוץ לתחום, ואף אחר שתנוח הספינה אין לו לקנות ד\"א חדשים, שזה כבר יש לו."}, {"s": "h7", "h": "שייכות דיר וסהר לדין ספינה - סברות ר\"ע מגזירת בקעה או מחסרון שביתה מבעו\"י"}, {"s": "p", "h": "והנה יש לבאר מה שייכות יש בין שני דינים אלו, היינו, דיר וסהר וספינה, שנחלקו בהם ר\"ע ור\"ג, והנה בגמ' לעיל אמרו שתי סברות בדעת ר\"ע, או משום דגזר אטו הילוך בקעה, או משום דלא אמרינן כל הבית כד\"א אלא בשבת באוויר מחיצות מבעוד יום, ולרב נחמן דאמר מטלטל בכולה בענין למימר דהוא משום דלא שבת באוויר מחיצות, ולרב הונא ניחא אפילו שבת באוויר מחיצות, דגזרי, ואפשר דאפ' בלא שבת הוי כד\"א, ולא אסרו אלא משום גזירה, ומשמע דשתי סברות אלו אינן אלא בדיר וסהר, היינו דניגזור משום בקעה דדמיא ליה, אבל בספינה לא, וכן דבספינה הרי שבת באוויר מחיצות כדאמרינן לקמן (ובתוס' אמרו דצ\"ל דסבר ר\"ע דלא מהני משום דלהבריח מים עשויות), וברש\"י דכתב בדעת רבה דמעליותא דספינה משום שבת באוויר מחיצות, ובמהלכת לא פליגי אלא בשעמדה, היינו דסבר ר\"ע דעד עתה לא קנה לו ד\"א משום שהיתה מהלכת, ועתה יש לו לקנות, ולא מהני דשבת באוויר מחיצות, ואפ\"ה שרי ר\"ג משום אוויר מחיצות, ומשמע דאף ר\"ג סבר דעד עתה לא קנה. וא\"כ צריך ביאור מה מהני מה דשבת באוויר מחיצות מבעוד יום אחר שלא קנה באותה שעה. ורבה מבעוד יום קאמר, והנה לכאורה היה נראה דמעלת מבעוד יום, היינו, לפני שקנה שביתה, והרי בכל אלו הוה אוויר מחיצות קודם שקנה (מלבד במח' ר\"ה ור\"נ)."}, {"s": "h7", "h": "בירור דעת ר\"ג בספינה לרבה - שבת באוויר מחיצות אינו תלוי בקניית שביתה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"682\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">25\u003c/sup>\u003cspan class=\"ca\" data-c=\"682\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ועוד יש להקשות דכיון דסבר ר\"ג דלא בעינן לשבת באוויר מחיצות, וכמו בדיר וסהר, למה שנאמר דכאן הוא משום אוויר מחיצות, ומה לי הוציאוהו נכרים או הוציאתו ספינה, ולא משמע דבספינה חשיב לדעת, וגם לא משמע דהוא תלוי בדעת, מהא דמקשינן ארב נחמן אמר שמואל דיצא לדעת אין לו אלא ד\"א דהוא פשיטא, ומאי קושיא, דילמא אמר כן לר\"ג ואפילו בדיר וסהר, דכיון דהוא לדעת לא אמרינן האי קולא, וכדכתב ברש\"י. ועוד דאין לומר שהיו מפליגין אי הוה חשיב לדעת (ואף שיש לחלק דאיכא לדעת דחשיב מזיד ואפילו חזר לתחום אין לו אלא ד\"א, ואיכא לדעת דאף באונס חשיב לדעת, לענין מהלך את כולה, מהא דלא מתרצינן הכי לר\"נ א\"ש, וכדלעיל). וצריך לומר כדלעיל, דהיינו, שאין גדר דשבת באוויר מחיצות מבעוד יום משום דהוא קודם קניית שביתה, ואינו תלוי כלל בקניית תחומין.\u003c/span>"}, {"s": "h7", "h": "ספק ד' אמות חוץ לאלפיים - אנשי עיר שנתנו עירובם בעיר אחרת מהלכים כולה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"683\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"683\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והיינו, דהנה מצאנו שנסתפקו אי יש לנותן עירוב ד\"א חוץ מאלפיים דקנה, ויש להקשות דהא לכ\"ע אנשי עיר שנתנו עירובם בעיר אחרת, הוי האי כולה כד\"א, ומהלך את כולה וחוצה לה (ור\"ע חולק אף בעיר בנותן את עירובו אבל בשבת מודי, כדכתב רש\"י התם, וכדמשמע הכא, ולא העמידו מחלוקתם באי נותן את עירובו אית ליה ד\"א), ומשמע שאין זה תלוי בזה, והיינו, שגדר מה שנחשבת עיר חוץ למדידת אלפיים הוא משום שחשיב ששבת בכל העיר, ואפילו אי לית ליה ד\"א דאלפים, היינו, חוץ לשביתתו, ואפילו אי לא יהבינן ד\"א לנותן, כיון דמקום שביתתו הוא במקום עירובו, ומקום זה הוא בתוך עיר חשוב כשבת בכל העיר, וישיבתה אחת היא, וכן הוא במקום מוקף מחיצות סתם, או הוקף לדירה, למר ולמר כדאית להו התם, בנותן, אבל בשבת כ\"ע מודו (ומשמע שאין זה תלוי בבעיא דרמי בר חמא, והיינו, דלר\"נ אפשר שיהיה לו ד\"א חוץ לאלפיים). ומעתה יש לומר דאמנם יצאה הספינה חוץ לתחום, אבל הרי אין דין מה ששבת באוויר מחיצות קשור לתחום, שהרי נמדד חוצה לו, והוא משום שנחשב שביתתו בכל המקום.\u003c/span>"}, {"s": "h3", "h": "ח. אחידות מקום מוקף ושיטת רבה בד' אמות דספינה"}, {"s": "h7", "h": "אחידות מקום מוקף לענין הילוך - ב' צדדים באחידות המקום ותלייתן במחלוקת ר\"נ ור\"ה"}, {"s": "p", "h": "וביתר ביאור שיש לדון בגדר מה שנחשוב מקום מוקף כולו כאחד לגבי הילוך מי שאין לו תחום, שהיה אפשר לומר בזה שני אופנים, או דכיון שיש לו ד\"א והאי ד\"א הם אחד עם שאר המקום, הרי שהילוך חוץ להם אין נחשב יציאה מהם. או שנאמר דכיון שמקום זה מוקף והוא אחד אין שייך בו כלל ד\"א נפרדים, שאין שיעור ד\"א אלא משום מקום אחד, ובמקום מוקף כולו אחד. והנה אמרו דיש להעמיד דברי ר\"ע אף לר\"נ אמר שמואל דמטלטל ע\"י זריקה, ומה שאין לו אלא ד\"א הוא משום דלא אמרינן כל הבית כד\"א, אלא בשבת באוויר מחיצות. והרי לר\"נ ודאי נחשב המקום אחד שהרי לגבי טלטול חשיב אחד, וגם אין לומר כלל ששביתתו תעשה גדר במקום, והיינו, כאידך גיסא, ונצטרך לומר שגדר מה שנחשב כל המקום אחד בשבת באוויר מחיצות אין זה משום אחידות המקום שלעצמו, אלא משום דהשביתה הופכתו להיות אחת, והיינו, דמה דעבדי מחיצות המקום אחד הוא רק ביחס לקרקע המוקפת, ולא ביחס לאווירה, ואין הילוך בקרקע אלא באווירה."}, {"s": "h7", "h": "ספק תחומין למעלה מעשרה טפחים - איסור הילוך אינו תלוי בקרקע כדחזינן מהילוך בשם"}, {"s": "p", "h": "אלא שזה צ\"ב שהרי נסתפקו אי איכא לתחומין מעל עשרה, ואי לא, משמע שהוא משום דאינו רשות קרקע, ואין הילוך אלא בקרקע. וזה לא קשה דהרי נסתפקו אף בהילוך דע\"י שם, וזה ודאי לא נחשב הילוך בקרקע, וליכא למ\"ד דשרי בתוך י', וא\"כ יש להוכיח בהיפך, דודאי אין הילוך דתחומין תלוי בקרקע, ומה דאיכא למ\"ד דאין תחומין למעלה מעשרה, הוא משום שאין להחשיב מקום דהילוך, היינו, אלפים שלא בקרקע."}, {"s": "h7", "h": "ב' גדרים בהילוך ובתחומין בשבת - עצם ההילוך וגדר יציאה ממקומו בקרקע"}, {"s": "p", "h": "וביאורו שיש כאן שני גדרים, גדר הילוך עצמו, ומה שנחשב הילוך, וזה לא תלוי בקרקע, וכמו ע\"י שם. וגדר מה שנחשב הילוך במקום חוץ לאלפים כהילוך אסור, שאין להחשיב הילוך שלא בקרקע כיציאה ממקומו, דאף שאין הילוך תלוי בקרקע מקומו, ודאי תלוי בקרקע, וכן יציאה ממקומו, והיינו, דכמו שאין לאסור עלייה למעלה מאלפיים משום תחומין, ואף שמתרחק אלפים, כי אין יציאה האסורה אלא ממקומו, ולא יציאה ממקום בכלל, אבל המהלך בתוך י' אף שאינו מהלך בקרקע חשיבא יציאה. וכן הוא בעניינו דזה ודאי דאין בהיקף מחיצות דעבדי הקרקע לאחת, להגדיר הילוך, שאין הוא תלוי בקרקע, ומה שנחשב מי ששבת באוויר מחיצות שיהיה לו כל הבית כד\"א, הוא משום שבזה יש לו להחשיב ששביתתו בכל המקום, כי יש גדר בשביתה שאין הילוך במקום שביתה חשיב הילוך, אלא חלק משביתה."}, {"s": "h7", "h": "שביתה במקום מוקף מחיצות ושאינו - מקום מוקף מחיצות מבעו\"י נחשב כולו כשביתה אחת"}, {"s": "p", "h": "ואמנם במקום שאינו מוקף, אין להגדיר שביתה ביותר מד\"א, אבל במקום מוקף שפיר דמי, וזה משום משמעות אחידה שיש בשימוש המוקף מחיצות, שאין הוא שימוש דהילוך, היינו, שינוי מקום. אלא שלמדנו שאין זה מועיל בכלתה מדתו במערה, והיינו, שאין זה גדר בהילוך שהוא נושא של מרחק ממקום, שהרי במה שנמדד הילוכו ביחס למקום אחר, בהכרח שאין מדידה זו תלויה במקום ההילוך. אבל במקום שביתה אין איסור היציאה מד\"א משום מרחק ד\"א מנקודת שביתתו, אלא משום יציאה ממקום למקום, דבתוך ד\"א הוי מקום אחד, ומחוץ לו הוי מקום אחר, וא\"כ הוי דבר התלוי במקום, ויש בהיקף להגדיר מקום. אלא דהאי מקום אינו הכוונה קרקע, היינו, מקום הינוח אלא אווירה, היינו, מקום שימוש, ולא אוויר הטפל לקרקע, אלא אוויר עצמו, ואין היקף לגבי אוויר אלא במחיצות, היינו, אוויר מחיצות. ואמנם יהיה אוויר חלוק ע\"י מחיצות גם בלי שביתה, אלא דלגבי מה שנחשב האוויר אחד לא יועילו המחיצות, שאין שייכות בין אווירים שבין המחיצות אלא משום קרקע, ואין גדר שימוש דשביתה, היינו, אוויר, בקרקע. ואמנם שביתה עצמה, היינו, היכן שהוא יושב ודאי הוי בקרקע, אבל מה שיש בשביתה זו להגדיר הילוך הרי הוא באוויר, שע\"י שנחשב האוויר, היינו, מקום שימוש, גם הילוך בקרקעו לא יחשב הילוך שיש בו ביטול שביתה. אלא שיש במחיצות להגדיר האוויר אחד כיון שהם חולקים אותו מכל צדדיו, והרי הוא חלוק באחת לאחד, אבל כיון שאין להגדיר האווירים לאחד גם אין המחיצות פועלות באחת, וזה במה שנחשבים כל המחיצות, היינו, החלוקה להיקף, יש להגדיר ע\"י ששבת שם מבעוד יום, ואין זה שייך לקניית שביתה, שבקניית שביתה יש לברור מקום, ולא להגדירו, אבל אי שבת שם מבעוד יום, היינו, בזמן בין השמשות, שיש בו להגדיר הדברים שיש להכינם לכל השבת, אזי יש לו להגדיר האוויר לאחד, וזה יועיל אפילו בלא קניית שביתה. וכמו שאמרנו דסבר ר\"ג דאף במהלכת מתחילת השבת דליכא למיקני שביתה ע\"י ששבת שם מבעוד יום, לכשיקנה תהיה קנייתו בכל המקום כאחד, והיינו, קרקע משום אוויר להגדרת אוויר."}, {"s": "h7", "h": "שבת באוויר מחיצות אליבא דשמואל - חילוק מחיצות אוויר לתחומין ממחיצות המיוחדות לקרקע"}, {"s": "p", "h": "ובזה יבואר מה דמקשינן דהאי סברא, היינו, דשבת באוויר מחיצות מבעוד יום, הוא אף לשמואל דסבר דלא חשיבי מחיצות לעניין יותר מבית סאתיים משום דלהבריח מים עשויות. ועוד קשה דהא משמע דסברא זו היא אף לרב, דאמרו בספינה מיהת דכולי עלמא מודו, והרי איהו ס\"ל דהוי מחיצה, ואפילו לעניין בית סאתיים, ומה דחה ר' זירא דלהבריח מים עשויות, וביאורו כמש\"כ באריכות במק\"א דעיקר מחלוקתם הוא בגדר מה דמחיצות נחשבות כחוצצות אוויר הרשות, והיינו, דרב סבר דגדר מה דאמרינן היקף לדירה אף שהוא גדר שימושי, ובאווירה אין זה גדר באוויר אלא במה דהוי האי מחיצות לקרקע, וע\"כ אין משמעות בהוקף לדירה אלא ביחס לקרקע. ושמואל סבר דהוקף, היינו, האוויר, אבל אין זה גדר באוויר אלא ביחס לקרקע, היינו, דהיקף לדירה יש בו לאחד אוויר, וע\"כ יש בו להגדיר את הקרקע כאחת, וע\"כ יהיה משמעות במה שאין מחיצות לאווירה אלא משום להבריח מים. אבל לרב אין המחיצות כהיקף לאוויר כלל, אלא לקרקע, ושימוש קרקע דספינה לדירה. אבל תחומין דהוא לגבי הילוך, היינו, אוויר, ואין צריך למחיצות אלא שלא נגדיר ההילוך במקומות רבים, ובזה לכ\"ע להבריח מים הוי חסרון."}, {"s": "h7", "h": "סברת רבה בדין מחיצות ספינה - שביתה מבעו\"י צריכה מחיצות קרקע ולא מחיצות אוויר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"684\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">27\u003c/sup>\u003cspan class=\"ca\" data-c=\"684\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אלא דמ\"מ סבר רבה דע\"י ששבת שם אין צריך לגדר מחיצות אוויר, אלא רק מחיצות קרקע, ובזה הרי לכ\"ע להבריח מים לא הוי חסרון (וזה גם ביאור מה דהוי חסרון אפילו בפחות מב\"ס, שאין גדר בפחות מבית סאתיים רק לגבי קרקע, וע\"כ יועיל לגבי הוצאה אפ' לשמואל, אבל בתחומין אין המחיצות לקרקע אלא באווירה), ונחלקו רבה ור' זירא בגדר מה דיש לקרקע ספינה להגדיר הילוך ביותר מארבע אמות, והיינו, דר' זירא סבר בדעת ר\"ע שאין לקנות כלל ארבע אמות דיוצא חוץ לתחום בספינה, דדין זה שיש ארבע אמות הוא גדר תחום עצמו, וכמו דלא מהני הגיע מדתו לחצי מערה, ואף אחר שנכנס אין לו להלך בכולה, כך מי שנמצא בספינה, והרי יוצאת מארבע אמות לארבע אמות, והרי יש בכל פסיעה שלו איסור. אבל ר\"ג סבר בהיפך שדין ארבע אמות שיש לו הוא בספינה עצמה ולא בקרקע עולם.\u003c/span>"}, {"s": "h7", "h": "לשון רש\"י בעקירת רגל בספינה - ד' אמות נקבעות בעמידה בקרקע ספינה ולא בהילוכה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"685\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">28\u003c/sup>\u003cspan class=\"ca\" data-c=\"685\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וביאור דבר זה כך הוא, שהנה כתב רש\"י שע\"י שנוטלתו כשעוקר רגלו יש לו לקנות ד\"א שנמצא בהם עתה, ויש להקשות למה העמיד רש\"י המקרה בעוקר רגלו, דהוה ליה למימר דכיון שהלך צעד אחד, הרי שיש למדוד ארבע ממקום זה, ומשמע דזה ודאי כיון שנמצא במקום ד\"א שהיה, אין לו לקנות אחרות, ואף לר\"ג, אבל כשעוקר רגלו ומוליכתו ספינה חוץ לד\"א, הרי יצא מן התחום, שאין לומר שביתה בד\"א דקרקע ספינה אלא לגבי עמידה, ולא הליכה, והיינו, דאף אם עתה תעמוד הספינה ויצטרך להישאר בד\"א שנמצא בהם, אין גדר הליכתו בהם משום הליכה בתחום, אלא משום דלא חשיבא הליכה, שגדר ד\"א דאית ליה דבקרקע הספינה הוא משום שכבר נמצא בהם, ולא יוסיף הילוך בהם כלום, וזה גדר בקרקע הספינה. וע\"כ סבר שאם נרצה להגדיר ד\"א אלו בכל הספינה, לא יועיל מה שיש מחיצות לקרקע, ומחיצות אוויר הרי להבריח מים עשויות, היינו, דמה שיש במחיצות להגדיר האוויר לאחד, הרי אין עשויות לאוויר, היינו, לחלוקה, וממילא איחוד, אלא להבריח מים. ומה שעשויות לקרקע הספינה, אין קרקע הספינה אלא להינוח ולא להילוך. אבל ר\"ג סבר דלגבי קרקע דספינה אין צריך כלל לשבת, וכמו בדיר וסהר, ומה שיוצא חוץ לארבע אמות דתחום, הרי שיש לו לקנות בכל צעד ד\"א חדשות. ובזה נשתנה דין ספינה מדיר וסהר, דבדיר וסהר סבר ר\"ג דאין נחשב שיוצא משום דחשיבן לו כולה כד\"א. ובזה חלקו ר\"ע ור\"י דס\"ל דאף שיש להחשיב כל הדיר וסהר לענין מקום ישיבתו, עדיין יהיה אסור לצאת משום יציאת תחום, אבל בספינה ר\"י מודה, שהרי קונה בכל פעם וכו', ור\"ע חלק משום דסבר דהאי ד\"א הוי בספינה עצמה, וכיון שכן הוי כדיר וסהר.\u003c/span>"}, {"s": "h7", "h": "דעת רבה בד' אמות דתחום - ד' אמות בקרקע עולם לעומת ר\"ג בספינה עצמה"}, {"s": "p", "h": "אבל רבה סבר דזה כ\"ע מודו דהאי ד\"א דתחום הוי בקרקע עולם, אלא דכיון שנוטלתו בכל שעה אין לו לקנות, וא\"כ ליתא כלל ליציאת תחום, והוי כמו בלמעלה מי\"ט לחד מ\"ד, אבל אי עמדה שעה אחת כבר לא יועיל, שהרי קנה ויצא, ולקנות שוב אין לו שהרי יש לו ד\"א דקרקע ספינה שקנה בשעת עמידה. ור\"ג סבר דאמנם אין זה כדיר וסהר שיש להגדיר ד\"א דתחומו בכל המקום משום ד\"א דקרקע, אבל כיון ששבת מבעוד יום באוויר מחיצות יש לו את כל המקום, ומה דיצא מחוץ לתחום אין בזה חסרון, דכיון ששבת באוויר מחיצות תחומו נמדד מחוץ להם. ור\"ע סבר שאין מועיל מה דשבת אלא ביחס לתחום דאית ליה, ולא מחוץ לתחום, שגדר ד\"א דאית ליה חוץ לתחום הוא משום דלית לן לאחשובי כתחום, היינו, שלא שייך בהם יציאה, וד\"א שנתנו ליוצא הוה משום שביתה. ולפי\"ז לא הודה רבה במהלכת אלא לעניין שלא קונה תחום, אבל אחר שקונה בזמן עמידה, אף לר\"ג לא מהני אלא משום שבת. וע\"כ עדיין יהיה בזה נפק\"מ לגבי נפחתו, וקופץ, ור\"י דמודה בספינה משום דשבת באוויר מחיצות."}, {"s": "h3", "h": "ט. שביתה בספינה נעה, גדר חזי להילוך, ויוצא ברשות"}, {"s": "h7", "h": "תמיהת הראשונים ממים נדים באוקיינוס - חילוק תנועת מים מאדם הקונה שביתה בספינה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"686\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">29\u003c/sup>\u003cspan class=\"ca\" data-c=\"686\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ועוד נראה שיש לחלק ע\"פ מה שהקשו הראשונים דהא אמרינן דמיא באוקיינוס לית להו שביתה משום דניידי, וא\"כ האי ספינה דקביעא אמיא, גם היא חשובה ניידא, ובודאי דאדם שעליה נחשב דניידי, ולמה קונה שביתה אפילו למטה מי', ואפילו במהלכת תוך ד\"א. ונראה לבאר זה בשני אופנים. או דניידי האמור לא שייך אלא במים, משום דמה דניידי במקום מקוה, הוא משום עצמם וטבעם, אלא דזה היה לומר אף באינם נובעים, ויותר נראה לומר דאמנם לגבי ספינה יש לומר דכיון דנדה ואפילו שזה משום מים אין לה לקנות שביתה, אלא דהכא אנן איירינן לגבי אדם, וכיון דהוא אינו נייד, יש לו לקנות שביתה, והיינו, כמו שאמרנו שגדר קביעות הנדרשת לשביתה אין היא במקום שביתה דתחום, אלא במקום שימוש, וזה בספינה, ולא נצרכנו לשעמדה לכ\"ע אלא לענין שיחשב ד\"א דאית ליה בספינה, היינו, סיבת ד\"א, דהוא באמצען, היינו, הוא עצמו, משום תחום, וזה אכן תלוי בספינה, אבל אין זה במקום מנוחת ספינה, דזה אמרנו דיש לומר דחשיבא כניידא אפילו כשעומדת, אלא הוא ביחס לד\"א דתחום. וזה כלישנא קמא דרש\"י, דפירושו דקרקע ספינה אין לו להיות מוגדר לפי תחומין, משום שאינו נח, דבכל קפיצה נע יותר מד\"א. ויהיה נפק\"מ בזה במי ששט בגופו, אי קונה שביתה, ואפילו שט בפחות מקפיצת ד\"א (ויש לדון אם האי ד\"א דאמרינן הוא דווקא לשמואל דסבר דלא מהני משיכה בספינה אלא עד שימשוך את כולה, ולגבי ד\"א דאית ליה בעינן לקפיצה דד\"א, אבל לרב דדי בכל שהוא הרי דחשיב דקרקע של ספינה כולה נדה. ויש לחלק דלא אמר רב התם דמהני, אלא משום דס\"ל דאין דין משיכה ביחס למקום שנחה עליו, אלא ביחס להיותה נחה, ובכל שהוא כבר לא חשיב נחה. אבל הכא בעינן שתנוד ביחס לקרקע מסויימת, והיינו, ד\"א, ולא יועיל אלא בנדה כולה. ונראה דזה צ\"ל אף לשמואל, דהא התם בעי לנדה כולה ממקום שנחה, היינו, שיבוא סופה למקום שהיה ראשה, והכא לא בעינן אלא לד\"א, והיינו, דסבר שמואל דהתם שאין בקרקע מנוחתה הגדרה ביחס אליה, אלא במה שהיא שם, וזה בעינן למיפק, או דבעינן למיסק למקום אחר, אבל הכא גדר ניודה הוא ביחס לד\"א דתחום, וע\"כ יהיה די במהלכת ד\"א. וטעמא משום דלית לן למימר שיקנה שביתה ד\"א בקרקע הים משום מנוחה דאית ליה בקרקע ספינה, דהא אין קרקע דספינה נח ביחס לקרקע הים).\u003c/span>"}, {"s": "h7", "h": "סיום מקום בספינה ברב ושמואל - ספק אי עמידת רגליו נחשבת כסימון מקום שביתה"}, {"s": "p", "h": "אלא דאיכא לאקשויי דהרי נחלקו רב ושמואל אי סיום מקום מעכב, באומר שביתתי במקום פלוני, ואף רב מודה במקצת ביתו ניכר, וא\"כ היה לומר גם בספינה שלא יועיל מה שקופצת ד\"א, אלא לרב יהא בעינן ח', ולשמואל בעינן קפיצה דכל הספינה, ויש לומר שלא אמרו כן אלא בלא מסיים מקום, אבל כאן דמקומו מסויים במקום עומדו לא בעינן. אלא דעדיין יש להסתפק דאמנם כיון שמקום עומדו מסויים ליתא לשמואל, אבל הרי בפחות מח' אין מסויים רק חלק מד\"א, והיינו, שאין אנו אומרים דבעינן שיהיה מקום עומדו ניכר, אלא רק חלק מד\"א של מקום עומדו, ואף כאן בהילוך פחות מח' הרי שבתחילת הילוך הספינה ניכר חלק מד\"א שלו, ובסוף הילוך ניכר חלק מד\"א שלו, היינו, שני חלקים, כל חלק בקצה אחר של מקום שביתתו, אלא שיש לומר דזה לא מהני, כיון שבכל עת לא ניכר אותו חלק, אלא חלק אחר, ובזה לא נחשב ניכר. אלא שעדיין יש לשאול שהרי לא דחה רהבד\"י דברי אביי בפחות בי\"ב, אלא משום שאין לנו להחליט שיהיה מקום שביתתו באמצעיתו, שנאמר שבכל ד\"א דאית בהאי מקום, מקום שביתתו ניכר, אבל משום מה שבכל בירור יעלה חלק אחר של מקום ביתו לא דחה דבריו. ובאמת שהן דבריו דרהבד\"י עצמו, היינו, דבפחות מח', והיינו, שאפשר שיהיה שביתתו בדרום וקנייתו בצפון, או שביתתו בצפון וקנייתו בדרום. וא\"כ גם כאן שבקפיצת ספינה פחות מח' בתחילת קפיצה יהיה קצה אחד דד\"א דקרקע הים מובלע בקצה אחד דד\"א שלו, ובסוף קפיצה יהיה קצה שני דד\"א דקרקע הים מובלע בקצה שני דד\"א שלו."}, {"s": "h7", "h": "שביתה בספינה מול שביתה בתל - ספינה מקום מסויים וכולה נחשבת מקום שביתה לרב"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"687\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"687\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואחר העיון נראה להקשות ביותר שהרי אמרו דבנתכוון לשבות בתל וכו' דאין צריך לסיים כלל, ואפילו לרב, והרי ספינה הוי מקום מסויים (אלא אם נאמר דהוי יותר מבית סאתיים, ולשמואל דלא מהני מחיצות דלהבריח מים עשויות, דבפחות לא גרע מתל), וכיון שנתכוון לשבות בה הוי שביתתו בכולה, ואין צריך לסיים ד\"א, וא\"כ ה\"נ אין צריך רק שיהיה ד\"א דקרקע הים באיזה חלק מאורך הספינה בכל משך קפיצה אחת, ואפילו לרב. ורש\"י נזהר מזה וכתב נמצא שאין לספינה תורת ארבע אמות, שלא עמד פסיעה אחת בתוך ארבע אמות. וצ\"ב.\u003c/span>"}, {"s": "h7", "h": "לשון רש\"י אין תורת ד' בספינה - השוואה לעמוד פחות מד' טפחים שאינו חזי להילוך"}, {"s": "p", "h": "ונראה ביאור דבריו הקדושים כמו שיש לבאר במה דכתב רש\"י במה דלא בעי אי אין תחומין למעלה מעשרה דווקא בעמוד פחות מד\"ט, דלא ניחא תשמישתה, לעומת יש בו ד\"ט דניחא תשמישתיה, דחזי להילוך, והוי הילוך מעליא. וזה הדבר צ\"ב שהרי גדר למעלה מעשרה הוא לכאורה משום דלא חשיב רשותא דקרקע, וא\"כ די שנאמר דפחות מד\"א לא חשיבא רשות לעצמה, שנאמר שהיא קרקע בעצמה, ורשות דקרקע שלמטה אינה תופסת למעלה מעשרה, ולמה בעינן לגדר הילוך. ומה גם שמהיכי תיתי שבד\"ט הוי חזי להילוך, ויותר היה לומר דשיעור מקום הילוך הוא בד\"א, וכבר ביארנו הכרחיו במק\"א, ורק נכתוב גדר הדבר, והיינו, דביחס לתחום עצמו אין שייך שיהיה חסרון במה שהוא למעלה מעשרה, שהרי כיון שנתרחק ממקום שביתתו אלפים הרי שיצא חוץ לתחום, וגם אי נימא שאין תפיסת התחום כולו אלא בתוך עשרה, לא ימצא זה אלא במישור אחיד, וכיון ששבת ברשות זו מה יועיל לרשות ד\"ט הגבוהה ממנה, ובהכרח שגדר מה דאמ' אין תחומין הוא במה שיש להחשיב שהות הנמצא באיזה מקום כנמצא חוץ לתחומו. ובזה נתקשה מה שייך שיתחברו בזה שיחשב ארעא סמיכתא. וביאורו שאין נחשב תחום אלא במה שיש להחשיב מקומו של אדם, ואין גדר מרחק ביחס לאדם, אלא במה שיש לו להתרחק, היינו, הילוך דשיעור דאלפים הוא משום שנחשב לאדם כריחוק מקום, ואין חוץ לתחום אלא במה שעתה הריהו בריחוק ממקום שביתתו. וזה גדר ממקומו, היינו, שכל עוד נמצא בקירוב יש להחשיב עמידתו, ומשמעות עמידתו בהילוך כאילו פונה למקומו. אבל ביציאה חוץ לאלפים הרי שנחשבת עמידתו כפניה למקום אחר, ואין הוא למקומו אלא ממקומו, וע\"כ לא יהיה גדר חוץ לתחום אלא במה שיש להחשיב מקום זה כמקום הראוי להילוך למקום שאינו מקומו, יותר מאשר למקומו. אבל במקום שאין להחשיבו כמקום הילוך הרי שלא נחשב כלל בגדרים אלו, ואין הוא מקום לא לכאן ולא לכאן."}, {"s": "h7", "h": "גדר מקום דחזי להילוך בתחומין - מקום הראוי לעמדת הליכה ולא מקום ההילוך עצמו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"688\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"688\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וזה ביאור גדר דחזי להילוך, דודאי מקום הילוך אינו אלא בד\"א, וכמו שהוכחנו בגדרי רה\"ר, אבל אין גדר דמקום הראוי להיחשב תחום משום הילוך בו, דהא אפילו כלתה מידתו בחצי מערה, אינו מהלך את כולה, אלא גדרו מקום הראוי להיות עמדת הליכה, היינו, שממנו ראוי ללכת (ונראה דזה ביאור מה דמקום לינה חשיב כשבת אף בנותן עירובו במקום אחר, שאין מקום לינתו מקומו), וזה דמי למה שאמרו בחריץ פחות מד\"ט דמפסע פסעי לה (ואף דהתם בד\"ט לא מיפסעי, ויש להקשות מקום דריסת רגל שניה היכן, אין זה קשה, דהתם הוא שיעור לחבר הקרקע, וכאן הוא שיעור קרקע עצמה, ואכמ\"ל), וחשיבות מקום עמידה לגבי פסיעה, היינו, במה שיש בו לאכול מפסיעה שלמה, וזה אינו גדר הילוך כהתקדמות ממקום למקום, אלא בעזיבת מקום לבד, וכמו שביארנו באיסור הימצאות דחוץ לתחום (וכבר נתבאר בזה דעת חכ' ומח' דרגל אחת וכו').\u003c/span>"}, {"s": "h7", "h": "פסיעה קבועה בספינה לרש\"י - חסרון עצם בית בספינה ולא חסרון סיום בית"}, {"s": "p", "h": "ולענייננו בביאור דברי רש\"י בספינה, דאין כוונת רש\"י למקום עמידת רגליו, דזה כמ\"ש הרי חשיב בד\"א או בח' על ח', אלא כוונת רש\"י כמו בגדר תחומין למעלה מעשרה, שאף אם ילך בה ארבע אמות, ויש לחשב ארבע אמות לפי קרקע דספינה, כיון שאין שייך בה פסיעה אחת ביחס לקרקע הים, והיינו, שיהיה מקום פסיעה אחת כולו בתוך ד\"א בקפיצה אחת, הרי שאין להחשיב איזה מקום בספינה כמקום הילוך, ותראה כי גדר זה הוא בהיפך למה שכתב בלישנא בתרא, והיינו, ששם ד\"א דקרקע קבועים הם, ופסיעה דיליה הוא ביחס להם, כפעולה בהם. וע\"כ יהיה הגדר בשלמות דמעשה פסיעה, והיא בעקירת רגל אחת והנחתה, כי אין זה נוגע לגדר הספינה, אלא לגדר מה שנחשב פסיעה חוץ לד\"א דאית ליה, ואין גדר בספינה כלל, דהתם דעתו שאין חסרון בקניית שביתה משום ניידות דספינה, אבל בלישנא קמא הוא בהיפך, דפסיעה קבועה היא, וזה בדריסת שתי רגלים דאיתא בהילוך אחת לפני השניה, וד\"א דקרקע הים נע לעומתו (וזה כמו דעת רב לגבי משיכה). ומעתה יבואר מה דלא אמרינן ביה מקצת ביתו ניכר, והוא שאחר שאין למצוא קביעות פסיעה אחת בקפיצה אחת בתוך ד\"א, אין להחשיב זה כבית כלל, ואין זה חסרון דסיום בית, אלא חסרון דבית עצמו."}, {"s": "h7", "h": "ספינה המהלכת מעצמה בשבת - הנחת רגליו בספינה נעה אינה קביעות לקניית שביתה"}, {"s": "p", "h": "וביתר ביאור, בהבחן מה דיש בספינה שאין בשאר מקרים, והוא שהיא מהלכת מעצמה, וע\"כ אם יש לנו להחשיב הילוכה כהילוך אדם, הרי שבשעה שקדש היום יש לאדם לקנות שביתה, וביציאתה מהתחום יאסר לו ללכת, שלא מצאנו במי שמהלך בזמן בין השמשות, שלא יקנה שביתה. אלא ודאי כיון שקדש היום יש לו לקנות מקום דריסת רגליו, מה שיש לו להניחם בין פסיעה לפסיעה (או אפילו רגל אחת למ\"ד), ויהיה גדר מה שמקום זה נחשב מקומו יותר משאר מקומות שמהלך בהם, שנאמר שאסור לו לצאת ממנו, משום קביעות שהיתה לו בהנחת רגליו, אבל בספינה כיון שאין בהנחת רגליו קביעות, שהוא יושב והיא מהלכת לו, אין לו לקנות שביתה, שאין שביתה אלא במה שיש להגדיר מקום זה קבוע יותר ממקום הילוכו. אלא שיש לנו לקבוע מקום שביתה לגבי ספינה עצמה, שהרי יש לו קביעות ביחס להילוך בה. ואמנם אין גדר שביתה בקרקע המהלכת לגבי תחום דאלפים, כיון שאין בה אלפים, אבל לגבי יציאה מתחום דקרקע הים יש לנו לקבוע, ואין למצוא  בד\"א אלו גדר אלא במה שיש להחשיב יציאה מהם כהילוך האסור, היינו, הילוך ממקומו, וכמו יציאה דחוץ לתחום, אלא שאין איסור בהילוך זה אלא במה שהוא שינוי מעמידה במקום (דאם לא כן היה לאסור את עצם השהות חוץ לתחום), ואין נחשב שינוי לגבי ספינה המהלכת אלא במה שהילוכה מורכב מרוב קפיצות, ואם כן יש להחשיב כל קפיצה כפסיעה, היינו, מה שיש מעקירת רגלו עד הנחתה. ויהיה גדר מעשה דיציאה בהילוך הספינה, ושינוי המקום בהילוך האדם בקרקע ספינה (וזה עוד יותר מאמר לנכרים שידחפוהו שהרי הילוכה מוכרח, והוי כזורה ורוח מסייעתו שאין בזה חסרון דמסייע). אלא שאם יהיה בקפיצת הספינה ד\"א, אין להחשיב שינוי המקום דהילוך אדם ביחס לתחום, אחר שאין במעשה הליכה שלו יותר מאם היה עומד. ודוק דאין זה משום עצם עמידת רגליו, שאין להגדיר מעשה דהילוך ע\"י עמידה, אלא דווקא עמידת פסיעה, שאין במעשה דפסיעה גדר שינוי במקום אלא במה שעתה התרחבה עמידת רגליו."}, {"s": "h7", "h": "מחלוקת רגל אחת או שתים בתחום - עמידת פסיעה כקביעות ביחס להילוך עתידי למקומו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"689\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">32\u003c/sup>\u003cspan class=\"ca\" data-c=\"689\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">(ויש בזה תוספת ביאור למה שכתבנו במח' דרגל אחת או שתים. שאם כנים הדברים שגדר תוצאת מעשה איסור דיציאה דחוץ לתחום הוא במה שעתה הוא מרוחק ממקומו, וכבר אין להחשיב עמידת רגליו כעמדה ובסיס הילוך דחזרה למקומו, והיינו, שיש בהימצאות תוך התחום גדר חיובי שבקרבתו לנקודת שביתתו, הרי שיש להגדיר את עמידת רגליו כעמדת הילוך למקומו, הרי שדי ביציאת רגל אחת למקום שהוא מרוחק, להגדיר שאין הוא עצמו כמהלך מוגדר כמהלך למקומו, שהרי אין גדר מקום דתוך התחום אלא במה שיש בו להגדיר את האדם, ובאין עמידתו כולה בתוך התחום כבר אין במקום עמידתו להגדירו כמהלך למקומו. וזה גדר רגלך ביחיד, שביחס לגדר החיובי שיש בזה הרי שדי ברגל אחת לבטלו, וזה ביאור קרי וכתיב, היינו, מה שיש לרגל אחת להגדיר את האדם ביחס להילוך דשני רגליו. אבל מ\"ד שתים סבר שאין להגדיר האדם לפי עמידת פסיעה, שאין זו עמידה קבועה ביחס להילוך, שהרי היא עמידה דהילוך, ואין להגדיר את האדם ביחס להילוך עתידי, אלא במה שאין הוא חלק מהילוך עצמו, וזה עמידת שתי רגליו ביושר. וע\"כ אף עתה שהוא עומד עמידת פסיעה, יש לברר היכן הוא נחשב עומד, וזה שאמרו שאחר רוב גופו הוא נזקר, והיינו, משום שאם היה צריך לחזור לעמידת רגלים ביושר, הרי היה חוזר למקום רגלו שבפנים, שרוב גופו עומד עליה, והיינו, קרי וכתיב, דרגליו, היינו, עמידה שיש בשתי רגליו ולא בפסיעה, שבזה בתחילת פסיעה עומד רוב גופו ברגל זו ובסופה ברגל זו, ומה דכתיב ברגלו, הוא משום שגדר זה שייך אף ברגלו אחת, וכדאמרן, בזו שרוב גופו עומד עליה, ולכ\"ע גדר יציאה דתחום הוא כמו שאמרנו, אלא שנחלקו אם יש בעמידת פסיעה קביעות, להגדיר את האדם ביחס להילוך עתידי.)\u003c/span>"}, {"s": "h7", "h": "יצא ברשות מול יצא לדבר מצוה - הימצאות חוץ לתחום מול היתר כניסה לתחומו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"690\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"690\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואגב כן יש לנו לבאר בזה עירוב שמות דאיתא בסוגיא דיצא ברשות, דבמשנה קראו ליציאה הנ\"ל יציאה ברשות, והיינו, דמשמע שיש יציאה ברשות ושלא ברשות. ואביי קרא לה לדבר מצוה, דהוא לכאורה היפך דבר הרשות. וכן ביאור מה שיש להקשות דכיון דסבר רבה דבזה אמרינן הבלעת תחומין והכא לא, הרי ממ\"נ או דחזר בו מההיא, ומה יש לאביי להביא ראיה מאחר שחזר בו, או שיש לחלק בין ארבע אמות דהתם לאלפים דהכא, ומה מהני לאביי להביא ראיה מהתם. וביאור עירוב השמות כך הוא, דהמשנה דברה ביחס להימצאותו חוץ לתחום, דבזה אין לומר דבר מצווה, כיון שאין מצווה בשהותו במקום זה אלא במעשה זה, והמשנה איירי במה שנותנים לו תחום, וזה הרי גדר במה שהוא נמצא שם, ולא במה שיצא, אמרו דכיון שיצא ברשות, היינו, כאילו אנו אומרים דמשום דבר מצוה הנצרך לעשות, הרשוהו להגיע למקום זה שהוא חוץ לתחום. אבל אביי לא איירי במה שיש להגדיר היותו במקום, שהרי לא בעי למימר אלא שיש לו להיכנס לתוך תחומו, והרי מה דמובלע תחום ד\"א דאית ליה בתחומו אינו תלוי בסיבת יציאתו, ואמר רבה דלא חלקו חכ' בזה אלא במי שיצא לדבר הרשות, אבל מי שיצא לדבר מצווה יש לו לחזור, וזה בהיפך ממה שאמרו במשנה, דבמשנה בעינן שיחשב זה כמקומו, שיהיה לו אלפים לכל רוח, וזה במה שאנו קובעים שכאן הוא מקומו, יותר ממי שיצא שלא ברשות, שאנו אומרים בו שאמנם הוא כאן, אבל תחומו במקום שיצא ממנו, ואין לו אלפים, אבל ביוצא שתים אנן בעינן שיחשב כמי שלא יצא, וזה במה שאנו אומרים שאין כאן מקומו. ונמצא שלושה מדרגות לגבי קביעותו במקום, דביוצא שתים לדבר מצוה אנו אומרים שאינו קונה המקום, וכיון שכן בהיכנסו לתחום הרי הוא כמי שלא יצא. ויוצא לדבר הרשות אנו אומרים שקונה המקום, ואף שיצא רק בשתים, לא יועיל מה שיכנס שעדיין שם ארבע אמות עליה, אבל אין אנו אומרים שכאן הוא קביעות מקומו למדוד לו אלפים לכל רוח. ויוצא יותר משתים לדבר מצוה, שלא יועיל שלא יקנה מקומו, שאין להלך חוץ לתחום יותר מד\"א, אף מי שאין לו קניית שביתה, הריהו קונה מקומו, ולא זו בלבד אלא שאנו אומרים ששם קביעות מקומו, שיש לו אלפים אמה לכל רוח.\u003c/span>"}, {"s": "h3", "h": "י. הבלעת תחומין ביוצא ברשות ויסוד מצי למשקליה"}, {"s": "h7", "h": "ג' דרגות בקביעות המקום ביוצא - יוצא לדבר מצוה, לדבר הרשות, והמוצא בעל כרחו"}, {"s": "p", "h": "ואחר העיון נראה לומר דקנית שביתה שיש למי שיצא ברשות, אין זה תוספת קביעות על קניה שיש אף למי שיצא שלא ברשות, אלא הרי הם שתי גדרים נפרדים, דגדר ארבע אמות שיש למי שיצא לדבר הרשות, אין זה שהקנו לו ארבע אמות, דכיון שיצא באיסור היה ראוי שלא יהיה ילך כלל, וכמו איסור אכילה דפירות, אלא כיון שארבע אמות שסביבו הריהו כמי שנמצא בהם כבר, אין בהילוכו בהם יותר מעמידה שהוא עומד. אבל מי שלא יצא באיסור (שהוציאוהו כו') הקלו חכ' שיוכל ללכת, אלא שלא נתנו לו מקום הילוך אלא בארבע אמות, וזה בגדר כמו שאמרנו דחשיב מקום שהניחהו שם כמקום שיש ללכת ממנו, ואין בפסיעתו חוץ למקום עמידתו משום איסור (וכל זה רק לר\"ג). וארבע אמות שהגבילוהו הוא משום שביותר מזה אין די שיחשב מקום עמידתו כמקום רשות פסיעה, אלא בעינן שיחשב מקום שביתה, וזה לא נתנו לו. וביוצא לדבר מצוה תקנו לו שיחשב לו מקומו כמקום שביתה, ויש לו אלפים."}, {"s": "h7", "h": "השוואת אביי יצא למצוה לאלפיים - שניהם קנו רשות פסיעה הראויה להבלעת תחומין"}, {"s": "p", "h": "וזה ביאור מה שדימה אביי יוצא שתים לדבר מצוה למי שנתנו לו אלפים, דבמי שיצא שלדבר הרשות כיון שאין לו להלך כלל, ומה שמהלך בארבע הוא משום עמידתו, אין שייך בזה משום עירוב תחומין, שמי שעומד בתחומו יש לו רשות פסיעה, וזה אין לו אלא עמידה, ואין כאן הבלעת תחומין, דאין זה תחום. אבל מי שיצא לדבר מצוה (או בהוציאוהו לר\"ג) הרי אית ליה רשות פסיעה, וכיון דרשות פסיעה, היינו, תחום, מיבלע ברשות פסיעה זו, יש לחברם."}, {"s": "h7", "h": "דברי אביי מאי לאו ר\"א לטעמיה - ר\"א מודי דיש תחום פסיעה בכל היוצא"}, {"s": "p", "h": "וזה ביאור מה שאמר מאי לאו ר\"א לטעמיה דאמר והוא באמצען, שיש לבאר מה בא לשלול, דמה יש ליספק בזה הלא שיעור זה הוא הפחות ביותר שיש לתת לצד אחד. ונבארו בהקדם מה שהיה להסתפק אם ארבע אמות הנ\"ל הוא מקום תפיסת עמידה, או הגבלת מקום פסיעה, שאם היה גדר ארבע שאמר ר\"א משום ד\"א דמקום עמידה, אין להביא ראיה, שאיך שיהיה ביאור הדברים דר\"א, בהכרח אין זה משום הבלעת תחומין (שאפשר לומר דסבר שלא מאבד תחומו אלא בשכל מקום עמידתו חוץ לתחום, ולאו משום איסור שעשה). וזה אמר אביי שיש לומר שר\"א לטעמיה, והיינו, דסבר שאין לו לאבד תחומו כלל, וגדר ארבע אמות דאית ליה הוא כמו מי שישן ולא קנה שביתה, שיש לו מקום פסיעה, אבל לא אלפים דמקום שביתה. וא\"כ הרי שנתנו לו תחום, ומה שהותר ליכנס חזרה הוא משום הבלעת תחומין, ואפילו בלא שבת באוויר מחיצות. וזה אמר דאף חכ' מודים ביוצא לדבר מצוה, והיינו, שלא חלקו חכ' אר\"א רק משום דסברו שלא נתנו למי שיוצא באיסור מקום פסיעה כלל, אבל במקום שנתנו אכן יש לומר הבלעת תחומין."}, {"s": "h7", "h": "סוגיית רבה ורש\"י בהבלעת תחומין - התאמת הדברים עם קניית עירוב והבלעת תחומין להלכה"}, {"s": "p", "h": "וביתר ביאור מהלך הסוגיא דהתם דקשיא הא ודאי לא נעלם מרבה דברי עצמו ומאי קסבר, ועוד קשה מפשיטות הגמ' בנתגלגל חוץ לתחום, דאמר רבא לא שנו וכו' אבל לתוך ארבע הוי עירוב, וביאר רש\"י שהוא משום הבלעת תחומין, היינו, דכיון שיש לנותן עירובו ארבע במקום שהניחו, וארבע אלה מובלעים בתחום ביתו, הוי כנותן עירובו בבית וכו' (וכבר כתבנו להקשות שהרי ודאי אסור לו לילך חוץ לתחומו, וכבר אמרו אין לו אלא חצי מערה, ובכלל מהו שנחשב דבר זה לפי תחום ביתו שאין הוא קונה שם, וקודם דקניא ליתא לדינא דתחומין כלל ומצי למישקליה היכן שירצה, ואי איתא איך יקנה עירוב, כיון שכבר קנה, ובכלל למה שיהיה דיני תחומין גדר במצי למישקליה (דא\"כ מעתה יש לומר שלא יועיל עירוב חצירות, כיון דלא מצי למישקליה לולי עירוב), ועוד דבמשנה כתב דהיכן שלא יקנה בין בביתו ובין בתחומו לא מצי למשקליה, וכאן לא ביאר רק מחמת תחום ביתו, ומשמע שמשום תחום עירובו לא יועיל, דהוא נמצא חוץ לתחום, היינו, שמודדים ממקום העירוב ולא מחוץ לארבע, ולא נתבאר מה שייכות יש בין מה דחשיב כוליה ביתא כד\"א אחר שיקנה עירוב לענייננו, ואי רוצה לומר שאפשר להניח העירוב בחצי בית שחוץ לתחום הול\"ל, ואם אין לדמות זה לבית דהוא מוקף מחיצות, אז אין לדמות כלל), ומשמע דזה אינו במח', ובכלל מה שייך לומר דנחלקו אי הבלעת תחומין מילתא או לא, והא רבה מודה במערה, ואין זה אלא הבלעת תחומין, וודאי מילתא היא גם לדעתו, ומשום חילוק שחילק אין שייך לשון לאו מילתא היא, וצ\"ב."}, {"s": "h7", "h": "ספק ד' אמות מלבד אלפיים - אנשי עיר שנתנו עירובם בעיר מהלכים את כולה"}, {"s": "p", "h": "ולבאר זה יש לנו להקדים עוד שהנה מצאנו שנסתפקו אי יש לנותן עירוב ד\"א מלבד אלפים, והנה מצאנו דדעת חכ' דהנותן את עירובו בעיר וכו' מהלך את כולה וכו', ויש להקשות למה אין זה ראיה דאית ליה ד\"א, והחילוק בזה הוא שאין כוונת הדברים כולה כד\"א, וממילא ד\"א דאית ליה הוי בכולה, אלא הכוונה דכיון שכולה כד\"א הרי שנחשב העירוב מונח בכל המקום, שגדר מה שאמרו כולה כד\"א, היינו, שנחשב כל המקום למקום אחד, ואין בו חילוק מקומות. וע\"כ אף אי נימא דנותן את עירובו אין לו ד\"א לבד אלפים מהלך את כולה וכו'."}, {"s": "h7", "h": "גדר מצי למישקליה בתחומין - הבלעת תחומין תלויה בהיות מקומו ומקום עירובו כאחד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"691\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">34\u003c/sup>\u003cspan class=\"ca\" data-c=\"691\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ומעתה יש לומר דודאי אין במה שהוא חוץ לתחום ביתו משום איסור תחומין, אלא שגדר מצי למשקליה הוא משום שצריך שיהיה הוא ועירובו במקום אחד, ודלהווי סעודה הראויה מבעוד יום, ומה שאמר דלא מצי למישקליה, היינו, לולי שהיה קונה תחומין. שאמנם אין בעצם קניית תחומין שיהיה ע\"י העירוב לבטל העירוב, דלא בעינן אלא שיהיה ראוי מבעוד יום ולא אחר כן, אבל כיון דאיתא לאיסור תחומין, אין נחשב הוא ועירובו במקום אחד, באם יהיה בינו לעירוב מרחק דתחומין. וע\"כ אם יחשב בתוך תחום דאחד מהם די בזה, דלא בעינן שיהיה הוא במקום עירוב או עירובו במקום שלו, אלא די שיהיו במקום אחד מאיזה צד. ואמנם כיון שנתגלגל הרי אין הוא ועירובו במקום אחד, אבל כיון דאתינן לה משום תחומין, הרי שדי שיהיה מקומו ומקום העירוב בתחום אחד. וזה דימה רש\"י לנותן בבית וכו', והיינו, דאף שאמרנו שנחשב כל המקום אחד והוי עירוב בכל המקום, איכא למידק דאיך הוא קונה שביתה בכל המקום, כיון שאין יכול לבוא לקצה הבית מביתו, ואף שאנו אומרים שכל המקום כאחד, הרי לגבי תחומין דביתו לא מהני זה. ומוכח דלגבי מה שיש חסרון בהיות רחוק מרחק תחום, מהני מה שהוא מובלע, וזה בהתעלם ממה דלא מהני הבלעה זו לילך חוץ לתחום שקונה, שאין זה גדר לגבי תחומין, אלא לגבי אדם, שיש למדוד מרחק ממקום מסויים, ולא למדוד תחום, ואחר כן להתיר הילוך בו.\u003c/span>"}, {"s": "h7", "h": "תחום אינו מוגדר קודם הילוך - שלילת הבלעת תחומין בסוף תחום אלא במקום שביתה"}, {"s": "p", "h": "ועכ\"פ יש לשמוע מהנ\"ל שאין תחום דאדם מוגדר קודם הילוך, והיינו, שנאמר שתחומו מסתיים כאן, ומעתה הילוך שהולך, הוא בתוך מקום. דא\"כ היה לומר הבלעת תחומין אף בסוף התחום, ולהיווי ליה כל המערה, וכמו לגבי קניית עירוב, וזה אינו, אלא גדר מה שנחשב חוץ לתחומו הרי הוא משום שבזה יתרחק אלפים ממקומו, ומקומו קבוע, והוא מתרחק או מתקרב מאותו מקום, ונאסר לצאת חוץ לתחום."}, {"s": "h7", "h": "חילוק דין יציאה מדין חזרה - השוואה למערה ותשובת רבא דהתם שבת באוויר מחיצות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"692\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">35\u003c/sup>\u003cspan class=\"ca\" data-c=\"692\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אלא שעדיין יש לומר דזה שפיר איכא למימר לגבי איסור יציאה, אבל אחר שיצא לעניין אי שרי להדורי הרי שאנו מודדים שתי מקומות, וכמו בהבלעה האמורה בנתגלגל, וישתנה הדין לגבי חזרה. אבל במי שיצא ברשות אף דאית ליה תחום, ותחומו מובלע בתחום מוקדם שלו, אבל אין מקומו מובלע, וזה שאל אביי ממערה, וא\"ל רבא דלא דמי משום דהתם שבת באוויר מחיצות, וביאור זה הוא כך, שהנה אמנם אמרנו שאין אלפים אלא מרחק ממקומו, וא\"כ אין שום גדר מקום לאלפים הנ\"ל כולם יחד, וגם אין משמעות הבדל בין אמה ראשונה לאמה אחרונה, דבשניהם אינו נחשב רחוק ממקומו, וע\"כ מותר להלך אליהם. אבל מי ששבת באוויר מחיצות, הרי עוד לפני שמתרחק יש גדר מבדיל בין הליכה בתוך המחיצות לחוצה להם, וזה הגדר אינו תלוי במקומו, היינו, מה שיש לו לתפוס. וע\"כ יהיה גדר דמרחק אלפים גם בלי שילך, והיינו, מה יש להחשיב כמקום שהליכה בו חשובה התרחקות ומה לא, וזה גדר אלפים קבועים, וע\"כ יש לומר בזה הבלעה. אבל מי שיצא ברשות, אף דאית ליה שני תחומין (שאם יוציאוהו נכרים חוץ לתחומו החדש ויכניסוהו לתחום ביתו אף רבא יודה בזה), כיון שאין שני התחומין קבועים אין הם מובלעים. ואמר ליה אביי ראיה שאמרנו מר\"א.\u003c/span>"}, {"s": "h7", "h": "מחלוקת ר\"י ור\"א בשיעור ד' - אי הבלעת תחומין תלויה בקביעת מקום ד' אמות"}, {"s": "p", "h": "ומעתה יבואר ביתר ביאור מה שנחלקו ר\"י ור\"א, והיינו, דסבר ר\"י דד\"א דר\"א לא נקבעו טרם שברר, אבל אחר שברר כבר נקנו לו, וכמו מי שיצא חוץ לתחום שתופס ארבע אמות. והנה אם היה ד\"א שדיבר בהם ר\"א כד\"א דמי שיוצא חוץ לתחום, אכן לא היה ראיה, וכדאמרן דבזה לא חלק רבה, דאין זה הבלעת תחומין אלא ד\"א שיש לו מובלע בתחומו, ובתחומו הרי שבת באוויר מחיצות. אבל אי נימא דד\"א, היינו, ד\"א שאמר ר\"א שהוא באמצען, הרי שאין כאן מקום ד\"א, שנאמר שמובלע בתחומו, וא\"כ בהכרח שע\"י שנכנס לתחומו והוא נמצא שלא מחמת מקום אחר, יש לו להיכנס כבר, והרי זה כיצא ברשות. וזה אמרו א\"כ הרי שאין זה אלא דעת ר\"א, אבל חכ' יחלקו דלא סבירא להם הבלעת תחומין, ואמר אביי דלא חלקו אלא לדבר הרשות דכיון שיצא באיסור וכו', אבל ביוצא לדבר מצווה לא יחלקו."}, {"s": "h7", "h": "דעת רבה ביוצא לדבר מצוה - אביי סבר הבלעת תחומין מילתא ורבה משום מקום"}, {"s": "p", "h": "והנה נראה לתרץ לדעת רבה דמה שאמר דלא פליגי לדבר מצווה, אין זה משום הבלעת תחומין, אלא דכיון שנתנו לו חכמים מקום הוה מובלע בתחומו. ויהיה בזה נפק\"מ אם יתירו חכ' אפילו ביצא שלוש וכר\"י, דאי נימא כרבה, יתירו אפילו בזה, אבל מהא דאביי לא אסיק להאי תירוצא משמע דס\"ל דאם יש לו מקום הרי זה כמי שיצא לתחום, וכמי שברר, שאין לומר בזה הבלעת תחומין, וכמי שיצא לדבר הרשות שיש בזה ביטול דשבו איש תחתיו. אומנם אין זה נפק\"מ לגבי יצא ברשות, דהא אית ליה אלפים, וסבר אביי דהבלעה מילתא."}, {"s": "h7", "h": "מקום הנחת עירוב מובלע בתחומו ברש\"י - עירוב מועיל למצי למישקליה בלא קניית תחום"}, {"s": "p", "h": "והנה בזה גם יש לבאר יותר מה שאמרנו בדעת רש\"י בנתגלגל, דכיון שקנה שביתה שם ויש בזה גדר מרחק בין מקומות. והיינו דאיכא למידק מהו דפשיטא ליה לרש\"י שיהיה מקום שביתתו מובלע בתחום ביתו, ולא ביתו בתחום מקום שביתתו, אחר שיש לו שם ד\"א, ונראה לומר דמה שיש להחשיב מקום שהונח שם עירוב כמקום שביתה אין זה שביתה דאית ליה אלפים הימנה, ובאמת אין מודדין אלפים אלא אחר שיקנה עירוב, ולא מהני מקום שביתה זה אלא לענין מצי למישקליה, שיש לומר שמקום שנתכוון לקנות שם שביתה, היינו, מקום הנחת עירוב, מובלע בתחום. ודי בזה."}], "comments": [{"id": "1585", "n": 1, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-556 | סוג: הקדמה וזיהוי | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בהקדמה ובזיהוי נקודת המוצא:\u003c/p>\u003cp>זיהוי הסוגיה ונקודת המוצא:\u003c/p>\u003cp>הסוגיה המרכזית: עירובין מא: - מב: (מי שהוציאוהו נכרים או רוח רעה אין לו אלא ד' אמות; נתנוהו בדיר וסהר ובספינה לר\"ג וראב\"ע מהלך את כולה ולר\"י ור\"ע אין לו אלא ד' אמות), מב. (רגל אחת בתחום), מג. (תחומין למעלה מי').\u003c/p>\u003cp>הקושי שהניע את המחבר: מדוע שביתה באוויר מחיצות מועילה רק כששבת מבעוד יום ולא במי שיצא וחזר, ומפני מה נחלקו ר\"ג ור\"ע בספינה המהלכת ובספינה נוטלתו.\u003c/p>\u003cp>מוצע לשלב את ההקדמה בפתח הסוגיה, לפני הפסקה הראשונה.\u003c/p>", "t": "intro", "sv": 2}, {"id": "1586", "n": 2, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-618 | סוג: פסקת פתיחה | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בפסקת פתיחה הכוללת מראי מקומות:\u003c/p>\u003cp>איתא במשנה ובגמ' פרק מי שהוציאוהו (עירובין מא: - מג.) דהוציאוהו נכרים אין לו אלא ד' אמות, ונחלקו ר\"ג וראב\"ע עם ר\"י ור\"ע בנתנוהו בדיר וסהר ובספינה המהלכת אם מהלך את כולה או אין לו אלא ד' אמות, ובגמ' תלו זאת בשביתה באוויר מחיצות ובספינה נוטלתו. וכן נחלקו (שם מב., נב:) בדין רגל אחת חוץ לתחום ובשיעור ד\\\"א דהיוצא לשיטות ר\\\"א, ר\\\"י וחכמים.\u003c/p>\u003cp>מוצע לשלב פסקה זו כפסקה הפותחת של הסוגיה.\u003c/p>", "t": "opening", "sv": 2}, {"id": "660", "n": 3, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-037 | חומרה: גבוהה | קטגוריה: היקף הראיה מ׳ארעא סמיכתא׳ — עמוד הראוי להילוך לעומת קרקע כללית. יש לדייק בהיקף הראיה מעירובין מג ע״א. הגמרא מוציאה מן הספק עמוד גבוה עשרה ורחב ארבעה משום „דארעא סמיכתא היא”; ורש״י מפרש: „הואיל וראוי להילוך והילוך מעליא הוא”. מכאן מוכח שלעמוד שיש בו רוחב הראוי להילוך יש דין תחומין, אף שהוא גבוה עשרה. אולם אין מכאן ראיה מפורשת שכל חלקי הקרקע, גם כשאינם מצטרפים למשטח הילוך אחד, נחשבים „קרקע כללית” אחת, או ששיעור עשרה אינו אלא גדר המפריד בין קרקעות. יש להפריד בין שלושה מקרים: עמוד רחב ארבעה הראוי להילוך; עמוד צר שאינו ראוי להילוך, שהוא עיקר הספק; והילוך בקפיצה/בספינה, שהגמרא מביאה כלשון נוספת. לכן אפשר להציע את החלוקה המושגית שבפסקה, אך יש לסמנה כחידוש המבאר את הסוגיה ולא כהגדרה מפורשת העולה מלשון „ארעא סמיכתא”.\u003c/p>", "t": "concept", "sv": 2}, {"id": "661", "n": 4, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-038 | חומרה: קריטית | קטגוריה: הבחנה בין הליכה לטלטול ובין עיר שכלתה בה המידה לעיר שבתוך התחום. יש להבחין כאן בין כמה דינים שאינם ראיה אחת. בעירובין מב ע״ב נאמר במפורש במי שמודד וכלתה מידתו בחצי העיר: „מותר לטלטל בכל העיר כולה ובלבד שלא יעבור את התחום ברגליו” — כלומר, ההיתר בכל העיר הוא לעניין טלטול, ואילו ההילוך ברגליו נשאר מוגבל לתחום. רש״י שם מדגיש שהעיר לא נעשתה לו כארבע אמות, משום שלא שבת בתוכה. לעומת זאת, בעיר שכל כולה נבלעת בתחום, או במי שהניח עירובו בעיר וקנה שם שביתה, יש דינים אחרים של העיר כארבע אמות, כמבואר בעירובין סא ע״א וברש״י שם. לכן אין להוכיח מן העיר „חשיבות חיובית” המאחדת את כל שטחה ביחס להתקדמותו בלי לברר תחילה אם מדובר בהיתר טלטול, בהילוך, בעיר שכלתה מידתו באמצעה, או בעיר שכל כולה בתוך תחומו. ההבחנה המושגית שאתה מציע עשויה להסביר את התוצאה, אבל יש להעמידה לאחר הפרדת המקרים ולא במקום ההבחנה התלמודית המפורשת.\u003c/p>", "t": "concept", "sv": 2}, {"id": "662", "n": 5, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-039 | חומרה: גבוהה | קטגוריה: דיוק במהלך רבה ורבי זירא — הסכמה לדין לעומת הסכמה לטעם. יש לדייק בניסוח היחס בין רבה לרבי זירא. בעירובין מב ע״ב מובאים שני טעמים להיתר בספינה: רבה — „הואיל ושבת באויר מחיצות מבעוד יום”; רבי זירא — „הואיל וספינה נוטלתו מתחילת ארבע ומנחתו בסוף ארבע”. הגמרא ממשיכה ומעמידה את מחלוקתם בשאלה אם הספינה מהלכת או עומדת, ורש״י מפרש את חילוקי הלשונות בהתאם. יש להבחין בין הקביעה שבספינה מהלכת הכול מודים להיתר, לבין השאלה אם כולם מודים גם למנגנון ההסברי של „נוטלתו”. מן הלשון „במהלכת כולי עלמא לא פליגי” אין להסיק לבדה שכל התנאים מקבלים את טעמו של רבי זירא; היא קובעת את גבול המחלוקת להלכה. כמו כן, „שבת באויר מחיצות” הוא טעם אמוראי להיתר, ואין לייחסו בפשטות לעמדת רבן גמליאל עצמו בלי להפריד בין שיטת התנאים לבין הסבר רבה לפסק ההלכה.\u003c/p>", "t": "source", "sv": 3}, {"id": "663", "n": 6, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0017 | חומרה: בינונית | קטגוריה: בהירות ומבנה. פסקה אחת מכילה כ־1,384 מילים לפי חלוקת הפסקאות בקובץ. מומלץ לבדוק אם היא כוללת כמה מהלכים עצמאיים שניתן להפריד לפסקאות, תוך שמירת סדר ההנמקה והקשר בין הטענות. אין לפצל באופן מכני.\u003c/p>", "t": "structure", "sv": 1}, {"id": "664", "n": 7, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-040 | חומרה: קריטית | קטגוריה: היקף מסקנת תחומין למעלה מעשרה — עמוד רחב ארבעה לעומת עמוד צר. המשפט „דאף למ״ד יש תחומין אין איסור לעלות למעלה” טעון צמצום. בעירובין מג ע״א הגמרא אומרת שעמוד גבוה עשרה ורחב ארבעה אינו בכלל הספק, משום שהוא „ארעא סמיכתא”; ורש״י מפרש שאסור לעלות על ראשו שבתוך התחום ולצאת לראשו האחר, מפני שהוא ראוי להילוך והילוך מעליא הוא. הספק הוא בעמוד גבוה עשרה שאינו רחב ארבעה, וכן הובאה לשון נוספת של קפיצה/ספינה. נמצא שאין לומר באופן כללי שאין איסור לעלות למעלה מעשרה: בעמוד רחב ארבעה יש תחומין אף למעלה מעשרה; רק במצבים שאינם נחשבים משטח הילוך רגיל נותר הספק. נוסף על כך, עצם שאלת הגמרא לא נפשטה בסוגיה, ולכן יש להציג את המודל שלך כהסבר אפשרי לצדדי הספק, ולא כמסקנה מוכרעת של הסוגיה.\u003c/p>", "t": "source", "sv": 3}, {"id": "665", "n": 8, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-041 | חומרה: גבוהה | קטגוריה: פירוש ׳למקום שרובו שם הוא נזקר׳ — רוב הגוף ולא בהכרח אופן הזקיפה. יש לדייק בפירוש „למקום שרובו הוא נזקר”. רש״י בעירובין נב ע״ב מפרש בפשטות: „ורובו בתוך התחום הוא”, כלומר, הולכים אחר המקום שבו נמצא רוב גופו של האדם. אין בדבריו הכרח שהמילה „נזקר” מגדירה פעולה של הזדקפות או צורת העמדת הגוף, כפי שניתן להבין מן הניסוח „אם תעמידהו ביושר רגלים וזקירת גוף”. אם כוונתך להציע שהמחלוקת אינה רק אחר רוב הגוף אלא גם בשאלה אם מיקום האדם נקבע לפי מעשה ההילוך או לפי מצב גופו, יש להציג זאת כחידוש פרשני נוסף, ולהפריד בינו לבין פירוש רש״י המפורש. כמו כן, בסוגיה מובאות שתי לשונות בדברי רבי חנינא — „רגלך כתיב” לעומת „רגליך קרינן” — ויש לבאר איזו מהן עומדת ביסוד כל שלב במהלך.\u003c/p>", "t": "concept", "sv": 2}, {"id": "666", "n": 9, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-042 | חומרה: קריטית | קטגוריה: שיטת רבי אליעזר — הבלעת תחומין מול חידוש תחום בארבע אמות. כאן נדרשת התמודדות מפורשת עם פירוש רש״י, שאינו מתיישב לכאורה עם ההעמדה המחודשת שבפסקה. רש״י בעירובין נב ע״ב על „שתים יכנס” כותב: „משום הבלעת תחומין כדאמרינן בפירקין ... ר׳ אליעזר לטעמיה דאמר והוא באמצען”. ובהמשך הסוגיה „הא דעקר חדא וקם אתרתי, הא דעקר תרתי וקם אתלת” מתפרש אצלו לפי מיקום האדם בתוך ארבע האמות האמצעיות. לפי זה, ההיתר של רבי אליעזר מוסבר במפורש בהבלעת תחומין, ולא בקניית תחום חדש מפני שאיבד את תחומו הראשון. אפשר כמובן להציע ביאור פנימי מחודש לגדר הבלעת התחומין, אך אין להעמיד את „תחום חדש” כתחליף לפירוש רש״י בלי ליישב את לשונו ואת הקישור שהוא עושה בין „שתים יכנס” לבין „והוא באמצען”. יש להבהיר גם אם החידוש הוא בהגדרת ארבע האמות או בהגדרת היחס בין תחום השביתה לתחום שנמצא בו עתה.\u003c/p>", "t": "source", "sv": 2}, {"id": "667", "n": 10, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-043 | חומרה: גבוהה | קטגוריה: היקש מאלפיים אמה לארבע אמות — אין להעביר צורת תחום בלי מקור. ההיקש מן הסוגיה בעירובין נא ע״א על „אלפים אמה עגולות” לגדר ארבע האמות של הישן בדרך טעון ביסוס נוסף. הסוגיה שם דנה בצורת תחום האלפיים ובדין הפאות/האלכסון של תחום שבת, ואילו כאן הנידון הוא גדר ארבע האמות הניתנות למי שישן בדרך, ובפרט מה משמעות הברירה לרבי יהודה ומה פירוש „והוא באמצען” לרבי אליעזר. אין די בכך שבשני המקומות מדובר בשיעור מרחק כדי להוכיח שאותו מודל גאומטרי חל בשניהם. יש להראות מהו הצד המשותף המהותי בין תחום האלפיים לבין ארבע האמות, ומדוע מחלוקת „עגולות או מרובעות” מלמדת שארבע האמות קודם הברירה הן מעגל סביב נקודת האמצע. עד שתובא ראיה זו, נכון להציג את המעגל כמודל המחשה אפשרי ולא כמסקנה מוכחת מן הסוגיה.\u003c/p>", "t": "source", "sv": 2}, {"id": "668", "n": 11, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-044 | חומרה: קריטית | קטגוריה: פירוש שתי הברייתות בדעת רבי אליעזר — אין לייחס להן שני גדרי מדידה בלי ראיה. יש לדייק במהלך הגמרא בעירובין נב ע״ב. על הסתירה בין „רבי אליעזר אומר שתים יכנס שלש לא יכנס” לבין „רבי אליעזר אומר אחת יכנס שתים לא יכנס”, הגמרא מתרצת תחילה: „הא דעקר חדא וקם אתרתי, הא דעקר תרתי וקם אתלת” — כלומר, ההבדל הוא בכמות שכבר עקר ובמקום שבו הוא עומד ביחס לארבע האמות, ולא נאמר כאן שהמשנה מודדת ביחס לתחום ואילו הברייתא מודדת ביחס לארבע אמות. רק לאחר מכן מובאת ברייתא שלישית, „רבי אליעזר אומר אפילו אמה אחת לא יכנס”, ומעמידים אותה „למודד”, כלומר במי שמודד את אלפיים האמה ולא במי שכבר יצא וקנה ארבע אמות. לכן החלוקה שבפסקה בין „לישנא דמשנה בתחום” לבין „לישנא דברייתא בד׳ אמות” אינה עולה מפורשות מן הסוגיה, ולכאורה מערבת את שני התירוצים הנפרדים. יש להציג את החלוקה כחידוש שלך, להסביר מדוע אין די בפירוש הגמרא „עקר חדא/עקר תרתי”, ולבאר כיצד היא מתיישבת עם פירוש רש״י ועם פירוש המאירי שהעמידו את דין רבי אליעזר בהבלעת תחומין ובארבע אמות שהוא באמצען.\u003c/p>", "t": "source", "sv": 3}, {"id": "669", "n": 12, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-045 | חומרה: גבוהה | קטגוריה: היקף מחלוקת רבה ורב שימי — בין פירוש המשנה לבין כלל הבלעת תחומין. הכיוון שבפסקה נתמך במפורש ברש״י, אך יש לדייק בהיקפו. בעירובין מה ע״א הגמרא אומרת „עד כאן לא פליגי רבנן עליה דר״א אלא לדבר הרשות אבל לדבר מצוה מודו ליה”, ורש״י מפרש: „ומתני׳ דמי שיצא ברשות דבר מצוה הוא וקאמר רבה לעיל דהבלעה לא מהניא”. נמצא שרש״י אכן מקשר את שיטת רבה לכך שהבלעת התחומין אינה מועילה גם במקרה של יציאה ברשות לדבר מצוה. עם זאת, בסוגיית מד ע״ב רבה ורב שימי נחלקו תחילה בפירוש „אם היה בתוך התחום כאילו לא יצא”: רבה מפרש „כאילו לא יצא מביתו”, ורב שימי מפרש שהתחומים החדשים מובלעים בתחום הראשון. אין להפוך את מחלוקת פירושי המשנה לכלל גורף על כל צורות הבלעת התחומין בלי להגדיר מהו בדיוק התחום החדש שניתן ליוצא ברשות, ומהו היחס בין „לא איבד את שביתת ביתו” לבין „הבלעה מילתא היא”. כדאי להבהיר שהמסקנה היא קריאת רש״י במהלך הסוגיה, ולא לשון מפורשת של רבה כעיקרון מופשט.\u003c/p>", "t": "source", "sv": 2}, {"id": "670", "n": 13, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-046 | חומרה: קריטית | קטגוריה: מערה והבלעת תחומין — אין לזהות הבלעה עם הפיכת כל אלפיים האמה לארבע אמות. יש להפריד בין שני מנגנונים שהפסקה מחברת. בעירובין מד ע״ב אביי מקשה על רבה מן המערה שתוכה ארבעת אלפים אמה ועל גגה פחות מארבעת אלפים; רש״י מסביר שהמערה בעלת שני פתחים, ומכל פתח יש תחום אלפיים, וכיוון ששני התחומים שעל הגג נבלעים זה בזה אפשר להלך את הגג ואת התחום שמחוצה לו. תשובת רבה אינה אומרת שכל אלפיים האמה נעשו „כארבע אמות”, אלא מבחינה בין מי ששבת באוויר מחיצות מבעוד יום לבין מי שלא שבת בהן. זהו תנאי המאפשר לדון את המרחב המוקף כמקום שביתתו, ולא בהכרח שינוי בשיעור או במעמד של אלפיים האמה עצמן. לכן המשפט „חשיבי כל אלפים כמקומו” וההמשך „אלפים הוי כארבע אמות” טעונים פירוק: האם כוונתך להבלעת שני תחומים שנולדו משביתה אחת, או לדין מחיצות ההופכות את כל המרחב לארבע אמות? אלה אינם בהכרח אותו דין. יש להראות כיצד ההבחנה שלך מתיישבת עם תשובת רבה ועם ציור המערה של רש״י, בלי להחליף את דין ההבלעה בדין כל המקום כארבע אמות.\u003c/p>", "t": "concept", "sv": 3}, {"id": "671", "n": 14, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-047 | חומרה: גבוהה | קטגוריה: הבחנה לשונית בין „נכרים” ל„עובדי כוכבים” — אין להעמיס עליה חלוקה הלכתית ללא מקור. החלוקה בין „נכרים” שבמשנה לבין „עובדי כוכבים” שבברייתא, כאילו הראשון מציין מי שפועל לצרכיו ואינו מתכוון להעביר את האדם על דעתו והשני מציין מי שמתכוון להעבירו על דתו, אינה מוכחת מן הלשון לבדה. בסוגיות חז״ל הכינויים „נכרים”, „עובדי כוכבים” ו„גויים” עשויים לשמש לסירוגין, והברייתא בעירובין מא ע״ב אינה אומרת שהעובדים־כוכבים פעלו במכוון כדי להוציא את האדם מדעתו; היא מונה אותם בין הדברים המעבירים את האדם על דעתו. מנגד, פירוש המשנה „הוציאוהו נכרים” מתאר את עצם ההוצאה שלא מרצונו, ולא מגדיר את מניעי המוציאים. אם יש בידך מקור לשוני או הלכתי המעמיד כאן שני טיפוסים שונים של מוציאים, יש להביאו. עד אז ראוי לסמן את ההבחנה כהשערה, ולא לבסס עליה את חילוק המקרים בין אונס לבין העברה על הדת.\u003c/p>", "t": "source", "sv": 3}, {"id": "672", "n": 15, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-048 | חומרה: גבוהה | קטגוריה: היקש מ„פוסק עמו על מנת לשבות” — הסכמה לתוצאה אינה זהה למעשה יציאה. הראיה משבת יט ע״א, „ופוסק עמו על מנת לשבות ואינו שובת”, טעונה הגדרה מדויקת. שם מדובר בהסכם מוקדם עם בעל הספינה לגבי שביתת הספינה בשבת, ובמחלוקת אם התנאי מחייב כאשר הספינה אינה שובתת; אין שם דיון ישיר בשאלה אם נוסע שביקש מגויים לדחוף את גופו החוצה לתחום נחשב כמי שעשה את מעשה היציאה. אפשר ללמוד משם עיקרון של ייחוס תוצאה למי שהסכים לה מראש, אך אין זה מוכיח כשלעצמו שהסכמה למעשה של אחרים הופכת את האדם ל„יוצא לדעת” בדיני תחומין. יש להראות את נקודת הדמיון המשפטית: האם מדובר בשליחות, בגרימת התוצאה, בהסכמה מוקדמת, או בקביעת דעתו של האדם על מקום שביתתו. כמו כן, יש להבחין בין „אמר לנכרים לדחפו” לבין „הניח לנכרים להוציאו” — אלו שני מצבים עובדתיים שונים.\u003c/p>", "t": "source", "sv": 3}, {"id": "673", "n": 16, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-049 | חומרה: קריטית | קטגוריה: „אלפיים פסיעות בינוניות” — שיעור אומדן ולא ראיה להגדרת שוגג. בעירובין מב ע״א נאמר: „היה מהלך ואינו יודע תחום שבת מהלך אלפים פסיעות בינוניות וזו היא תחום שבת”; רש״י מפרש „פסיעה בינונית — דרך הילוכו של אדם אמה”. המקור קובע אמת־מידה מעשית לאומדן אלפיים אמה באמצעות פסיעות בינוניות. הוא אינו אומר שהאדם נחשב שוגג מפני שרוב בני אדם פוסעים באורך זה, ואינו תולה את הדין ב„רובא דעלמא”. לכן אין להסיק מכאן לבדו שאילו גדר השוגג היה חוסר ידיעה של המציאות, לא היה מועיל רוב. יש להבחין בין שלוש שאלות: כיצד אדם מעריך את מרחק תחומו כשאינו יודע את הגבול; מה נחשב שוגג או מזיד לעניין איסור תחומין; ומהו שיעור הפסיעה הממוצעת. כדי לבסס את המסקנה שבפסקה יש להביא מקור נוסף שמחבר בין אומדן הפסיעות לבין מעמדו של האדם כשוגג, ולא להעמיס את ההגדרה על לשון שמואל.\u003c/p>", "t": "concept", "sv": 3}, {"id": "674", "n": 17, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-050 | חומרה: קריטית | קטגוריה: תחומין למעלה מעשרה — ספק שלא נפשט, ורש״י אינו קובע כלל של העדר הילוך. יש לדייק בהבאת סוגיית עירובין מג ע״א כראיה לגדר האיסור. הגמרא שואלת „יש תחומין למעלה מעשרה או אין תחומין למעלה מעשרה” ולא פושטת את הספק. רש״י שם דווקא מדגיש שעמוד גבוה עשרה ורחב ארבעה „חזי להילוך והילוך מעליא הוא”; בעמוד שאינו רחב ארבעה הוא מציין שאין נוח להשתמש בו, ובקפיצה נשאל אם זו נחשבת הליכה. לכן אין לייחס לרש״י קביעה כללית ש„לא חשיב הילוך” בכל מקום שמעל עשרה, וממילא אין להוכיח מכאן לבדה שאיסור תחומין תלוי במעשה ההילוך ולא במציאות הימצאותו של האדם מחוץ לתחום. נוסף על כך, גם אם יש צד לומר שהילוך מסוים אינו נחשב הילוך, עדיין צריך לברר אם זהו טעם הפטור מתחומין או רק הגדרת המקרה המסוים שבספק. נא לציין את מראה המקום המדויק ברש״י שעליו נשענת הלשון „לא חשיב הילוך”, ולנסח את המסקנה בהתאם לכך שהשאלה התלמודית נשארת בספק.\u003c/p>", "t": "source", "sv": 3}, {"id": "675", "n": 18, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-051 | חומרה: קריטית | קטגוריה: סתירה פנימית לכאורה בין איסור של מצב לבין איסור של מעשה הילוך. יש כאן מתח מושגי שצריך ליישב עם P03764–P03768. שם הוגדר איסור תחומין בעיקר כמציאות גופו של האדם מחוץ לתחום, והמעשה נידון כאמצעי שבו הוא מביא את עצמו למצב האסור; כאן נאמר „מעשה האיסור הוא בהליכתו”, ובהמשך שהאיסור הוא „במה שאינו שובת” ובתוצאת היותו מחוץ לתחום. ייתכן ששני התיאורים נכונים בשתי רמות — מעשה המחולל את האיסור לעומת החפצא או המצב שעליו חל האיסור — אבל יש להגדיר זאת במפורש. בפרט, הפסוק „אל יצא איש ממקומו” אינו מכריע לבדו אם גדר האיסור הוא פעולת היציאה, עצם ההימצאות מחוץ למקום, או צירוף של מעשה ותוצאה. מוצע להבחין לאורך הפרק בין: (א) תנאי החיוב והייחוס לאדם; (ב) המעשה האסור; (ג) המצב שבו הגוף נמצא; (ד) התנאי המאפשר או מונע חזרה. בלי חלוקה זו, הקורא עלול להבין שהפסקאות קובעות שתי הגדרות סותרות.\u003c/p>", "t": "concept", "sv": 3}, {"id": "676", "n": 19, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-052 | חומרה: קריטית | קטגוריה: היתר זריקה מעבר לאלפיים — אין להסיק ממנו שכל המתחם נעשה ארבע אמות או שכלי החפץ קונה שביתה. יש להפריד בין לשון הגמרא ופירוש רש״י לבין המסקנה בדבר קניית שביתה של החפצים. בעירובין מב ע״א נאמר „שבת בבקעה והקיפוה נכרים מחיצה בשבת ... ומטלטל בכולה על ידי זריקה”; רש״י מפרש במפורש: „אפילו חוץ לאלפים שאין לו רשות להלך מותר לטלטל על ידי זריקה”. מכאן אכן עולה הבחנה בין איסור הילוך של האדם לבין היתר הטלטול/הזריקה, אך אין בלשון זו לבדה קביעה שהחפצים הם דווקא כליו של האדם או שקנו שביתה כמותו, ואף לא שכל המתחם נעשה „כארבע אמות” לעניין תחומין. רש״י עצמו מסביר שהמחיצות שנעשו בשבת אינן מועילות לאדם שיש לו אלפיים אמה להיחשב לו כארבע אמות, ובכל זאת מתיר זריקה מחוץ לאלפיים. יש לבסס בנפרד את הטענה על זהות החפצים ועל תחומם, ולברר אם ההיתר נובע מדין טלטול ברשות מוקפת, מדין תחום החפצים, או מגדר מיוחד של זריקה. כמו כן, אין להסיק מהיתר הזריקה שכל מקום החפץ נעשה מקום שביתתו של האדם; זה בדיוק ההבדל שהסוגיה מחייבת לברר.\u003c/p>", "t": "concept", "sv": 3}, {"id": "677", "n": 20, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-053 | חומרה: קריטית | קטגוריה: גזירת רב הונא — טעם מפורש של שמא יימשך אחר חפצו לעומת המודל המושגי המוצע. יש להפריד בין טעם הגזירה המפורש בסוגיה לבין הביאור המושגי שאתה מציע. בעירובין מב ע״ב נשאל מדוע רב הונא אינו מתיר טלטול בכולה על ידי זריקה, והתשובה היא „גזרינן שמא ימשך אחר חפצו”; רש״י מפרש שהחשש הוא שיימשך אחר החפץ וייצא מתחומו. כלומר, לשון הסוגיה מצביעה בראש ובראשונה על חשש מעשי של היגררות האדם אחר החפץ, ולא על חשש שיסיק מן ההיתר שהילוך האדם עצמו הותר. אפשר להציע שהמודל שלך מסביר את שורש החשש או את ההיגיון שמאחוריו, אך יש לסמן זאת כחידוש ולבאר כיצד הוא מתיישב עם פירוש רש״י ועם מהלך הגמרא, שמבחין בין שני מקומות לבין טלטול והילוך באותו מקום. כמו כן, אין לזהות בלי ביאור בין „הנחת חפצים במקום המוקף” לבין היתר טלטול החפצים בכל ההיקף: הסוגיה עוסקת במפורש בטלטול על ידי זריקה מחוץ לאלפיים, ובמחלוקת רב נחמן ורב הונא.\u003c/p>", "t": "concept", "sv": 2}, {"id": "678", "n": 21, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-054 | חומרה: קריטית | קטגוריה: ירושלמי — ייחוס שתי אמירות ר׳ זעירא לשני מקרים שונים טעון הוכחה. החילוק שאתה מציע בין אמירת ר׳ זעירא „ארבע אמות שאמרו אינן תחום” בדיר וסהר לבין אמירתו הקודמת „ארבע אמות שאמרו תחום הן” בבקעה אינו מפורש בירושלמי, ויש להציגו כיישוב מחודש. בירושלמי עירובין פ״ד ה״א (כז ע״א) נשאל במפורש על ארבע האמות של מי שהוציאוהו חוץ לתחום אם הן תחום או אינן תחום, ור׳ זעירא מוכיח שהן תחום מן המשנה „ובלבד שלא יוציא זה מתוך שלו לתוך של חבירו”. בהמשך אותה סוגיה מובאת מחלוקת רב הונא וחייא בריה דרב על מי שקנה שביתה והקיפוהו מחיצה, ולאחר מכן הדיון בספינה; בסופו, בדף כח ע״א, ר׳ זעירא אומר שוב „ארבע אמות שאמרו אינן תחום”, מכוח הדיון בספינה ובתחומין למעלה מעשרה. המקור אינו אומר שהאמירה הראשונה נאמרה דווקא בבקעה, או שהאחרונה דווקא בדיר וסהר. כדי לקיים את החילוק יש להסביר מהו מושא הדיון בכל אחת מן האמירות, מדוע אותו לשון מתייחס לשני גדרים שונים, ומה מונע לראות בדברי ר׳ זעירא סתירה ממשית.\u003c/p>", "t": "source", "sv": 3}, {"id": "679", "n": 22, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-055 | חומרה: גבוהה | קטגוריה: ארבע אמות כתחום — משמעות שתי האמות לכל צד והיחס למקום העמידה. כאן נדרש לדייק מה פירוש „ד׳ אמות אלו חשובים כאלפים” ומהו בדיוק הגבול הנוצר. בירושלמי השאלה „ארבע אמות שאמרו תחום הן או אינן תחום” נבחנת לפי האפשרות לתת לאדם ארבע אמות משני מקומות, ולפי דין חפציו; ר׳ זעירא מוכיח שהן תחום מן האיסור להוציא מתוך שלו לתוך של חברו. מכאן יש בסיס לראות בארבע האמות תחום בעל משמעות עצמאית, אבל אין זה מוכיח כשלעצמו שהן תמיד תחום חדש הנמדד שתי אמות לכל צד ממקום עמידת הרגליים, או שהן „כאלפים” בכל המובנים. יש להבחין בין שיעור ארבע האמות, מיקומן סביב האדם, מעמדן כתחום לעניין חפצים, והאיסור לצאת מהן בהילוך. בפרט, ההמשך על חצי מערה עוסק במדידת תחום ובמקום שאליו נמשכת המדידה; יש להסביר מדוע אותו מנגנון חל גם על ארבע האמות שניתנו למי שהוציאוהו.\u003c/p>", "t": "concept", "sv": 3}, {"id": "680", "n": 23, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-056 | חומרה: קריטית | קטגוריה: שלושת רכיבי איסור תחומין — הבחנה בין האדם, חפציו ומקום השביתה. המשפט המסכם „איסור תחומין מורכב משלושה חלקים, הדבר, מקום הדבר, והמעשה בדבר ובמקומו” דורש הגדרה חדה של כל רכיב. לאורך היחידה מתחלפים כאן שלושה נושאים שאינם זהים: הילוך האדם מחוץ לתחומו; תחום ארבע האמות שניתנו לגופו; וטלטול חפציו, שלגביו עשויה להיות משמעות לשביתת הבעלים או לשביתת החפץ. אם „הדבר” הוא האדם, יש להסביר מדוע ניסוח האיסור הוא הוצאת „דבר” ממקומו; ואם „הדבר” כולל גם חפצים, יש להבחין בין איסור תחומין של האדם לבין דיני תחום החפצים. גם „המעשה בדבר ובמקומו” אינו מובן עדיין: האם זהו מעשה ההילוך, שינוי מקום אובייקטיבי, או הוצאה של חפץ מרשות/תחום? מוצע להגדיר במפורש את שלושת הרכיבים ולבדוק כל אחד מהם בנפרד מול סוגיית הבקעה, דיר וסהר והספינה, כדי שלא תיווצר החלפה סמויה בין גופו של האדם לבין חפציו.\u003c/p>", "t": "concept", "sv": 2}, {"id": "681", "n": 24, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-057 | חומרה: קריטית | קטגוריה: הוצרך לנקביו — כבוד הבריות ודין „עייל לתחומא” אינם מוכיחים שאין כאן מעשה הילוך. יש להיזהר מן המעבר מלשון הסוגיה למסקנה שהיציאה „אינה נחשבת הילוך שלו”. בעירובין מא ע״ב רבא משיב על שאלת הנצרך לנקביו: „גדול כבוד הבריות שדוחה את לא תעשה שבתורה”; נהרדעי מוסיפים „אי פיקח הוא עייל לתחומא וכיון דעל על”. רש״י מפרש שהותר לו לצאת מארבע אמותיו לצורך זה, ואם נכנס לתחומו — שוב נחשב כאילו לא יצא, משום שיצא ברשות. אין כאן אמירה מפורשת שהאדם אינו הולך, שהילוכו מיוחס לאדם אחר, או שהפעולה אינה מעשה שלו. ההיתר יכול להיות היתר למעשה אסור מחמת כבוד הבריות, בלי לשנות את הגדרת ההילוך או את ייחוסו. אם כוונתך לחדש שכבוד הבריות מפקיע את עצם שם ההילוך, יש להביא לכך מקור נוסף ולהסביר מדוע אין די בהסבר הפשוט של היתר וחזרה ברשות.\u003c/p>", "t": "source", "sv": 2}, {"id": "682", "n": 25, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-058 | חומרה: קריטית | קטגוריה: רבה ור׳ זירא בספינה — „שבת באוויר מחיצות מבעוד יום” ותלותה בקניית שביתה. המהלך כאן מחדש ש„שבת באוויר מחיצות מבעוד יום” אינו תלוי כלל בקניית שביתה, אך יש לבסס זאת מול לשון הסוגיה. בעירובין מב ע״ב רבה מנמק את ההיתר בספינה בכך „הואיל ושבת באוויר מחיצות מבעוד יום”; הגמרא מבחינה בין טעם רבה לבין טעם ר׳ זירא, ובודקת נפקא מינה בנפחתו דופני הספינה או בקופץ מספינה לספינה. בהמשך נשאל מדוע ר׳ זירא אינו אומר כרבה, והתשובה היא „מחיצות להבריח מים עשויות”. מכאן שהזמן „מבעוד יום” והימצאות האדם באוויר המחיצות הם רכיבים מפורשים בטעם רבה. כדי לטעון שאין מדובר בקניית שביתה, יש להגדיר מה בדיוק נקבע מבעוד יום — אחדות האוויר, מעמד המחיצות, או מקום השימוש — ולהראות מדוע קביעה זו נשארת גם כשאין קניית שביתה בספינה המהלכת. כמו כן, יש להבהיר כיצד הקריאה מתיישבת עם נפקא מינות הגמרא, ולא רק להעמיד את „שבת” במשמעות מופשטת של נוכחות.\u003c/p>", "t": "concept", "sv": 3}, {"id": "683", "n": 26, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-059 | חומרה: גבוהה | קטגוריה: עירוב בעיר — ראיה לאחדות מקום השביתה או דין מיוחד של עיר מיושבת. הראיה מעירובו בעיר אחרת צריכה להבחין בין שני דינים. בעירובין סא ע״ב נידון מי ששבת בעיר לעומת מי שהניח את עירובו בעיר; שם מובאת גם מחלוקת ר׳ עקיבא, והגמרא מבחינה בין „שבת בעיר” לבין „הניח את עירובו בעיר”. אכן יש מכאן בסיס להבחנה בין מקום שביתה בפועל לבין נקודת עירוב שנבחרה, אך אין זה מוכיח לבדו שכל מקום מוקף נעשה „מקום שביתתו בכל המקום” מכוח אחדות האוויר, כפי שאתה מבקש ללמוד. עיר היא מקום מיושב שיש בו דין עיר, ואילו הסוגיה שלך עוסקת גם בדיר, סהר וספינה ובמחיצות שאינן בהכרח מחיצות דירה. יש להסביר מדוע דין העיר הוא ראיה למנגנון הכללי של מקום מוקף, ולא דין מיוחד של שביתה בעיר; וכן לדייק אם „כל העיר כד׳ אמות” הוא תוצאה של מקום השביתה או של דין העיר כיחידה אחת.\u003c/p>", "t": "source", "sv": 3}, {"id": "684", "n": 27, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-060 | חומרה: קריטית | קטגוריה: מחיצות קרקע לעומת מחיצות אוויר — חסר שלב מקשר בהיתר ההילוך. זהו שלב מרכזי במהלך, אך כרגע יש בו קושי פנימי שדורש גישור מפורש. בפסקאות הקודמות הוגדר איסור ההילוך כקשור ל„אוויר” — מקום השימוש והמעבר — ואילו כאן נאמר שלרבה די במחיצות קרקע, ואין צורך במחיצות אוויר. אולם אם מחיצות הקרקע מגדירות רק את הקרקע כמקום אחד, כיצד הן מגדירות גם את האוויר שבו מתרחש ההילוך, ובפרט כאשר לשיטתך הילוך אינו תלוי בקרקע? מנגד, בגמרא עירובין מג ע״א נאמר על מחיצות הספינה „להבריח מים עשויות”, ורש״י מפרש שאינן נחשבות מחיצות לעשות את הספינה כולה כארבע אמות; זו בדיוק נקודת הקושי בטעם רבה. יש לבאר מה ההבדל בין „מחיצות קרקע” שמספיקות לשיטת רבה לבין מחיצות הספינה שנדחו כ„להבריח מים”, והאם שביתה מבעוד יום היא שמקשרת בין הקרקע לאוויר. בלי שלב זה, נראה שהפסקה מניחה את המבוקש: היא מסבירה היתר הילוך באמצעות מחיצות שאינן מחיצות של מקום ההילוך.\u003c/p>", "t": "concept", "sv": 2}, {"id": "685", "n": 28, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-061 | חומרה: קריטית | קטגוריה: פירוש רש״י בספינה — תנועת הספינה והקניית ארבע אמות חדשות. יש לדייק את גבולות הראיה מרש״י. בעירובין מב ע״ב רש״י מפרש את „ספינה נוטלתו מתחילת ארבע ומנחתו בסוף ארבע” כך שכאשר האדם עוקר את רגלו, הספינה מוציאה אותו בעל כורחו מארבע האמות שלו ומניחה אותו בארבע אמות אחרות; הרי הוא כמי שהוציאוהו נכרים ונתנוהו במקום אחר, שנותנים לו ארבע אמות וכן לעולם. זה תומך בהבחנה בין תנועת האדם לבין העתקתו על ידי הספינה, אך אינו אומר במפורש שארבע האמות שעל קרקע הספינה מועילות רק לעמידה ולא להילוך, או שהילוך צעד בתוך הספינה אינו נחשב הילוך מפני שהאדם נשאר באותן ארבע אמות. יש להפריד בין שלושה מצבים: הליכת האדם בתוך ארבע אמותיו; תנועת הספינה כשהוא עוקר רגלו; ועמידת הספינה לאחר שהועתק למקום חדש. כמו כן, רש״י מביא כמה לשונות בפירוש „נוטלתו”, ובסוף מציין „וזה עיקר”; יש לבסס את המהלך על הלשון העיקרית ולא לערבב בינה לבין הלשונות האחרות.\u003c/p>", "t": "source", "sv": 3}, {"id": "686", "n": 29, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-062 | חומרה: קריטית | קטגוריה: שביתת הספינה — שיטת המאירי לעומת הצורך שהספינה תעמוד בבין השמשות. יש כאן שני מהלכים ראשוניים שצריך להפריד ביניהם. המאירי בעירובין מג ע״א (בדבריו על הספינה והמים הנדים) כותב במפורש „איהו מינח נייח וספינה הוא דקא מסגיא”, ומדמה זאת ל„חצר מהלכת”; זו אסמכתה ישירה לחילוק שאתה מציע בין תנועת הספינה לבין הילוך האדם. אולם הרשב״א שם (מג ע״א) מבאר את מעשה ספינתו של רבן גמליאל בכך שהספינה „כל בין השמשות מינח ניחא”, כלומר היא עמדה בזמן קניית השביתה. אלה אינם בהכרח אותו הסבר: המאירי מדגיש שהאדם אינו מהלך, ואילו הרשב״א מעמיד את קניית השביתה על עמידת הספינה בבין השמשות. יש לציין במפורש שאתה מאמץ את שיטת המאירי או מציע צירוף חדש, ולהסביר אם „ניידי” פוסל את קניית שביתת המים בלבד, את קניית שביתת הספינה, או גם את קניית שביתת האדם שעליה. בלי ההבחנה הזאת נוצר רושם שהמקורות מסכימים על מנגנון אחד, בעוד שהם מציגים מסלולים שונים.\u003c/p>", "t": "source", "sv": 2}, {"id": "687", "n": 30, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-063 | חומרה: גבוהה | קטגוריה: מקום מסוים — התנאים המדויקים של תל/בקעה וההיקש לספינה. הראיה מעירובין נ ע״ב צריכה להביא את מלוא תנאי הברייתא: „במקום המסויים כגון ששבת בתל שהוא גבוה עשרה טפחים והוא מד׳ אמות ועד בית סאתים, וכן בקעה שהיא עמוקה עשרה והיא מד׳ אמות ועד בית סאתים”. רש״י מסביר שבמקום מוקף ומסוים כזה כל המקום נחשב כארבע אמות, ולכן אין צורך לסיים בו ארבע אמות מסוימות. אין זו קביעה כללית שכל מקום בעל גבולות פיזיים נעשה מקום שביתה אחד. בפרט, בספינה יש להבחין בין גבולות הספינה עצמה, מקום עמידת האדם ביחס לקרקע הים, והשטח המוגדר לעניין דין „מקום מסוים”; ואם הספינה גדולה מבית סאתיים, תנאי הברייתא אינו מתקיים כפשוטו. יש לבאר מהו בדיוק המושא שנחשב מסוים בספינה, ומדוע תנועתה אינה פוגעת בסיום המקום, לפני שמסיקים שאין צורך בסיום ארבע אמות.\u003c/p>", "t": "source", "sv": 3}, {"id": "688", "n": 31, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-064 | חומרה: קריטית | קטגוריה: עמוד רחב ארבעה — „חזי להילוך” לעומת מקום עמידה שממנו אפשר לצאת להילוך. כאן חשוב לדייק בלשון רש״י בעירובין מג ע״א. על עמוד גבוה עשרה ורחב ארבעה הוא כותב „דהא חזי להילוך והילוך מעליא הוא”; ועל עמוד שאינו רחב ארבעה — „דלא ניחא תשמישתיה”. כלומר, בפשטות מדובר במשטח הראוי להילוך עליו, ולא רק במקום עמידה שממנו אפשר להתחיל ללכת. אתה מחדש ש„חזי להילוך” פירושו מקום הראוי להיות עמדת הילוך, ולא מקום ההילוך עצמו. זה עשוי להיות יסוד חשוב בשיטתך, אך יש להראות מדוע לשון „הילוך מעליא” אינה מתפרשת כפשוטה, ומה הקשר בין שיעור ארבעה טפחים בעמוד לבין שיעור ארבע אמות של תחום. כרגע המעבר בין שני השיעורים ובין „מקום עמידה” ל„מקום הילוך” אינו מבואר דיו.\u003c/p>", "t": "concept", "sv": 2}, {"id": "689", "n": 32, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-065 | חומרה: קריטית | קטגוריה: רגל אחת או שתיים — דרשת „רגלך” מול דין רוב הגוף. בסוגיית עירובין נב ע״ב מובאת מחלוקת מפורשת: ר׳ חנינא דורש „רגלך כתיב” ולפיו רגל אחת מחוץ לתחום מונעת כניסה; הברייתא המתירה להיכנס מתפרשת כשיטת „אחרים”, שאומרים „למקום שרובו הוא נזקר”, ורש״י מפרש שהולכים אחר רוב הגוף. בפסקה זו אתה מפרש את המחלוקת דרך „עמידת פסיעה” לעומת עמידת שתי רגליים, ומייחס לה משמעות ביחס להילוך עתידי ולמקום העמידה. זהו חידוש מעבר לפשט הסוגיה, שמנסחת את ההכרעה במפורש לפי רוב הגוף. יש להראות כיצד פירושך משמר את דין „למקום שרובו הוא נזקר”, או להבהיר שאתה מציע קריאה אחרת בדרשת „רגלך” ולא את פירוש הברייתא המקובל. כמו כן, יש להבחין בין השאלה אם האדם כבר יצא מתחומו לצורך חזרתו, לבין השאלה המושגית מה נחשב עמידה או פסיעה; אין להסיק מן הראשונה לבדה את הגדר של האחרונה.\u003c/p>", "t": "source", "sv": 3}, {"id": "690", "n": 33, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-066 | חומרה: גבוהה | קטגוריה: „יצא ברשות” מול „יצא לדבר מצוה” — הבחנה בין מעמד היציאה לבין טעמה. ההבחנה שאתה מציע בין לשון המשנה „יצא ברשות” לבין לשון אביי „לדבר מצוה” עשויה להועיל לניתוח שני הדינים, אך צריך להיזהר שלא להציג את המשנה כאילו אינה עוסקת ביציאה לצורך מצווה. המשנה עצמה מסיימת „כל היוצאין להציל חוזרין למקומן”, ורש״י מפרט גם עדות החודש, הצלה מן הגייס או מן הנהר וחכמה הבאה לילד. לכן „ברשות” הוא מעמד היציאה מבחינת ההיתר והקניית התחום, אבל המקרה עשוי להיות בו בזמן מעשה מצווה. אפשר לומר שהמשנה דנה בתוצאת ההימצאות במקום ואביי בטעם ההיתר לחזור, אך יש לנסח זאת כהבחנה בין שני מישורי ניתוח של אותו מעשה, ולא כניגוד בין יציאה ברשות לבין יציאה למצווה. ראוי גם לעגן את החילוק במהלך הגמרא בעירובין מד ע״ב–מה ע״א, שבו רבה ורב שימי נחלקים בפירוש „כאילו לא יצא” ואביי מביא את דין ר׳ אליעזר.\u003c/p>", "t": "concept", "sv": 2}, {"id": "691", "n": 34, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-067 | חומרה: קריטית | קטגוריה: „מצי למישקליה” בעירוב — נגישות ממשית לעומת הגדרת „מקום אחד”. יש להפריד בין לשון הסוגיה לבין ההגדרה שאתה מציע לה. בעירובין לה ע״א רבא מבחין בין עירוב שנתגלגל חוץ לארבע אמות לבין עירוב שנשאר בתוך ארבע אמות, שאז „הנותן עירובו יש לו ארבע אמות”. רש״י בעירובין לב ע״ב מסביר שארבע האמות שסביב העירוב נחשבות כמוקפות מחיצות וכבית, ולכן אפשר להביא את העירוב מן החלק שמחוץ לתחום אל החלק שבתוכו. מכאן יש בסיס למעמד של „מקום אחד”, אבל אין למחוק את רכיב הנגישות הממשית העולה מלשון „מצי למישקליה”. בפסקה אתה הופך אותו לתנאי משפטי של היות האדם והעירוב במקום אחד, גם כאשר אין איסור תחומין ישיר. יש להסביר האם „מצי למישקליה” הוא תנאי עצמאי של אפשרות נטילה, או רק תוצאה של ההגדרה המרחבית; אחרת ההסבר עלול להיות מעגלי — העירוב נחשב באותו מקום מפני שאפשר לקחתו, ואפשר לקחתו מפני שהוא באותו מקום. כמו כן, יש ליישב את דבריך עם פירוש רש״י שהארבע אמות סביב העירוב מתפקדות כבית/מחיצות.\u003c/p>", "t": "concept", "sv": 2}, {"id": "692", "n": 35, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-068 | חומרה: קריטית | קטגוריה: הבלעת תחומין במערה — פירוש „שבת באוויר מחיצות” והראשונים החולקים. הגמרא בעירובין מד ע״ב משיבה לאביי: „ולא שני לך בין היכא דשבת באוויר מחיצות מבעוד יום להיכא דלא שבת באוויר מחיצות מבעוד יום”. אתה מפרש זאת כיצירת גבול קבוע של אלפיים אמה עוד קודם ההילוך, המאפשר להבחין בין תחום פנימי לתחום חיצוני. זהו פירוש מושגי, אך יש להביא בחשבון שהראשונים דנו במפורש במשמעות התשובה. הרשב״א שם מביא את פירוש הראב״ד שמחיצות המערה נחשבות כבית ורשותה עולה עד לרקיע, ולאחר מכן מקשה עליו מכמה סוגיות; הוא מביא גם את חילוק התוספות בין מי שקנה ארבע אמות חדשות מחוץ לתחום לבין מי שעקר את תחומו הראשון וקנה תחום אחר. לכן אין להציג את „הגבול הקבוע” כמסקנה פשוטה מלשון הגמרא. יש לציין לאיזו שיטת ראשונים אתה מתייחס, כיצד אתה מתמודד עם קושיות הרשב״א, ומהו ההבדל המדויק בין תחום שנקנה במקום חדש לבין תחום שהיה מובלע בתחום הראשון.\u003c/p>", "t": "source", "sv": 3}]};
